    #[test]
    fn a_project_of_several_files_becomes_a_package_that_verifies() {
        const MAIN: &str = r#"
package com.tr.yt.several;

import android.app.Activity;
import android.os.Bundle;

public final class MainActivity extends Activity {

    private Counter counter;

    @Override
    protected void onCreate(Bundle state) {
        super.onCreate(state);
        counter = new Doubling();
        counter.add(2);
    }

    public int reached() {
        return counter.total();
    }
}
"#;
        const COUNTER: &str = r#"
package com.tr.yt.several;

class Counter {

    private int total;

    void add(int by) {
        total = total + step(by);
    }

    int total() {
        return total;
    }

    private int step(int by) {
        return by;
    }
}
"#;
        const DOUBLING: &str = r#"
package com.tr.yt.several;

final class Doubling extends Counter {

    @Override
    void add(int by) {
        super.add(by * 2);
    }
}
"#;

        let directory = temp_directory("omni-several");
        let root = directory.join("Several");
        let folder = root.to_str().unwrap().to_string();
        crate::scaffold::create(
            &folder,
            &crate::scaffold::Spec {
                package: "com.tr.yt.several".to_string(),
                label: "Several".to_string(),
                languages: vec!["java".to_string()],
                min_sdk: 30,
                target_sdk: 36,
                ..Default::default()
            },
        )
        .expect("the project must be made");

        let sources = root.join("Java");
        std::fs::create_dir_all(&sources).unwrap();
        for (name, text) in [
            ("MainActivity.java", MAIN),
            ("Counter.java", COUNTER),
            ("Doubling.java", DOUBLING),
        ] {
            std::fs::write(sources.join(name), text.trim_start()).unwrap();
        }

        let project = crate::builder::from_project(&folder)
            .unwrap_or_else(|error| panic!("the project did not compile: {error}"));
        let named: Vec<&str> = project
            .code
            .iter()
            .map(|held| held.descriptor.as_str())
            .collect();
        for wanted in [
            "Lcom/tr/yt/several/MainActivity;",
            "Lcom/tr/yt/several/Counter;",
            "Lcom/tr/yt/several/Doubling;",
        ] {
            assert!(
                named.contains(&wanted),
                "{wanted} is missing from {named:?}"
            );
        }

        let calls = |class: &str, method: &str| -> Vec<u8> {
            project
                .code
                .iter()
                .filter(|one| one.descriptor.ends_with(class))
                .flat_map(|one| one.direct_methods.iter().chain(one.virtual_methods.iter()))
                .filter(|one| one.reference.name == method)
                .flat_map(|one| one.instructions.iter())
                .filter_map(|one| match &one.operand {
                    crate::dexwrite::Operand::Method(_) => {
                        Some((one.units.first().copied().unwrap_or_default() & 0xff) as u8)
                    }
                    _ => None,
                })
                .collect()
        };
        assert!(
            calls("Doubling;", "add").contains(&0x6f),
            "a call up into the superclass stays a call up across files"
        );
        assert!(
            calls("Counter;", "add").contains(&0x70),
            "a private method stays a call inward across files"
        );

        let key = crate::rsa::generate(2048).expect("a key");
        let certificate = crate::certificate::self_signed(
            &key,
            "Several",
            "Omni",
            "TR",
            crate::certificate::moment_from_epoch(1_700_000_000),
            crate::certificate::moment_from_epoch(2_000_000_000),
        )
        .expect("a certificate");
        let mut sink = Sink::new();
        let outcome = crate::builder::assemble(&project, &key, &certificate, &mut sink)
            .expect("the project must package");
        assert!(outcome.carries_code);
        assert!(outcome.verified.everything_checkable_passed());

        let path = directory.join("several.apk");
        std::fs::write(&path, &outcome.package).unwrap();
        let found = crate::inspect::package(path.to_str().unwrap()).expect("it must open");
        assert_eq!(found.package, "com.tr.yt.several");
        assert_eq!(found.dex_files, 1);
        assert!(found.sound);

        std::fs::remove_dir_all(&directory).ok();
    }

