    #[test]
    fn der_refuses_every_encoding_the_rules_forbid() {
        let cases: &[(&[u8], &str)] = &[
            (&[0x30, 0x80, 0x00, 0x00], "ED002"),
            (&[0x30, 0x81, 0x00], "ED004"),
            (&[0x30, 0x81, 0x01, 0x00], "ED005"),
            (&[0x1f, 0x01, 0x00], "ED001"),
            (&[0x30, 0x05, 0x00], "ED007"),
        ];
        for (bytes, code) in cases {
            let mut reader = crate::der::Reader::new(bytes, 0);
            let error = reader.next_element().unwrap_err();
            assert_eq!(error.code, *code, "{bytes:?}");
        }

        let padded = crate::der::Element {
            tag: crate::der::tag::INTEGER,
            contents: &[0x00, 0x01],
            offset: 0,
            total: 4,
        };
        assert_eq!(
            crate::der::read_integer_bytes(&padded).unwrap_err().code,
            "ED032"
        );
    }

    #[test]
    fn der_reads_object_identifiers_the_way_the_encoding_defines_them() {
        let cases: &[(&[u8], &str)] = &[
            (&[0x06, 0x03, 0x55, 0x04, 0x03], "2.5.4.3"),
            (
                &[
                    0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x0b,
                ],
                "1.2.840.113549.1.1.11",
            ),
            (
                &[0x06, 0x07, 0x2a, 0x86, 0x48, 0xce, 0x3d, 0x04, 0x03],
                "1.2.840.10045.4.3",
            ),
        ];
        for (bytes, expected) in cases {
            let mut reader = crate::der::Reader::new(bytes, 0);
            let element = reader.next_element().unwrap();
            assert_eq!(crate::der::read_oid(&element).unwrap(), *expected);
        }

        for bad in [
            &[0x06u8, 0x02, 0x55, 0x80][..],
            &[0x06, 0x03, 0x55, 0x80, 0x01][..],
        ] {
            let mut reader = crate::der::Reader::new(bad, 0);
            let element = reader.next_element().unwrap();
            assert!(crate::der::read_oid(&element).is_err(), "{bad:?}");
        }
    }

    #[test]
    fn der_survives_arbitrary_input() {
        let mut seed = 0xaaaa_5555_cccc_3333u64;
        for _ in 0..3_000 {
            let length = (xorshift(&mut seed) % 120) as usize;
            let bytes: Vec<u8> = (0..length)
                .map(|_| (xorshift(&mut seed) & 0xff) as u8)
                .collect();
            let mut reader = crate::der::Reader::new(&bytes, 0);
            for _ in 0..64 {
                match reader.next_element() {
                    Ok(element) => {
                        assert!(element.contents.len() <= bytes.len());
                        let _ = crate::der::read_oid(&element);
                        let _ = crate::der::read_string(&element);
                        let _ = crate::der::read_integer_bytes(&element);
                    }
                    Err(_) => break,
                }
                if reader.is_empty() {
                    break;
                }
            }
        }
    }

    #[test]
    fn a_certificate_reads_as_the_tools_read_it() {
        let certificate = Certificate::parse(CONFORMANCE_CERTIFICATE).expect("must parse");

        assert_eq!(certificate.subject, "C=TR, O=Omni, CN=Omni Conformance");
        assert_eq!(certificate.issuer, certificate.subject, "it is self-signed");
        assert_eq!(certificate.serial, "5D97B82E9226CBB1");
        assert_eq!(certificate.public_key_algorithm.display(), "RSA");
        assert_eq!(certificate.public_key_bits, Some(2048));
        assert!(certificate.signature_algorithm.is_known());

        assert_eq!(
            certificate.fingerprint.to_hex(),
            "a7259d236ba6819af41ef78ed77ed17804f07ec9edce8294a5ff380558289fbe"
        );
        assert!(certificate
            .fingerprint_display()
            .starts_with("A7:25:9D:23:6B:A6:81:9A"));

        assert!(certificate.not_before.ends_with("UTC"));
        assert!(certificate.not_after > certificate.not_before);
    }

    #[test]
    fn sha384_matches_the_published_vectors() {
        assert_eq!(
            crate::hash::sha384(b"").to_hex(),
            "38b060a751ac96384cd9327eb1b1e36a21fdb71114be07434c0cc7bf63f6e1da\
             274edebfe76f65fbd51ad2f14898b95b"
                .replace(char::is_whitespace, "")
        );
        assert_eq!(
            crate::hash::sha384(b"abc").to_hex(),
            "cb00753f45a35e8bb5a03d699ac65007272c32ab0eded1631a8b605a43ff5bed\
             8086072ba1e7cc2358baeca134c825a7"
                .replace(char::is_whitespace, "")
        );
        assert_eq!(
            crate::hash::sha384(
                b"abcdefghbcdefghicdefghijdefghijkefghijklfghijklmghijklmn\
                  hijklmnoijklmnopjklmnopqklmnopqrlmnopqrsmnopqrstnopqrstu"
                    .iter()
                    .copied()
                    .filter(|byte| !byte.is_ascii_whitespace())
                    .collect::<Vec<u8>>()
                    .as_slice()
            )
            .to_hex(),
            "09330c33f71147e83d192fc782cd1b4753111b173b3b05d22fa08086e3b0f712\
             fcc7c71a557e2db966c3e9fa91746039"
                .replace(char::is_whitespace, "")
        );

        let long: Vec<u8> = std::iter::repeat_n(b'a', 1_000_000).collect();
        assert_eq!(
            crate::hash::sha384(&long).to_hex(),
            "9d0e1809716474cb086e834e310a4a1ced149e9c00f248527972cec5704c2a5b\
             07b8b3dc38ecc4ebae97ddd87f3d8985"
                .replace(char::is_whitespace, "")
        );
    }

    #[test]
    fn a_self_signed_certificate_is_checked_against_its_own_key() {
        let held =
            crate::x509::own_signature(CONFORMANCE_CERTIFICATE).expect("the certificate reads");
        assert!(
            held.self_issued,
            "the conformance certificate is self-signed"
        );
        assert!(held.checkable, "and it is signed with RSA over SHA-384");
        assert!(
            held.holds,
            "a certificate another tool signed must verify here"
        );
        assert!(held.nothing_wrong());

        let mut altered = CONFORMANCE_CERTIFICATE.to_vec();
        let at = altered.len() / 3;
        altered[at] ^= 0x01;
        if let Ok(said) = crate::x509::own_signature(&altered) {
            assert!(
                !said.holds || !said.checkable,
                "a certificate altered after it was signed cannot still hold"
            );
        }

        let key = crate::rsa::generate(2048).expect("a key");
        let mine = crate::certificate::self_signed(
            &key,
            "Omni Extensions",
            "Omni",
            "TR",
            crate::certificate::moment_from_epoch(1_700_000_000),
            crate::certificate::moment_from_epoch(2_000_000_000),
        )
        .expect("a certificate");

        let said = crate::x509::own_signature(&mine).expect("it reads");
        assert!(said.self_issued && said.checkable && said.holds);

        let read = crate::x509::Certificate::parse(&mine).expect("it parses");
        assert_eq!(read.subject, "C=TR, O=Omni, CN=Omni Extensions");
        assert_eq!(read.issuer, read.subject);
        assert_eq!(read.public_key_bits, Some(2048));

        for (name, oid) in [
            ("subject key identifier", [0x06u8, 0x03, 0x55, 0x1d, 0x0e]),
            ("key usage", [0x06, 0x03, 0x55, 0x1d, 0x0f]),
            ("basic constraints", [0x06, 0x03, 0x55, 0x1d, 0x13]),
            ("authority key identifier", [0x06, 0x03, 0x55, 0x1d, 0x23]),
            ("extended key usage", [0x06, 0x03, 0x55, 0x1d, 0x25]),
        ] {
            assert!(
                mine.windows(oid.len()).any(|held| held == oid),
                "the certificate carries no {name}"
            );
        }

        if let Some(tool) = openssl() {
            let directory = temp_directory("omni-certificate-extensions");
            let der = directory.join("mine.der");
            std::fs::write(&der, &mine).unwrap();
            let shown = std::process::Command::new(&tool)
                .args([
                    "x509",
                    "-inform",
                    "DER",
                    "-in",
                    der.to_str().unwrap(),
                    "-noout",
                    "-text",
                ])
                .output()
                .expect("openssl runs");
            assert!(
                shown.status.success(),
                "openssl would not read this certificate:\n{}",
                String::from_utf8_lossy(&shown.stderr)
            );
            let said = String::from_utf8_lossy(&shown.stdout);
            for wanted in [
                "X509v3 Subject Key Identifier",
                "X509v3 Authority Key Identifier",
                "X509v3 Basic Constraints: critical",
                "X509v3 Key Usage: critical",
                "Digital Signature",
                "Code Signing",
            ] {
                assert!(
                    said.contains(wanted),
                    "openssl does not report {wanted}:\n{said}"
                );
            }
            eprintln!("certificate: openssl reads every extension this writes");
            std::fs::remove_dir_all(&directory).ok();
        }
    }

    #[test]
    fn a_certificate_never_claims_its_signature_was_checked() {
        let certificate = Certificate::parse(CONFORMANCE_CERTIFICATE).unwrap();
        let mut w = Writer::new();
        w.begin_array(None);
        certificate.write_json(&mut w);
        w.end_array();
        let document = w.finish();

        assert!(is_structurally_valid(&document));
        assert!(document.contains("\"signatureChecked\":false"));
    }

    #[test]
    fn a_damaged_certificate_is_refused_rather_than_half_read() {
        let mut sink_count = 0;
        for position in [0usize, 1, 4, 40, 200, 500] {
            let mut damaged = CONFORMANCE_CERTIFICATE.to_vec();
            damaged[position] ^= 0xff;
            if Certificate::parse(&damaged).is_err() {
                sink_count += 1;
            }
        }
        assert!(sink_count > 0, "damaging a certificate must be noticed");

        assert!(Certificate::parse(&[]).is_err());
        assert!(Certificate::parse(&[0x30, 0x00]).is_err());
        assert!(Certificate::parse(&CONFORMANCE_CERTIFICATE[..100]).is_err());
    }

    #[test]
    fn certificate_parsing_survives_arbitrary_input() {
        let mut seed = 0x9999_1111_2222_3333u64;
        for _ in 0..2_000 {
            let mut bytes = CONFORMANCE_CERTIFICATE.to_vec();
            let mutations = (xorshift(&mut seed) % 8) + 1;
            for _ in 0..mutations {
                let position = (xorshift(&mut seed) as usize) % bytes.len();
                bytes[position] = (xorshift(&mut seed) & 0xff) as u8;
            }
            let _ = Certificate::parse(&bytes);
        }
    }

    #[test]
    fn a_package_without_a_signing_block_is_reported_as_such() {
        let mut builder = ArchiveBuilder::new();
        builder.add("a.txt", b"x".to_vec()).unwrap();
        let bytes = builder.finish().unwrap();
        let archive = archive::read(&bytes, &mut Sink::new()).unwrap();

        let mut sink = Sink::new();
        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );

        assert!(!report.has_block);
        assert!(!report.everything_checkable_passed());
        assert!(sink.entries().iter().any(|d| d.code == "ES030"));
    }

    fn find_build_tool(tool: &str) -> Option<std::path::PathBuf> {
        find_apksigner().and_then(|path| {
            let candidate = path.parent()?.join(tool);
            candidate.is_file().then_some(candidate)
        })
    }

    pub(crate) fn find_apksigner() -> Option<std::path::PathBuf> {
        let mut roots: Vec<std::path::PathBuf> = Vec::new();
        for name in ["ANDROID_HOME", "ANDROID_SDK_ROOT"] {
            if let Ok(value) = std::env::var(name) {
                if !value.is_empty() {
                    roots.push(std::path::PathBuf::from(value));
                }
            }
        }
        roots.push(std::path::PathBuf::from("/opt/android-sdk"));
        roots.push(std::path::PathBuf::from("/usr/local/lib/android/sdk"));
        if let Ok(home) = std::env::var("HOME") {
            roots.push(std::path::PathBuf::from(home).join("Android/Sdk"));
        }

        for root in roots {
            let Ok(entries) = std::fs::read_dir(root.join("build-tools")) else {
                continue;
            };
            let mut versions: Vec<std::path::PathBuf> = entries
                .filter_map(|entry| entry.ok())
                .map(|entry| entry.path())
                .collect();
            versions.sort();
            for version in versions.into_iter().rev() {
                let candidate = version.join("apksigner");
                if candidate.is_file() {
                    return Some(candidate);
                }
            }
        }

        assert!(
            std::env::var("OMNI_REQUIRE_APKSIGNER").is_err(),
            "OMNI_REQUIRE_APKSIGNER is set but no apksigner was found, so the \
             signing conformance tests would have skipped silently"
        );
        None
    }

    fn sign_with_apksigner(label: &str) -> Option<(Vec<u8>, std::path::PathBuf)> {
        sign_with_apksigner_using(label, 2048)
    }

    #[test]
    fn a_key_this_build_never_sees_can_still_sign_what_it_makes() {
        let Some(openssl) = openssl() else {
            eprintln!("device signing: openssl is not available here");
            return;
        };

        let directory = temp_directory("omni-device-signing");
        std::fs::create_dir_all(&directory).unwrap();
        let key = directory.join("key.pem");
        let certificate = directory.join("cert.pem");
        let der = directory.join("cert.der");

        let made = std::process::Command::new(&openssl)
            .args([
                "req",
                "-x509",
                "-newkey",
                "rsa:2048",
                "-nodes",
                "-days",
                "3650",
                "-subj",
                "/CN=Omni Device/O=Omni/C=TR",
                "-keyout",
                key.to_str().unwrap(),
                "-out",
                certificate.to_str().unwrap(),
            ])
            .output()
            .unwrap();
        if !made.status.success() {
            eprintln!("device signing: openssl would not make a key");
            std::fs::remove_dir_all(&directory).ok();
            return;
        }
        assert!(std::process::Command::new(&openssl)
            .args([
                "x509",
                "-in",
                certificate.to_str().unwrap(),
                "-outform",
                "DER",
                "-out",
                der.to_str().unwrap(),
            ])
            .output()
            .unwrap()
            .status
            .success());
        let certificate_der = std::fs::read(&der).unwrap();

        let mut builder = ArchiveBuilder::for_android();
        builder
            .add("AndroidManifest.xml", b"<manifest/>".to_vec())
            .unwrap();
        builder.add("classes.dex", vec![0x2a; 4_000]).unwrap();
        let unsigned = builder.finish().unwrap();

        let range = (30u32, 37u32);
        let asked = signing::to_sign(
            &unsigned,
            &certificate_der,
            crate::rsa::DigestAlgorithm::Sha256,
            Some(range),
        )
        .expect("this build says what has to be signed");
        assert!(!asked.v2.is_empty());
        assert!(
            asked.v3.is_some(),
            "a platform range asks for a v3 signer too"
        );

        let outside = |what: &[u8], name: &str| -> Vec<u8> {
            let payload = directory.join(format!("{name}.bin"));
            let signature = directory.join(format!("{name}.sig"));
            std::fs::write(&payload, what).unwrap();
            let done = std::process::Command::new(&openssl)
                .args([
                    "dgst",
                    "-sha256",
                    "-sign",
                    key.to_str().unwrap(),
                    "-out",
                    signature.to_str().unwrap(),
                    payload.to_str().unwrap(),
                ])
                .output()
                .unwrap();
            assert!(
                done.status.success(),
                "openssl would not sign:\n{}",
                String::from_utf8_lossy(&done.stderr)
            );
            std::fs::read(&signature).unwrap()
        };

        let first = outside(&asked.v2, "v2");
        let second = outside(asked.v3.as_ref().unwrap(), "v3");
        let third = asked
            .v31
            .as_ref()
            .map(|rotated| outside(rotated, "v31"))
            .expect("a range reaching the rotation platform asks for a v3.1 signer");

        let package = signing::with_every_signature(
            &unsigned,
            &certificate_der,
            &asked,
            &first,
            Some(&second),
            Some(&third),
            Some(range),
        )
        .expect("a signature made elsewhere seals the package");

        let mut sink = Sink::new();
        let archive = archive::read(&package, &mut sink).expect("it reads back");
        let report = signing::examine(
            &package,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );
        assert!(report.has_block);
        assert_eq!(report.digests_failed, 0, "{:?}", sink.entries());
        assert!(report.digests_verified > 0);
        assert_eq!(report.signatures_failed, 0, "{:?}", sink.entries());
        assert!(
            report.signatures_verified >= 3,
            "v2, v3 and v3.1 are all signed"
        );
        assert!(report.key_matches_certificate);
        assert!(report.certificates_hold);
        assert!(report.everything_checkable_passed());

        let wrong = outside(b"not what was asked for", "wrong");
        let mut own = Sink::new();
        let bad = signing::with_every_signature(
            &unsigned,
            &certificate_der,
            &asked,
            &wrong,
            Some(&second),
            Some(&third),
            Some(range),
        )
        .expect("the block is still built");
        let held = archive::read(&bad, &mut own).unwrap();
        let refused = signing::examine(
            &bad,
            held.central_directory_offset(),
            held.end_record_offset(),
            &mut own,
        );
        assert!(
            !refused.everything_checkable_passed(),
            "a signature over the wrong bytes must not pass"
        );
        assert!(refused.signatures_failed > 0);

        let mut checked = "not checked";
        if let Some(apksigner) = find_apksigner() {
            let path = directory.join("device.apk");
            std::fs::write(&path, &package).unwrap();
            let out = std::process::Command::new(&apksigner)
                .args([
                    "verify",
                    "--min-sdk-version",
                    "30",
                    "--max-sdk-version",
                    "37",
                    "--print-certs",
                    path.to_str().unwrap(),
                ])
                .output()
                .unwrap();
            let said = format!(
                "{}{}",
                String::from_utf8_lossy(&out.stdout),
                String::from_utf8_lossy(&out.stderr)
            );
            assert!(
                out.status.success(),
                "apksigner refused a package signed by a key this build never saw:\n{said}"
            );
            assert!(said.contains("CN=Omni Device"), "{said}");
            checked = "apksigner verified it";
        }

        eprintln!(
            "device signing: the private key stayed in openssl, this build never \
             read it, and the package it sealed verifies -- {checked}"
        );
        std::fs::remove_dir_all(&directory).ok();
    }

    fn sign_with_apksigner_using(
        label: &str,
        key_bits: u32,
    ) -> Option<(Vec<u8>, std::path::PathBuf)> {
        let apksigner = find_apksigner()?;

        let directory = temp_directory(label);
        let apk = directory.join("sample.apk");
        let keystore = directory.join("k.jks");

        let mut builder = ArchiveBuilder::for_android();
        builder
            .add("AndroidManifest.xml", b"<manifest/>".to_vec())
            .unwrap();
        builder.add("classes.dex", vec![0x2a; 3_000]).unwrap();
        builder
            .add("lib/arm64-v8a/libomni.so", vec![0x7f; 2_000])
            .unwrap();
        std::fs::write(&apk, builder.finish().unwrap()).unwrap();

        let keytool = std::process::Command::new("keytool")
            .args([
                "-genkeypair",
                "-keystore",
                keystore.to_str().unwrap(),
                "-storepass",
                "pass123",
                "-keypass",
                "pass123",
                "-alias",
                "k",
                "-keyalg",
                "RSA",
                "-keysize",
                &key_bits.to_string(),
                "-validity",
                "30",
                "-dname",
                "CN=Omni Test, O=Omni, C=TR",
            ])
            .output()
            .ok()?;
        if !keytool.status.success() {
            std::fs::remove_dir_all(&directory).ok();
            return None;
        }

        let signed = std::process::Command::new(&apksigner)
            .args([
                "sign",
                "--ks",
                keystore.to_str().unwrap(),
                "--ks-pass",
                "pass:pass123",
                "--key-pass",
                "pass:pass123",
                "--ks-key-alias",
                "k",
                "--v1-signing-enabled",
                "false",
                "--v2-signing-enabled",
                "true",
                "--v3-signing-enabled",
                "false",
                "--min-sdk-version",
                &crate::compiler::OLDEST_API.to_string(),
                apk.to_str().unwrap(),
            ])
            .output()
            .ok()?;
        assert!(
            signed.status.success(),
            "apksigner failed: {}",
            String::from_utf8_lossy(&signed.stderr)
        );

        let bytes = std::fs::read(&apk).unwrap();
        Some((bytes, directory))
    }

    #[test]
    fn the_digest_this_build_computes_matches_the_one_apksigner_wrote() {
        let Some((bytes, directory)) = sign_with_apksigner("v2-digest") else {
            eprintln!(
                "signing conformance: apksigner is not available here, so the digest \
                 was not checked against it"
            );
            return;
        };

        let mut sink = Sink::new();
        let archive = archive::read(&bytes, &mut sink).expect("the signed package must read");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );

        assert!(
            report.has_block,
            "apksigner wrote a block and it was not found"
        );
        assert!(
            report.schemes.contains(&"v2"),
            "schemes: {:?}",
            report.schemes
        );
        assert_eq!(report.signers.len(), 1);
        assert_eq!(report.digests_failed, 0, "{:?}", sink.entries());
        assert!(
            report.digests_verified > 0,
            "no digest was recomputed: {:?}",
            sink.entries()
        );
        assert!(report.everything_checkable_passed());

        let certificate = &report.signers[0].certificates[0];
        assert_eq!(certificate.subject, "C=TR, O=Omni, CN=Omni Test");
        assert_eq!(certificate.public_key_bits, Some(2048));

        assert!(
            report.signatures_checked,
            "apksigner's own signature was not checked"
        );
        assert_eq!(report.signatures_failed, 0, "{:?}", sink.entries());
        assert!(
            report.signatures_verified > 0,
            "no signature verified: {:?}",
            sink.entries()
        );
        assert!(report.key_matches_certificate);

        eprintln!(
            "signing conformance: {} digest(s) and {} signature(s) of apksigner's agreed",
            report.digests_verified, report.signatures_verified
        );
        std::fs::remove_dir_all(&directory).ok();
    }

    fn built_package() -> Option<std::path::PathBuf> {
        let mut found: Vec<std::path::PathBuf> =
            std::fs::read_dir("Builder/build/outputs/apk/release")
                .ok()?
                .filter_map(|entry| Some(entry.ok()?.path()))
                .filter(|path| path.extension().is_some_and(|end| end == "apk"))
                .collect();
        found.sort();
        found
            .iter()
            .find(|path| !path.to_string_lossy().ends_with("-unsigned.apk"))
            .or_else(|| found.first())
            .cloned()
    }

    fn package_this_build_produced() -> Option<Vec<u8>> {
        if let Ok(named) = std::env::var("OMNI_PACKAGE_UNDER_TEST") {
            if !named.is_empty() {
                let bytes = std::fs::read(&named)
                    .unwrap_or_else(|why| panic!("OMNI_PACKAGE_UNDER_TEST={named}: {why}"));
                return Some(bytes);
            }
        }
        std::fs::read(built_package()?).ok()
    }

    #[test]
    fn the_package_this_build_produced_reads_and_its_digest_holds() {
        let Some(bytes) = package_this_build_produced() else {
            eprintln!(
                "signing conformance: no built package here, so a real Android \
                 Gradle Plugin package was not read. Build one with \
                 `./gradlew :Builder:assembleRelease` or set \
                 OMNI_PACKAGE_UNDER_TEST."
            );
            return;
        };

        let mut sink = Sink::new();
        let archive = archive::read(&bytes, &mut sink).expect("the package must read");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        assert!(
            archive.entries().len() > 10,
            "a real package has more than a handful of entries"
        );

        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );

        if !report.has_block {
            assert_eq!(report.digests_verified, 0, "{:?}", sink.entries());
            assert_eq!(report.digests_failed, 0, "{:?}", sink.entries());
            assert!(report.schemes.is_empty(), "{:?}", report.schemes);
            eprintln!(
                "signing conformance: {} entries, and no signature — this build \
                 was given no key, so the package it wrote cannot be installed",
                archive.entries().len()
            );
            return;
        }

        assert_eq!(report.digests_failed, 0, "{:?}", sink.entries());
        assert!(report.digests_verified > 0, "{:?}", sink.entries());

        assert!(report.signatures_checked, "{:?}", sink.entries());
        assert_eq!(report.signatures_failed, 0, "{:?}", sink.entries());
        assert!(report.signatures_verified > 0, "{:?}", sink.entries());
        assert!(report.key_matches_certificate);
        assert!(report.everything_checkable_passed());

        eprintln!(
            "signing conformance: {} entries, schemes {:?}, {} digest(s) and \
             {} signature(s) matched",
            archive.entries().len(),
            report.schemes,
            report.digests_verified,
            report.signatures_verified
        );
    }

    #[test]
    fn a_sha512_signed_package_is_checked_rather_than_declined() {
        let Some((bytes, directory)) = sign_with_apksigner_using("v2-sha512", 4096) else {
            eprintln!("signing conformance: apksigner is not available here");
            return;
        };

        let mut sink = Sink::new();
        let archive = archive::read(&bytes, &mut sink).expect("the signed package must read");
        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );

        let algorithms: Vec<&str> = report
            .signers
            .iter()
            .flat_map(|signer| signer.digests.iter().map(|(a, _)| a.name))
            .collect();
        assert!(
            algorithms.iter().any(|name| name.contains("SHA-512")),
            "expected a SHA-512 signature, got {algorithms:?}"
        );
        assert_eq!(report.digests_failed, 0, "{:?}", sink.entries());
        assert_eq!(
            report.digests_unverifiable,
            0,
            "nothing here should be undecidable any more: {:?}",
            sink.entries()
        );
        assert!(report.digests_verified > 0, "{:?}", sink.entries());
        assert_eq!(
            report.signers[0].certificates[0].public_key_bits,
            Some(4096)
        );
        assert!(report.signatures_checked);
        assert_eq!(report.signatures_failed, 0, "{:?}", sink.entries());
        assert!(report.signatures_verified > 0, "{:?}", sink.entries());
        assert!(report.everything_checkable_passed());

        eprintln!(
            "signing conformance: SHA-512, {} digest(s) and {} signature(s) agreed",
            report.digests_verified, report.signatures_verified
        );
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_verity_digest_is_never_compared_against_the_chunked_one() {
        for id in [0x0421u32, 0x0423, 0x0425] {
            let algorithm = signing::algorithm(id).expect("a defined algorithm");
            assert_eq!(
                algorithm.digest,
                signing::DigestKind::VerityMerkle,
                "0x{id:04x} ({}) must not be treated as a chunked digest",
                algorithm.name
            );
        }

        for (id, kind) in [
            (0x0101u32, signing::DigestKind::Chunked256),
            (0x0102, signing::DigestKind::Chunked512),
            (0x0103, signing::DigestKind::Chunked256),
            (0x0104, signing::DigestKind::Chunked512),
            (0x0201, signing::DigestKind::Chunked256),
            (0x0202, signing::DigestKind::Chunked512),
            (0x0301, signing::DigestKind::Chunked256),
        ] {
            assert_eq!(signing::algorithm(id).unwrap().digest, kind, "0x{id:04x}");
        }
    }

    #[test]
    fn changing_one_byte_of_a_signed_package_is_detected() {
        let Some((bytes, directory)) = sign_with_apksigner("v2-tamper") else {
            eprintln!("signing conformance: apksigner is not available here");
            return;
        };

        let archive = archive::read(&bytes, &mut Sink::new()).unwrap();
        let entry = archive.entry("classes.dex").expect("classes.dex");
        let position = entry.data_offset as usize + 10;

        let mut tampered = bytes.clone();
        tampered[position] ^= 0xff;

        let mut sink = Sink::new();
        let archive = archive::read(&tampered, &mut sink).unwrap();
        let report = signing::examine(
            &tampered,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );

        assert!(report.has_block);
        assert_eq!(report.digests_verified, 0);
        assert!(report.digests_failed > 0, "a changed byte must be noticed");
        assert!(!report.everything_checkable_passed());

        let error = sink.entries().iter().find(|d| d.code == "ES033").unwrap();
        assert_eq!(error.severity, Severity::Fatal);
        assert_eq!(error.class, FailureClass::Corruption);
        assert!(error.suggestion.as_deref().unwrap().contains("Do not"));

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_signing_report_says_what_it_checked_and_what_it_did_not() {
        let Some((bytes, directory)) = sign_with_apksigner("v2-report") else {
            return;
        };

        let archive = archive::read(&bytes, &mut Sink::new()).unwrap();
        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut Sink::new(),
        );

        let mut w = Writer::new();
        w.begin_object(None);
        report.write_json(&mut w, "signing");
        w.end_object();
        let document = w.finish();

        assert!(is_structurally_valid(&document), "{document}");
        assert!(document.contains("\"signaturesChecked\":true"));
        assert!(document.contains("\"signaturesVerified\":1"));
        assert!(document.contains("\"signaturesFailed\":0"));
        assert!(document.contains("\"keyMatchesCertificate\":true"));

        assert!(document.contains("ECDSA and DSA"));

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_key_that_is_not_the_certificate_s_key_is_refused() {
        let Some((bytes, directory)) = sign_with_apksigner("v2-swap") else {
            return;
        };

        let archive = archive::read(&bytes, &mut Sink::new()).unwrap();
        let mut sink = Sink::new();
        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );
        let signer = report.signers[0].clone();

        let other = crate::rsa::generate(2048).expect("a key");
        let substituted = signing::Signer {
            public_key: crate::certificate::public_key_info(&other).expect("a public key"),
            ..signer.clone()
        };

        let mut complaints = Sink::new();
        let checked = signing::verify_signer(&substituted, &mut complaints);
        assert!(!checked.key_matches_certificate);
        assert!(checked.signatures.is_empty(), "nothing may be counted");
        let refusal = complaints
            .entries()
            .iter()
            .find(|entry| entry.code == "ES034")
            .expect("the swap must be named");
        assert_eq!(refusal.severity, Severity::Fatal);
        assert_eq!(refusal.class, FailureClass::SecurityFailure);

        let mut quiet = Sink::new();
        assert!(signing::verify_signer(&signer, &mut quiet).key_matches_certificate);

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_signature_that_was_tampered_with_stops_verifying() {
        let Some((bytes, directory)) = sign_with_apksigner("v2-bent") else {
            return;
        };

        let archive = archive::read(&bytes, &mut Sink::new()).unwrap();
        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut Sink::new(),
        );
        let mut signer = report.signers[0].clone();
        assert!(!signer.signatures.is_empty());

        let middle = signer.signatures[0].1.len() / 2;
        signer.signatures[0].1[middle] ^= 0x01;

        let mut sink = Sink::new();
        let checked = signing::verify_signer(&signer, &mut sink);
        assert!(checked.key_matches_certificate, "the key is untouched");
        assert_eq!(checked.signatures.len(), 1);
        assert_eq!(checked.signatures[0].1, signing::Checked::Failed);
        let refusal = sink
            .entries()
            .iter()
            .find(|entry| entry.code == "ES036")
            .expect("a bent signature must be named");
        assert_eq!(refusal.severity, Severity::Fatal);

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn what_the_signature_covers_includes_the_digests() {
        let Some((bytes, directory)) = sign_with_apksigner("v2-covered") else {
            return;
        };

        let archive = archive::read(&bytes, &mut Sink::new()).unwrap();
        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut Sink::new(),
        );
        let mut signer = report.signers[0].clone();

        let at = signer.signed_data.len() / 2;
        signer.signed_data[at] ^= 0xff;

        let mut sink = Sink::new();
        let checked = signing::verify_signer(&signer, &mut sink);
        assert_eq!(checked.signatures[0].1, signing::Checked::Failed);

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_signing_block_reader_survives_arbitrary_input() {
        let Some((bytes, directory)) = sign_with_apksigner("v2-fuzz") else {
            return;
        };

        let mut seed = 0x7777_8888_9999_aaaau64;
        for _ in 0..1_500 {
            let mut damaged = bytes.clone();
            let mutations = (xorshift(&mut seed) % 6) + 1;
            for _ in 0..mutations {
                let position = (xorshift(&mut seed) as usize) % damaged.len();
                damaged[position] = (xorshift(&mut seed) & 0xff) as u8;
            }

            let mut sink = Sink::new();
            if let Some(archive) = archive::read(&damaged, &mut sink) {
                let report = signing::examine(
                    &damaged,
                    archive.central_directory_offset(),
                    archive.end_record_offset(),
                    &mut sink,
                );

                assert!(
                    report.signatures_verified == 0
                        || (report.signatures_failed == 0 && report.key_matches_certificate),
                    "a damaged package reported a clean signature"
                );
            }
        }

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_check_refuses_where_a_build_would_and_says_which_line() {
        let directory = temp_directory("omni-check");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Checked".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");

        let clear = crate::builder::check(&root);
        assert!(
            clear.refusal.is_none(),
            "a project as written must check clear: {:?}",
            clear.refusal
        );
        assert!(clear.classes > 0, "the activity is a class");
        assert_eq!(clear.package, "com.tr.yt");

        let before = crate::workspace::tree(&root).unwrap();
        crate::builder::check(&root);
        let after = crate::workspace::tree(&root).unwrap();
        assert_eq!(
            before.len(),
            after.len(),
            "a check left something behind in the project"
        );

        let source = crate::workspace::tree(&root)
            .unwrap()
            .into_iter()
            .find(|entry| entry.path.ends_with(".java"))
            .expect("the scaffold writes Java");
        let text = crate::workspace::read_text(&root, &source.path).unwrap();
        let mut lines: Vec<String> = text.lines().map(|line| line.to_string()).collect();
        let broken = lines.len() / 2;
        lines.insert(broken, "    int and now this is not Java @@@;".to_string());
        crate::workspace::write_text(&root, &source.path, &lines.join("\n")).unwrap();

        let refused = crate::builder::check(&root);
        let refusal = refused.refusal.expect("a project that is not Java refuses");
        let place = refusal
            .location
            .as_ref()
            .expect("a refusal about a line carries that line");
        assert_eq!(
            place.line as usize,
            broken + 1,
            "the refusal points at {} rather than at the line that is wrong: {refusal:?}",
            place.line
        );
        assert_eq!(
            place.file, source.path,
            "the refusal names the file by the path the project knows it by"
        );

        let error = crate::builder::from_project(&root).expect_err("the build refuses too");
        assert_eq!(error.code, refusal.code);
        assert_eq!(
            error.location.as_ref().map(|held| held.line),
            Some(place.line)
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_bridge_checks_a_project_without_building_it() {
        let directory = temp_directory("omni-check-bridge");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Checked".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");

        let root_c = std::ffi::CString::new(root.clone()).unwrap();
        let read = |ptr: *mut std::os::raw::c_char| {
            assert!(!ptr.is_null());
            let held = unsafe { std::ffi::CStr::from_ptr(ptr) }
                .to_string_lossy()
                .into_owned();
            unsafe { crate::ffi::omni_string_free(ptr) };
            held
        };

        let clear = read(unsafe { crate::ffi::omni_check_project(root_c.as_ptr()) });
        assert!(is_structurally_valid(&clear), "{clear}");
        assert!(clear.contains("\"clear\":true"), "{clear}");
        assert!(clear.contains("\"package\":\"com.tr.yt\""), "{clear}");

        let source = crate::workspace::tree(&root)
            .unwrap()
            .into_iter()
            .find(|entry| entry.path.ends_with(".java"))
            .expect("the scaffold writes Java");
        crate::workspace::write_text(&root, &source.path, "this is not Java at all\n").unwrap();

        let refused = read(unsafe { crate::ffi::omni_check_project(root_c.as_ptr()) });
        assert!(is_structurally_valid(&refused), "{refused}");
        assert!(refused.contains("\"clear\":false"), "{refused}");
        assert!(refused.contains("\"location\""), "{refused}");
        assert!(refused.contains("\"line\":1"), "{refused}");

        assert!(
            !directory.join("Built").exists(),
            "a check produced a package"
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_search_finds_every_place_and_says_what_it_skipped() {
        let directory = temp_directory("omni-search");
        let root = directory.to_str().unwrap().to_string();
        std::fs::create_dir_all(directory.join("Java/com/example")).unwrap();
        std::fs::write(
            directory.join("AndroidManifest.xml"),
            "<manifest package=\"com.example\"><application/></manifest>\n",
        )
        .unwrap();
        std::fs::write(
            directory.join("Java/com/example/Main.java"),
            "package com.example;\n\
             // the answer is here\n\
             class Main {\n\
             \x20   int answer = 42;\n\
             \x20   int Answer = 43;\n\
             \x20   int answered = 44;\n\
             }\n",
        )
        .unwrap();
        std::fs::write(
            directory.join("Java/com/example/Other.java"),
            "class Other { String answer = \"answer\"; }\n",
        )
        .unwrap();

        std::fs::write(directory.join("Icon.png"), [0x89u8, b'P', b'N', 0x00, b'G']).unwrap();

        let found = crate::workspace::search(&root, "answer", false, false).unwrap();
        assert_eq!(found.files_not_text, 1, "the image must not be searched");
        assert_eq!(found.files_searched, 3);
        assert!(!found.stopped_early);

        let places: Vec<(String, u32, u32)> = found
            .matches
            .iter()
            .map(|one| (one.path.clone(), one.line, one.column))
            .collect();
        assert_eq!(
            places,
            vec![
                ("Java/com/example/Main.java".to_string(), 2, 8),
                ("Java/com/example/Main.java".to_string(), 4, 9),
                ("Java/com/example/Main.java".to_string(), 5, 9),
                ("Java/com/example/Main.java".to_string(), 6, 9),
                ("Java/com/example/Other.java".to_string(), 1, 22),
                ("Java/com/example/Other.java".to_string(), 1, 32),
            ],
            "the places a search reports are the places the text is"
        );

        assert_eq!(found.matches[0].text, "// the answer is here");

        let exact = crate::workspace::search(&root, "answer", true, false).unwrap();
        assert!(
            exact.matches.iter().all(|one| one.line != 5),
            "a case-sensitive search matched a different case"
        );
        assert_eq!(exact.matches.len(), 5);

        let words = crate::workspace::search(&root, "answer", true, true).unwrap();
        assert!(
            words.matches.iter().all(|one| one.line != 6),
            "a whole-word search matched inside a longer word"
        );

        assert_eq!(words.matches.len(), 4);

        assert_eq!(
            crate::workspace::search(&root, "", false, false)
                .unwrap_err()
                .code,
            "EW160"
        );

        std::fs::remove_dir_all(&directory).ok();
    }

