    #[test]
    fn the_build_engine_produces_a_package_apksigner_accepts() {
        let _turn = crate::progress::one_at_a_time();
        let Some(apksigner) = find_apksigner() else {
            assert!(
                std::env::var("OMNI_REQUIRE_SELF_BUILT_APK").is_err(),
                "OMNI_REQUIRE_SELF_BUILT_APK is set but apksigner is missing"
            );
            eprintln!("build engine: apksigner is not available here");
            return;
        };

        let key = crate::rsa::generate(2048).expect("the engine must be able to make a key");
        let mut sink = Sink::new();
        let mut project = crate::builder::starter("com.omni.made", "Made By Omni");
        project.files = sample_project().files;
        let outcome = crate::builder::build(&project, &key, 1_787_000_000, &mut sink)
            .expect("a compliant project must build");

        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        assert_eq!(outcome.guard.verdict(), crate::guard::Verdict::Passed);
        assert!(outcome.guard.rules_applied >= 7);
        assert!(outcome.signed);
        assert!(outcome.carries_code);
        assert_eq!(outcome.entries, 4);

        let mut own = Sink::new();
        let archive = archive::read(&outcome.package, &mut own).expect("it must read back");
        assert!(archive
            .entries()
            .iter()
            .any(|entry| entry.name == "classes.dex"));

        let directory = temp_directory("omni-engine");
        let path = directory.join("made-by-omni.apk");
        std::fs::write(&path, &outcome.package).unwrap();

        let verified = std::process::Command::new(&apksigner)
            .args([
                "verify",
                "--verbose",
                "--print-certs",
                "--min-sdk-version",
                &crate::compiler::OLDEST_API.to_string(),
                path.to_str().unwrap(),
            ])
            .output()
            .unwrap();
        let report = format!(
            "{}{}",
            String::from_utf8_lossy(&verified.stdout),
            String::from_utf8_lossy(&verified.stderr)
        );
        assert!(
            verified.status.success(),
            "apksigner rejected it:\n{report}"
        );
        assert!(
            report.contains("Verified using v3 scheme (APK Signature Scheme v3): true"),
            "{report}"
        );
        assert!(report.contains("CN=Omni_Builder"), "{report}");

        let older = std::process::Command::new(&apksigner)
            .args([
                "verify",
                "--verbose",
                "--min-sdk-version",
                "24",
                "--max-sdk-version",
                "27",
                path.to_str().unwrap(),
            ])
            .output()
            .unwrap();
        let older_report = format!(
            "{}{}",
            String::from_utf8_lossy(&older.stdout),
            String::from_utf8_lossy(&older.stderr)
        );
        assert!(
            older.status.success(),
            "apksigner rejected the v2 block:\n{older_report}"
        );
        assert!(
            older_report.contains("Verified using v2 scheme (APK Signature Scheme v2): true"),
            "{older_report}"
        );

        let mut block_sink = Sink::new();
        let (directory_offset, end_offset) =
            crate::signing::locate(&outcome.package).expect("the package must have a directory");
        let block = crate::signing::examine(
            &outcome.package,
            directory_offset,
            end_offset,
            &mut block_sink,
        );
        assert!(block.schemes.contains(&"v2"), "{:?}", block.schemes);
        assert!(block.schemes.contains(&"v3"), "{:?}", block.schemes);

        let extracted = std::process::Command::new("unzip")
            .args(["-p", path.to_str().unwrap(), "classes.dex"])
            .output()
            .unwrap();
        assert!(extracted.status.success());
        let classes = dex::read(&extracted.stdout, &mut Sink::new()).expect("our dex must read");
        assert_eq!(classes.class_names(), vec!["com.omni.made.MainActivity"]);
        if let Some((_, descriptors)) = dexdump(&extracted.stdout) {
            assert_eq!(descriptors, vec!["Lcom/omni/made/MainActivity;"]);
        }

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "build engine: {} bytes, {} entries including a classes.dex written here, apksigner verified the v3 block at API 28 and the v2 block at API 27",
            outcome.package.len(),
            outcome.entries
        );
    }

    #[test]
    fn a_developer_key_is_written_read_and_unlocked_with_their_own_password() {
        let directory = temp_directory("omni-keys");
        let folder = directory.to_str().unwrap().to_string();
        let request = crate::keystore::Request {
            alias: "release-2026".to_string(),
            common_name: "Eaquel".to_string(),
            organisation: "Omni".to_string(),
            country: "TR".to_string(),
            validity_days: 9_125,
            bits: 2048,
        };
        let password = "correct horse battery";

        let made = crate::keystore::create(&folder, &request, password, 1_787_000_000)
            .expect("a developer must be able to make their own key");
        assert_eq!(made.alias, "release-2026");
        assert!(made.subject.contains("CN=Eaquel"), "{}", made.subject);
        assert!(made.subject.contains("O=Omni"), "{}", made.subject);
        assert!(made.subject.contains("C=TR"), "{}", made.subject);
        assert_eq!(made.bits, Some(2048));
        assert_eq!(made.issued, "2026-08-16 20:53:20 UTC");
        assert_eq!(made.expires, "2051-08-11 20:53:20 UTC");

        let stored = std::fs::read(&made.path).expect("the key file must be on disk");
        assert_eq!(&stored[..8], crate::keystore::MAGIC);
        assert!(
            !stored
                .windows(password.len())
                .any(|window| window == password.as_bytes()),
            "the password must never be written into the key file"
        );

        let listed = crate::keystore::list(&folder);
        assert_eq!(listed.len(), 1);
        assert_eq!(listed[0].fingerprint, made.fingerprint);

        let described =
            crate::keystore::describe(&made.path).expect("a listing must not need the password");
        assert_eq!(described.subject, made.subject);

        let opened =
            crate::keystore::unlock(&made.path, password).expect("the password must open it");
        assert_eq!(opened.record.fingerprint, made.fingerprint);
        assert_eq!(
            crate::certificate::public_key_info(&opened.key).unwrap(),
            crate::x509::Certificate::public_key_info(&opened.certificate).unwrap()
        );

        for wrong in ["correct horse batterz", "", "correct horse battery "] {
            let refused = crate::keystore::unlock(&made.path, wrong)
                .expect_err("a wrong password must be refused");
            assert_eq!(refused.code, "EY021", "{}", refused.message);
            assert!(
                !refused
                    .context
                    .iter()
                    .any(|line| line.contains(wrong) && !wrong.is_empty()),
                "a diagnostic must never carry the password: {:?}",
                refused.context
            );
        }

        let again = crate::keystore::create(&folder, &request, password, 1_787_000_000)
            .expect_err("an alias already in use must not be overwritten");
        assert_eq!(again.code, "EY040");

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "developer key: {} sealed under a password, listed without one, {}",
            made.alias, made.fingerprint
        );
    }

    static SHARED_KEY_TURN: std::sync::Mutex<()> = std::sync::Mutex::new(());

    #[test]
    fn the_shared_key_is_sealed_to_the_device_as_well_as_to_its_password() {
        assert_eq!(
            crate::keystore::shared_password_for(""),
            crate::keystore::DEFAULT_PASSWORD,
            "a machine that will not name itself falls back to what it always was"
        );

        let here = crate::keystore::shared_password_for("a1b2c3d4e5f60718");
        let there = crate::keystore::shared_password_for("a1b2c3d4e5f60719");
        assert_ne!(here, there, "one byte apart must not seal the same");
        assert_eq!(
            here,
            crate::keystore::shared_password_for("a1b2c3d4e5f60718")
        );
        assert_ne!(here, crate::keystore::DEFAULT_PASSWORD);
        assert!(
            here.starts_with(crate::keystore::DEFAULT_PASSWORD),
            "what the person types is still in there; what follows is the device"
        );
        assert!(here.len() > crate::keystore::DEFAULT_PASSWORD.len() + 32);

        let _turn = SHARED_KEY_TURN
            .lock()
            .unwrap_or_else(|held| held.into_inner());
        let directory = temp_directory("omni-keys-bound");
        let folder = directory.to_str().unwrap().to_string();

        crate::keystore::bind_device("a1b2c3d4e5f60718");
        assert!(crate::keystore::device_is_bound());
        let (made, created) = crate::keystore::ensure_default(&folder, 1_787_000_000)
            .expect("the shared key must be made");
        assert!(created);
        assert!(crate::keystore::is_default(&made.path));

        crate::keystore::unlock(&made.path, crate::keystore::DEFAULT_PASSWORD)
            .expect("on the device that made it, the shared key opens");

        crate::keystore::bind_device("a1b2c3d4e5f60719");
        let refused = crate::keystore::unlock(&made.path, crate::keystore::DEFAULT_PASSWORD)
            .expect_err("somewhere else, the same file must not open");
        assert!(
            refused.code == "EY051" || refused.code == "EY021",
            "refused with {}: {}",
            refused.code,
            refused.message
        );

        crate::keystore::bind_device("");
        assert!(!crate::keystore::device_is_bound());
        crate::keystore::unlock(&made.path, crate::keystore::DEFAULT_PASSWORD)
            .expect_err("the published password alone must not open a bound key");

        let listed = crate::keystore::list(&folder);
        let mut said = String::new();
        for record in &listed {
            said.push_str(&format!("{record:?}"));
        }
        assert!(!said.contains(&here), "the seal must not be reported");

        std::fs::remove_dir_all(&directory).ok();
        eprintln!("keystore: the shared key opens on the device that made it and nowhere else");
    }

    #[test]
    fn a_key_written_before_there_were_tags_still_opens_and_is_given_one() {
        let directory = temp_directory("omni-keys-upgrade");
        let folder = directory.to_str().unwrap().to_string();
        let password = "a password long enough";
        let request = crate::keystore::Request {
            alias: "older".to_string(),
            common_name: "Older".to_string(),
            organisation: "Omni".to_string(),
            country: "TR".to_string(),
            validity_days: 400,
            bits: 2048,
        };
        let made = crate::keystore::create(&folder, &request, password, 1_787_000_000).unwrap();
        let current = std::fs::read(&made.path).unwrap();
        let parsed = crate::keystore::parts(&current).unwrap();
        assert_eq!(parsed.version, crate::keystore::CONTAINER_VERSION);

        let mut older = Vec::new();
        older.extend_from_slice(crate::keystore::MAGIC);
        older.extend_from_slice(&crate::keystore::OLDEST_CONTAINER_VERSION.to_le_bytes());
        for part in [parsed.alias.as_bytes(), parsed.certificate, parsed.sealed] {
            older.extend_from_slice(&(part.len() as u32).to_le_bytes());
            older.extend_from_slice(part);
        }
        std::fs::write(&made.path, &older).unwrap();

        let read_back = std::fs::read(&made.path).unwrap();
        let before = crate::keystore::parts(&read_back).unwrap();
        assert_eq!(before.version, crate::keystore::OLDEST_CONTAINER_VERSION);
        assert!(!before.is_authenticated(), "version one carried no tag");

        let opened = crate::keystore::unlock(&made.path, password)
            .expect("a key written before there were tags must still open");
        assert_eq!(opened.record.alias, "older");

        let after_file = std::fs::read(&made.path).unwrap();
        let after = crate::keystore::parts(&after_file).unwrap();
        assert_eq!(after.version, crate::keystore::CONTAINER_VERSION);
        assert!(after.is_authenticated(), "it should carry a tag now");
        assert_eq!(after.sealed, parsed.sealed, "the sealed key is untouched");
        assert_eq!(after.certificate, parsed.certificate);

        assert!(
            !std::path::Path::new(&format!("{}.upgrading", made.path)).exists(),
            "the file written beside it should have been moved over it"
        );

        crate::keystore::unlock(&made.path, password).expect("and it opens again after");

        let mut altered = after_file.clone();
        altered[12 + after.alias.len() + 8] ^= 0x40;
        std::fs::write(&made.path, &altered).unwrap();
        assert_eq!(
            crate::keystore::unlock(&made.path, password)
                .expect_err("now that it records itself, altering it must be refused")
                .code,
            "EY051"
        );

        let mut untagged = after_file.clone();
        let last = untagged.len() - 1;
        untagged[last] ^= 1;
        std::fs::write(&made.path, &untagged).unwrap();
        assert_eq!(
            crate::keystore::unlock(&made.path, password)
                .expect_err("a tag that does not hold must refuse")
                .code,
            "EY021"
        );

        std::fs::remove_dir_all(&directory).ok();
        eprintln!("keystore: a version one key opened, kept its key, and came back version two");
    }

    #[test]
    fn a_developer_key_file_that_has_been_altered_is_refused() {
        let directory = temp_directory("omni-keys-altered");
        let folder = directory.to_str().unwrap().to_string();
        let password = "a password long enough";
        let mine = crate::keystore::Request {
            alias: "mine".to_string(),
            common_name: "Mine".to_string(),
            organisation: "Omni".to_string(),
            country: "TR".to_string(),
            validity_days: 400,
            bits: 2048,
        };
        let theirs = crate::keystore::Request {
            alias: "theirs".to_string(),
            common_name: "Theirs".to_string(),
            ..mine.clone()
        };

        let mine_made = crate::keystore::create(&folder, &mine, password, 1_787_000_000).unwrap();
        let theirs_made =
            crate::keystore::create(&folder, &theirs, password, 1_787_000_000).unwrap();

        let mine_file = std::fs::read(&mine_made.path).unwrap();
        let theirs_file = std::fs::read(&theirs_made.path).unwrap();
        let mine_parts = crate::keystore::parts(&mine_file).unwrap();
        let theirs_parts = crate::keystore::parts(&theirs_file).unwrap();
        let mine_certificate = mine_parts.certificate;
        let mine_sealed = mine_parts.sealed;
        let theirs_certificate = theirs_parts.certificate;
        assert!(mine_parts.is_authenticated());

        let borrowed = crate::keystore::tag_key_for(mine_sealed, password).unwrap();

        let mut edited = mine_file.clone();
        let somewhere_inside = 12 + mine_parts.alias.len() + 8;
        edited[somewhere_inside] ^= 0x40;
        std::fs::write(&mine_made.path, &edited).unwrap();
        let refused = crate::keystore::unlock(&mine_made.path, password)
            .expect_err("a file edited where it stands must be refused");
        assert_eq!(refused.code, "EY051", "{}", refused.message);

        let wrong_key = [0x11u8; 32];
        let swapped = crate::keystore::encode("mine", theirs_certificate, mine_sealed, &wrong_key);
        std::fs::write(&mine_made.path, &swapped).unwrap();
        let refused = crate::keystore::unlock(&mine_made.path, password)
            .expect_err("a file that does not match its own tag must be refused");
        assert_eq!(refused.code, "EY021", "{}", refused.message);
        assert!(
            refused
                .suggestion
                .as_deref()
                .is_some_and(|line| line.contains("not the one it was written as")),
            "the person has to be told the other thing it could be: {:?}",
            refused.suggestion
        );

        let retagged = crate::keystore::encode("mine", theirs_certificate, mine_sealed, &borrowed);
        std::fs::write(&mine_made.path, &retagged).unwrap();
        let refused = crate::keystore::unlock(&mine_made.path, password)
            .expect_err("a certificate that does not match the key must be refused");
        assert_eq!(refused.code, "EY050", "{}", refused.message);

        let honest = crate::keystore::encode("mine", mine_certificate, mine_sealed, &borrowed);
        std::fs::write(&mine_made.path, &honest).unwrap();
        crate::keystore::unlock(&mine_made.path, password).expect("the honest file must open");

        let covered = crate::keystore::parts(&honest).unwrap().covered;
        let mut checked = 0usize;
        for at in (0..covered).step_by(covered / 12 + 1) {
            let mut altered = honest.clone();
            altered[at] ^= 1;
            std::fs::write(&mine_made.path, &altered).unwrap();
            let refused = crate::keystore::unlock(&mine_made.path, password)
                .expect_err("a byte changed anywhere under the tag must be refused");
            assert!(
                refused.code == "EY051" || refused.code == "EY032" || refused.code == "EY033",
                "byte {at} was changed and the file was refused with {}: {}",
                refused.code,
                refused.message
            );
            assert_ne!(
                refused.code, "EY050",
                "byte {at} reached the certificate check, so it reached a decryption"
            );
            checked += 1;
        }
        assert!(checked >= 12, "only {checked} bytes were tried");
        std::fs::write(&mine_made.path, &honest).unwrap();

        std::fs::write(&mine_made.path, b"not a key at all").unwrap();
        assert_eq!(
            crate::keystore::describe(&mine_made.path)
                .expect_err("a file that is not a key must be refused")
                .code,
            "EY032"
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_keystore_refuses_what_would_produce_an_unusable_key() {
        let directory = temp_directory("omni-keys-refused");
        let folder = directory.to_str().unwrap().to_string();
        let sound = crate::keystore::Request {
            alias: "ok".to_string(),
            common_name: "Name".to_string(),
            organisation: "Omni".to_string(),
            country: "TR".to_string(),
            validity_days: 9_125,
            bits: 2048,
        };

        let cases: &[(&str, crate::keystore::Request, &str)] = &[
            (
                "an alias that is a path",
                crate::keystore::Request {
                    alias: "../escape".to_string(),
                    ..sound.clone()
                },
                "EY010",
            ),
            (
                "an empty name",
                crate::keystore::Request {
                    common_name: "   ".to_string(),
                    ..sound.clone()
                },
                "EY011",
            ),
            (
                "a country that is not a code",
                crate::keystore::Request {
                    country: "Turkiye".to_string(),
                    ..sound.clone()
                },
                "EY012",
            ),
            (
                "a validity of no days",
                crate::keystore::Request {
                    validity_days: 0,
                    ..sound.clone()
                },
                "EY013",
            ),
            (
                "a key too small to sign with",
                crate::keystore::Request {
                    bits: 1024,
                    ..sound.clone()
                },
                "EY014",
            ),
        ];

        for (what, request, code) in cases {
            match crate::keystore::create(&folder, request, "a long enough password", 1_787_000_000)
            {
                Ok(made) => {
                    panic!("{what}: {code} was expected but {} was written", made.path)
                }
                Err(error) => assert_eq!(&error.code, code, "{what}: {}", error.message),
            }
        }
        assert!(crate::keystore::list(&folder).is_empty());
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_short_password_does_not_protect_a_key_so_it_is_refused() {
        let directory = temp_directory("omni-keys-password");
        let folder = directory.to_str().unwrap().to_string();
        let request = crate::keystore::Request {
            alias: "short".to_string(),
            common_name: "Name".to_string(),
            organisation: "Omni".to_string(),
            country: "TR".to_string(),
            validity_days: 400,
            bits: 2048,
        };
        let refused = crate::keystore::create(&folder, &request, "1234567", 1_787_000_000)
            .expect_err("seven characters must not be accepted");
        assert_eq!(refused.code, "EY020");
        assert!(!crate::keystore::path_for(&folder, "short").is_empty());
        assert!(crate::keystore::list(&folder).is_empty());
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_developers_own_key_signs_the_package_and_apksigner_reads_their_name() {
        let Some(apksigner) = find_apksigner() else {
            assert!(
                std::env::var("OMNI_REQUIRE_SELF_BUILT_APK").is_err(),
                "OMNI_REQUIRE_SELF_BUILT_APK is set but apksigner is missing"
            );
            eprintln!("developer key: apksigner is not available here");
            return;
        };

        let directory = temp_directory("omni-developer");
        let folder = directory.to_str().unwrap().to_string();
        let password = "the developer's own password";
        let request = crate::keystore::Request {
            alias: "eaquel-release".to_string(),
            common_name: "Eaquel Release".to_string(),
            organisation: "Omni Builder".to_string(),
            country: "TR".to_string(),
            validity_days: 10_950,
            bits: 2048,
        };
        let made = crate::keystore::create(&folder, &request, password, 1_787_000_000).unwrap();
        let opened = crate::keystore::unlock(&made.path, password).unwrap();

        let mut sink = Sink::new();
        let project = crate::builder::starter("com.tr.yt", "Omni");
        let outcome =
            crate::builder::assemble(&project, &opened.key, &opened.certificate, &mut sink)
                .expect("the developer's key must sign the package");
        assert_eq!(outcome.certificate_fingerprint, made.fingerprint);

        assert!(outcome.verified.everything_checkable_passed());
        assert!(outcome.verified.signatures_checked);
        assert_eq!(outcome.verified.signatures_failed, 0);
        assert!(outcome.verified.signatures_verified >= 2, "v2 and v3 both");
        assert!(outcome.verified.key_matches_certificate);
        assert_eq!(outcome.verified.digests_failed, 0);

        let path = directory.join("developer-signed.apk");
        std::fs::write(&path, &outcome.package).unwrap();
        let verified = std::process::Command::new(&apksigner)
            .args([
                "verify",
                "--verbose",
                "--print-certs",
                "--min-sdk-version",
                &crate::compiler::OLDEST_API.to_string(),
                path.to_str().unwrap(),
            ])
            .output()
            .unwrap();
        let report = format!(
            "{}{}",
            String::from_utf8_lossy(&verified.stdout),
            String::from_utf8_lossy(&verified.stderr)
        );
        assert!(verified.status.success(), "{report}");
        assert!(
            report.contains("Verified using v3 scheme (APK Signature Scheme v3): true"),
            "{report}"
        );
        assert!(report.contains("CN=Eaquel Release"), "{report}");
        assert!(report.contains("O=Omni Builder"), "{report}");
        assert!(
            report
                .to_lowercase()
                .contains(&made.fingerprint.replace(':', "").to_lowercase()),
            "apksigner must report the same certificate the keys list shows\n{report}"
        );

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "developer key: apksigner read CN=Eaquel Release off a package this build signed"
        );
    }

    #[test]
    fn the_security_policy_reports_a_weak_package_without_stopping_it() {
        let _turn = crate::progress::one_at_a_time();
        let key = crate::rsa::generate(1024).unwrap();
        let cases: &[(&str, &str, &str)] = &[
            (
                "debuggable",
                r#"<application android:label="X" android:allowBackup="false" android:debuggable="true" />"#,
                "EG001",
            ),
            (
                "cleartext",
                r#"<application android:label="X" android:allowBackup="false" android:usesCleartextTraffic="true" />"#,
                "EG002",
            ),
            ("backup", r#"<application android:label="X" />"#, "EG003"),
            (
                "exported",
                r#"<application android:label="X" android:allowBackup="false"><activity android:name="A" android:exported="true"><intent-filter><action android:name="x" /></intent-filter></activity></application>"#,
                "EG004",
            ),
            (
                "provider",
                r#"<application android:label="X" android:allowBackup="false"><provider android:name="P" android:authorities="a" android:exported="true" android:grantUriPermissions="true" /></application>"#,
                "EG005",
            ),
            (
                "legacy storage",
                r#"<application android:label="X" android:allowBackup="false" android:requestLegacyExternalStorage="true" />"#,
                "EG009",
            ),
            (
                "task hijacking",
                r#"<application android:label="X" android:allowBackup="false"><activity android:name="A" android:exported="true" android:launchMode="singleTask"><intent-filter><action android:name="x" /></intent-filter></activity></application>"#,
                "EG011",
            ),
        ];

        for (name, application, code) in cases {
            let manifest = format!(
                r#"<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android" package="com.omni.weak">
    <uses-sdk android:minSdkVersion="30" android:targetSdkVersion="36" />
    {application}
</manifest>"#
            );
            let project = crate::builder::Project {
                manifest,
                files: Vec::new(),
                code: Vec::new(),
                references: Vec::new(),
                identity: crate::builder::Identity::default(),
                icon: None,
                launcher: Vec::new(),
                values: Vec::new(),
                resources: Vec::new(),
                library_values: Vec::new(),
                library_resources: Vec::new(),
                library_packages: Vec::new(),
                sealed: None,
                shrink: true,
                seal_resources: false,
            };
            let mut sink = Sink::new();
            let built = crate::builder::build(&project, &key, 1_787_000_000, &mut sink)
                .unwrap_or_else(|why| panic!("{name} must still be produced: {why:?}"));
            assert!(built.signed, "{name}");
            let codes: Vec<&str> = sink.entries().iter().map(|d| d.code.as_str()).collect();
            assert!(
                codes.contains(code),
                "{name}: expected {code}, got {codes:?}"
            );
            assert!(
                sink.entries()
                    .iter()
                    .filter(|one| one.code == *code)
                    .all(|one| !one.severity.is_blocking()),
                "{name}: a policy finding must not block a build"
            );
            assert!(
                built.guard.findings.iter().any(|one| one.code == *code),
                "{name}: the report must carry the finding"
            );
        }
    }

    #[test]
    fn a_shared_user_identity_and_a_census_of_every_application_are_refused() {
        let manifest = r#"<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android" package="com.omni.weak"
    android:sharedUserId="com.omni.shared">
    <uses-sdk android:minSdkVersion="30" android:targetSdkVersion="36" />
    <uses-permission android:name="android.permission.QUERY_ALL_PACKAGES" />
    <application android:label="X" android:allowBackup="false" android:hasCode="false"
        android:extractNativeLibs="false" />
</manifest>"#;

        let mut sink = Sink::new();
        let root = crate::xml::parse(manifest, "AndroidManifest.xml", &mut sink).unwrap();
        let report = crate::guard::inspect_manifest(&root);
        assert_eq!(report.verdict(), crate::guard::Verdict::Refused);

        let codes: Vec<&str> = report.findings.iter().map(|one| one.code).collect();
        assert!(codes.contains(&"EG008"), "{codes:?}");
        assert!(codes.contains(&"EG010"), "{codes:?}");

        for finding in &report.findings {
            assert!(!finding.why.is_empty(), "{} says nothing", finding.code);
            assert!(
                !finding.remedy.is_empty(),
                "{} offers nothing",
                finding.code
            );
        }
    }

