    fn python_compress(data: &[u8], level: u32, raw: bool) -> Option<Vec<u8>> {
        let directory = temp_directory("omni-zlib-in");
        let source = directory.join("plain.bin");
        let target = directory.join("packed.bin");
        std::fs::write(&source, data).ok()?;
        let program = format!(
            "import zlib\ndata = open(r'{}', 'rb').read()\nc = zlib.compressobj({}, zlib.DEFLATED, {})\nout = c.compress(data) + c.flush()\nopen(r'{}', 'wb').write(out)\n",
            source.to_str()?,
            level,
            if raw { -15 } else { 15 },
            target.to_str()?,
        );
        let run = std::process::Command::new("python3")
            .arg("-c")
            .arg(&program)
            .output()
            .ok()?;
        if !run.status.success() {
            std::fs::remove_dir_all(&directory).ok();
            return None;
        }
        let packed = std::fs::read(&target).ok();
        std::fs::remove_dir_all(&directory).ok();
        packed
    }

    #[test]
    fn deflate_writes_a_stream_an_independent_reader_accepts() {
        let mut seed = 0x2b7e_1516_28ae_d2a6u64;
        let mut next = || {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            seed
        };

        let mut cases: Vec<Vec<u8>> = vec![
            Vec::new(),
            b"a".to_vec(),
            b"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa".to_vec(),
            b"the same words the same words the same words the same words".to_vec(),
            vec![0u8; 200_000],
            (0..=255u8).cycle().take(120_000).collect(),
        ];
        for size in [2usize, 3, 4, 258, 259, 1_024, 40_000] {
            cases.push((0..size).map(|_| (next() & 0xff) as u8).collect());
        }
        let mut lumpy = Vec::new();
        for _ in 0..4_000 {
            let run = (next() % 60) as usize;
            let byte = (next() & 0x0f) as u8;
            lumpy.extend(std::iter::repeat_n(byte, run));
        }
        cases.push(lumpy);

        let mut original = 0usize;
        let mut packed_total = 0usize;
        for case in &cases {
            let packed = crate::deflate::zlib(case);
            let read = crate::inflate::zlib(&packed).unwrap_or_else(|error| {
                panic!("{} bytes: {} {}", case.len(), error.code, error.message)
            });
            assert_eq!(
                &read,
                case,
                "{} bytes did not survive the round trip",
                case.len()
            );
            original += case.len();
            packed_total += packed.len();
        }

        if python_available() {
            for case in &cases {
                let packed = crate::deflate::zlib(case);
                let directory = temp_directory("omni-deflate");
                let source = directory.join("packed.bin");
                std::fs::write(&source, &packed).unwrap();
                let program = format!(
                    "import zlib,sys\nd=open(r'{}','rb').read()\nsys.stdout.write(str(len(zlib.decompress(d))))\n",
                    source.to_str().unwrap()
                );
                let run = std::process::Command::new("python3")
                    .arg("-c")
                    .arg(&program)
                    .output()
                    .unwrap();
                let reported = String::from_utf8_lossy(&run.stdout).to_string();
                assert!(
                    run.status.success(),
                    "an independent reader refused what this build wrote for {} bytes:\n{}",
                    case.len(),
                    String::from_utf8_lossy(&run.stderr)
                );
                assert_eq!(
                    reported,
                    case.len().to_string(),
                    "an independent reader read a different length back"
                );
                std::fs::remove_dir_all(&directory).ok();
            }
        } else {
            assert!(
                std::env::var("OMNI_REQUIRE_INFLATE_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_INFLATE_CONFORMANCE is set but no independent reader is here"
            );
        }

        assert!(
            packed_total < original,
            "{packed_total} bytes out of {original} is not compression"
        );
        eprintln!(
            "deflate: {original} bytes written as {packed_total}, read back exactly by this \
             build and by an independent reader"
        );
    }

    fn git_available() -> bool {
        std::process::Command::new("git")
            .arg("--version")
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status()
            .map(|code| code.success())
            .unwrap_or(false)
    }

    fn pack_entry_header(kind: u8, size: usize) -> Vec<u8> {
        let mut out = Vec::new();
        let mut byte = (kind << 4) | (size & 0x0f) as u8;
        let mut rest = size >> 4;
        while rest > 0 {
            out.push(byte | 0x80);
            byte = (rest & 0x7f) as u8;
            rest >>= 7;
        }
        out.push(byte);
        out
    }

    fn pack_back_reference(offset: usize) -> Vec<u8> {
        let mut value = offset;
        let mut out = vec![(value & 0x7f) as u8];
        value >>= 7;
        while value > 0 {
            value -= 1;
            out.push(0x80 | (value & 0x7f) as u8);
            value >>= 7;
        }
        out.reverse();
        out
    }

    fn pack_around(count: u32, body: Vec<u8>) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(b"PACK");
        out.extend_from_slice(&2u32.to_be_bytes());
        out.extend_from_slice(&count.to_be_bytes());
        out.extend_from_slice(&body);
        let mut hash = crate::hash::Sha1::default();
        hash.update(&out);
        out.extend_from_slice(hash.finish().as_bytes());
        out
    }

    #[test]
    fn git_names_an_object_the_way_the_format_names_it() {
        assert_eq!(
            git::to_hex(&git::identify(git::Kind::Blob, b"")),
            "e69de29bb2d1d6434b8b29ae775ad8c2e48c5391"
        );
        assert_eq!(
            git::to_hex(&git::identify(git::Kind::Blob, b"hello world\n")),
            "3b18e512dba79e4c8300dd08aeb37f8e728b8dad"
        );
        assert_eq!(
            git::of_hex("3b18e512dba79e4c8300dd08aeb37f8e728b8dad"),
            Some(git::identify(git::Kind::Blob, b"hello world\n"))
        );
        assert_eq!(git::of_hex("3b18e5"), None);
    }

    #[test]
    fn git_resolves_both_kinds_of_delta_in_one_pack() {
        let leaf = b"hello world\n".to_vec();
        let leaf_id = git::identify(git::Kind::Blob, &leaf);
        let grown = b"hello world\nmore\n".to_vec();
        let grown_id = git::identify(git::Kind::Blob, &grown);

        let mut delta = vec![
            leaf.len() as u8,
            grown.len() as u8,
            0x90,
            leaf.len() as u8,
            5,
        ];
        delta.extend_from_slice(b"more\n");

        let mut tree = Vec::new();
        tree.extend_from_slice(b"100644 one\0");
        tree.extend_from_slice(&leaf_id);
        tree.extend_from_slice(b"100755 two\0");
        tree.extend_from_slice(&grown_id);
        let tree_id = git::identify(git::Kind::Tree, &tree);

        let commit = format!(
            "tree {}\nauthor A <a@b> 0 +0000\ncommitter A <a@b> 0 +0000\n\nfirst\n",
            git::to_hex(&tree_id)
        )
        .into_bytes();

        let mut body = Vec::new();
        let leaf_at = body.len();
        body.extend_from_slice(&pack_entry_header(3, leaf.len()));
        body.extend_from_slice(&crate::deflate::zlib(&leaf));

        body.extend_from_slice(&pack_entry_header(7, delta.len()));
        body.extend_from_slice(&leaf_id);
        body.extend_from_slice(&crate::deflate::zlib(&delta));

        let second_at = body.len();
        body.extend_from_slice(&pack_entry_header(6, delta.len()));
        body.extend_from_slice(&pack_back_reference(second_at - leaf_at));
        body.extend_from_slice(&crate::deflate::zlib(&delta));

        body.extend_from_slice(&pack_entry_header(2, tree.len()));
        body.extend_from_slice(&crate::deflate::zlib(&tree));
        body.extend_from_slice(&pack_entry_header(1, commit.len()));
        body.extend_from_slice(&crate::deflate::zlib(&commit));

        let pack = git::unpack(&pack_around(5, body)).expect("the pack resolves");
        assert_eq!(pack.count_of(git::Kind::Blob), 2);
        assert_eq!(pack.count_of(git::Kind::Tree), 1);
        assert_eq!(pack.count_of(git::Kind::Commit), 1);
        assert_eq!(pack.get(&grown_id).map(|one| one.body.clone()), Some(grown));

        let commit_id = git::identify(git::Kind::Commit, &commit);
        assert_eq!(git::tree_of(&pack, &commit_id), Ok(tree_id));

        let into = std::env::temp_dir().join("omni_git_two_deltas");
        let _ = std::fs::remove_dir_all(&into);
        let written = git::checkout(&pack, &commit_id, &into).expect("the tree is written");
        assert_eq!(written.files, 2);
        assert_eq!(std::fs::read(into.join("one")).unwrap(), b"hello world\n");
        assert_eq!(
            std::fs::read(into.join("two")).unwrap(),
            b"hello world\nmore\n"
        );
        let _ = std::fs::remove_dir_all(&into);
    }

    #[test]
    fn git_refuses_a_pack_that_is_not_one() {
        assert!(git::unpack(b"").is_err());
        assert!(git::unpack(&[0u8; 64]).is_err());
        let mut wrong = pack_around(0, Vec::new());
        wrong[0] = b'X';
        assert!(git::unpack(&wrong).is_err());
        let mut later = pack_around(0, Vec::new());
        later[7] = 9;
        assert!(git::unpack(&later).is_err());
    }

    #[test]
    fn git_refuses_a_name_that_would_leave_the_folder() {
        let leaf = b"x".to_vec();
        let leaf_id = git::identify(git::Kind::Blob, &leaf);
        for name in ["..", "a/b", ".", ""] {
            let mut tree = Vec::new();
            tree.extend_from_slice(format!("100644 {name}\0").as_bytes());
            tree.extend_from_slice(&leaf_id);
            let tree_id = git::identify(git::Kind::Tree, &tree);

            let mut body = Vec::new();
            body.extend_from_slice(&pack_entry_header(3, leaf.len()));
            body.extend_from_slice(&crate::deflate::zlib(&leaf));
            body.extend_from_slice(&pack_entry_header(2, tree.len()));
            body.extend_from_slice(&crate::deflate::zlib(&tree));

            let pack = git::unpack(&pack_around(2, body)).expect("the pack resolves");
            let into = std::env::temp_dir().join("omni_git_escape");
            let _ = std::fs::remove_dir_all(&into);
            assert!(
                git::checkout(&pack, &tree_id, &into).is_err(),
                "a tree naming {name:?} was written"
            );
            let _ = std::fs::remove_dir_all(&into);
        }
    }

    #[test]
    fn git_reads_what_the_reference_implementation_packs() {
        if !git_available() {
            assert!(
                std::env::var("OMNI_REQUIRE_GIT_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_GIT_CONFORMANCE is set but no reference git is here"
            );
            eprintln!("git: no reference implementation is available here");
            return;
        }

        let work = std::env::temp_dir().join("omni_git_conformance");
        let _ = std::fs::remove_dir_all(&work);
        std::fs::create_dir_all(work.join("deep/deeper")).expect("the work tree is made");

        let mut filler = String::new();
        for round in 0..400 {
            filler.push_str(&format!("line {round} of a file that compresses well\n"));
        }
        std::fs::write(work.join("README.md"), "# title\n\nbody\n").unwrap();
        std::fs::write(work.join("deep/one.txt"), &filler).unwrap();
        std::fs::write(
            work.join("deep/deeper/two.txt"),
            format!("{filler}and one more\n"),
        )
        .unwrap();
        std::fs::write(
            work.join("binary.bin"),
            (0u8..=255).cycle().take(9000).collect::<Vec<u8>>(),
        )
        .unwrap();

        let run = |args: &[&str]| {
            let done = std::process::Command::new("git")
                .args(args)
                .current_dir(&work)
                .output()
                .expect("git runs");
            assert!(done.status.success(), "git {args:?}: {done:?}");
            done.stdout
        };
        run(&["init", "--quiet", "--initial-branch=main"]);
        run(&["config", "user.email", "a@b"]);
        run(&["config", "user.name", "A"]);
        run(&["add", "."]);
        run(&["commit", "--quiet", "-m", "first"]);
        std::fs::write(work.join("deep/one.txt"), format!("{filler}changed\n")).unwrap();
        run(&["add", "."]);
        run(&["commit", "--quiet", "-m", "second"]);
        run(&["repack", "-a", "-d", "--quiet"]);

        let head = String::from_utf8(run(&["rev-parse", "HEAD"]))
            .unwrap()
            .trim()
            .to_string();
        let packs: Vec<std::path::PathBuf> = std::fs::read_dir(work.join(".git/objects/pack"))
            .expect("the pack folder is there")
            .filter_map(|entry| entry.ok().map(|one| one.path()))
            .filter(|path| path.extension().is_some_and(|end| end == "pack"))
            .collect();
        assert_eq!(packs.len(), 1, "one pack was expected");

        let bytes = std::fs::read(&packs[0]).expect("the pack is read");
        let pack = git::unpack(&bytes).expect("the pack resolves");

        let listed =
            String::from_utf8(run(&["cat-file", "--batch-all-objects", "--batch-check"])).unwrap();
        let mut counted = 0usize;
        for line in listed.lines() {
            let mut parts = line.split_whitespace();
            let (Some(id), Some(kind)) = (parts.next(), parts.next()) else {
                continue;
            };
            let named = git::of_hex(id).expect("git names an object in hex");
            let held = pack
                .get(&named)
                .unwrap_or_else(|| panic!("{id} is missing"));
            assert_eq!(held.kind.as_str(), kind, "{id} is read as the wrong kind");
            assert_eq!(git::to_hex(&git::identify(held.kind, &held.body)), id);
            counted += 1;
        }
        assert_eq!(
            counted,
            pack.len(),
            "the pack holds objects git does not list"
        );

        let into = std::env::temp_dir().join("omni_git_conformance_out");
        let _ = std::fs::remove_dir_all(&into);
        let named = git::of_hex(&head).expect("HEAD is hex");
        let written = git::checkout(&pack, &named, &into).expect("the tree is written");
        assert_eq!(written.files, 4);

        for relative in [
            "README.md",
            "deep/one.txt",
            "deep/deeper/two.txt",
            "binary.bin",
        ] {
            assert_eq!(
                std::fs::read(into.join(relative)).unwrap(),
                std::fs::read(work.join(relative)).unwrap(),
                "{relative} differs from what git checked out"
            );
        }
        let _ = std::fs::remove_dir_all(&into);
        let _ = std::fs::remove_dir_all(&work);
    }

    #[test]
    fn inflate_reads_what_an_independent_compressor_wrote() {
        if !python_available() {
            assert!(
                std::env::var("OMNI_REQUIRE_INFLATE_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_INFLATE_CONFORMANCE is set but no independent compressor is here"
            );
            eprintln!("inflate: no independent compressor is available here");
            return;
        }

        let mut seed = 0x51ed_2701_9fa3_1c5du64;
        let mut next = || {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            seed
        };

        let mut cases: Vec<Vec<u8>> = vec![
            Vec::new(),
            b"a".to_vec(),
            b"the same words the same words the same words the same words".to_vec(),
            vec![0u8; 70_000],
            (0..=255u8).cycle().take(100_000).collect(),
        ];
        for size in [1usize, 17, 255, 4096, 33_000] {
            cases.push((0..size).map(|_| (next() & 0xff) as u8).collect());
        }
        let mut lumpy = Vec::new();
        for _ in 0..2_000 {
            let run = (next() % 40) as usize;
            let byte = (next() & 0xff) as u8;
            lumpy.extend(std::iter::repeat_n(byte, run));
        }
        cases.push(lumpy);

        let mut checked = 0usize;
        for case in &cases {
            for level in [0u32, 1, 6, 9] {
                let Some(packed) = python_compress(case, level, false) else {
                    continue;
                };
                let read = crate::inflate::zlib(&packed).unwrap_or_else(|error| {
                    panic!(
                        "level {level}, {} bytes: {} {}",
                        case.len(),
                        error.code,
                        error.message
                    )
                });
                assert_eq!(&read, case, "level {level}, {} bytes", case.len());

                let Some(raw) = python_compress(case, level, true) else {
                    continue;
                };
                assert_eq!(&crate::inflate::raw(&raw).unwrap(), case);
                checked += 2;
            }
        }

        assert!(checked >= 20, "only {checked} streams were checked");
        eprintln!(
            "inflate: {checked} streams written by an independent compressor read back exactly, \
             across stored, fixed and dynamic blocks"
        );
    }

    #[test]
    fn inflate_refuses_a_stream_that_has_been_damaged() {
        if !python_available() {
            eprintln!("inflate: no independent compressor is available here");
            return;
        }
        let plain: Vec<u8> = (0..5_000u32).map(|value| (value % 251) as u8).collect();
        let Some(packed) = python_compress(&plain, 6, false) else {
            return;
        };
        assert_eq!(crate::inflate::zlib(&packed).unwrap(), plain);

        let mut wrong_header = packed.clone();
        wrong_header[0] ^= 0x10;
        assert!(crate::inflate::zlib(&wrong_header).is_err());

        let mut wrong_check = packed.clone();
        let last = wrong_check.len() - 1;
        wrong_check[last] ^= 0x01;
        assert_eq!(
            crate::inflate::zlib(&wrong_check).unwrap_err().code,
            "EI106"
        );

        let truncated = &packed[..packed.len() - 8];
        assert!(crate::inflate::zlib(truncated).is_err());

        assert!(crate::inflate::zlib(&[]).is_err());
        assert_eq!(
            crate::inflate::zlib(&[0x78, 0x9c, 0, 0, 0, 0])
                .unwrap_err()
                .code,
            "EI101",
            "a header with no deflate payload behind it ends before its data"
        );
        assert_eq!(
            crate::inflate::zlib(&[0x78, 0x9c, 0x06, 0, 0, 0, 0])
                .unwrap_err()
                .code,
            "EI135",
            "block type three is the one the format reserves"
        );
    }

    #[test]
    fn the_image_reader_accepts_every_real_png_it_is_shown() {
        let mut roots: Vec<std::path::PathBuf> = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            std::env::var("ANDROID_SDK_ROOT").ok(),
            Some("/usr/share/icons".to_string()),
            Some("/usr/share/pixmaps".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                roots.push(path);
            }
        }

        let mut files = Vec::new();
        for root in &roots {
            gather_png_files(root, &mut files, 200);
        }

        if files.is_empty() {
            assert!(
                std::env::var("OMNI_REQUIRE_IMAGE_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_IMAGE_CONFORMANCE is set but no PNG files were found, so the \
                 image reader was never shown one written by another tool"
            );
            eprintln!("image conformance: no PNG files are available here");
            return;
        }

        let mut read = 0usize;
        let mut oversized = 0usize;
        for file in &files {
            let bytes = std::fs::read(file).unwrap();
            match crate::image::read_png(&bytes) {
                Ok(png) => {
                    let width = u32::from_be_bytes([bytes[16], bytes[17], bytes[18], bytes[19]]);
                    let height = u32::from_be_bytes([bytes[20], bytes[21], bytes[22], bytes[23]]);
                    assert_eq!(png.width, width, "{}", file.display());
                    assert_eq!(png.height, height, "{}", file.display());
                    assert_eq!(png.bit_depth, bytes[24], "{}", file.display());
                    assert_eq!(png.bytes, bytes.len(), "{}", file.display());
                    assert!(png.chunks >= 3, "{}", file.display());
                    read += 1;
                }
                Err(error) if error.code == "EM015" => oversized += 1,
                Err(error) => panic!(
                    "the reader refused a real PNG: {} {} {}\n{:?}",
                    file.display(),
                    error.code,
                    error.message,
                    error.context
                ),
            }
        }

        assert!(read > 0, "no PNG was read");
        eprintln!(
            "image conformance: {read} PNG files written by other tools read here, \
             {oversized} refused only for being larger than an icon"
        );
    }

    #[test]
    fn every_real_png_decodes_and_what_this_build_writes_reads_back() {
        let mut roots: Vec<std::path::PathBuf> = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                roots.push(path);
            }
        }
        let mut files = Vec::new();
        for root in &roots {
            gather_png_files(root, &mut files, 200);
        }
        if files.is_empty() {
            assert!(
                std::env::var("OMNI_REQUIRE_IMAGE_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_IMAGE_CONFORMANCE is set but no PNG files were found"
            );
            eprintln!("codec: no PNG files are available here");
            return;
        }

        let mut decoded = 0usize;
        let mut interlaced = 0usize;
        let mut source_bytes = 0usize;
        let mut written_bytes = 0usize;

        for file in &files {
            let bytes = std::fs::read(file).unwrap();
            let raster = match crate::image::decode(&bytes) {
                Ok(raster) => raster,
                Err(error) if error.code == "EM032" => {
                    interlaced += 1;
                    continue;
                }
                Err(error) if error.code == "EM015" => continue,
                Err(error) => panic!(
                    "the codec refused a real PNG: {} {} {}\n{:?}",
                    file.display(),
                    error.code,
                    error.message,
                    error.context
                ),
            };

            let header = crate::image::read_png(&bytes).unwrap();
            assert_eq!(raster.width, header.width, "{}", file.display());
            assert_eq!(raster.height, header.height, "{}", file.display());
            assert_eq!(
                raster.pixels.len(),
                raster.width as usize * raster.height as usize * 4
            );

            let written = crate::image::encode(&raster).unwrap();
            crate::image::read_png(&written).unwrap_or_else(|error| {
                panic!(
                    "this build wrote a PNG it will not read: {} {}",
                    error.code, error.message
                )
            });
            let again = crate::image::decode(&written).unwrap();
            assert_eq!(again.width, raster.width);
            assert_eq!(again.height, raster.height);
            assert_eq!(
                again.pixels,
                raster.pixels,
                "{} did not survive a write and a read",
                file.display()
            );

            decoded += 1;
            source_bytes += bytes.len();
            written_bytes += written.len();
        }

        assert!(decoded > 0, "no PNG was decoded");
        assert!(
            written_bytes * 10 < source_bytes * 11,
            "this build wrote {written_bytes} bytes where the tools that made these images wrote \
             {source_bytes}. Within a tenth is the bar an encoder that picks its own colour type, \
             palette, filter and Huffman tables should clear; further from it means one of those \
             stopped working."
        );
        eprintln!(
            "codec: {decoded} images written by other tools decoded to pixels, written again by \
             this build and read back identical ({source_bytes} bytes in, {written_bytes} out, \
             {interlaced} interlaced refused)"
        );
    }

    #[test]
    fn the_pixels_of_a_known_image_are_the_ones_an_independent_reader_sees() {
        if !python_available() {
            eprintln!("codec: no independent reader is available here");
            return;
        }

        let directory = temp_directory("omni-codec");
        let source = directory.join("made.png");
        let dump = directory.join("pixels.txt");
        let program = format!(
            "import zlib,struct\n\
             w,h=7,5\n\
             rows=b''\n\
             for y in range(h):\n\
             \x20   rows+=b'\\x00'\n\
             \x20   for x in range(w):\n\
             \x20       rows+=bytes([(x*31)%256,(y*57)%256,(x*y*13)%256,(255-(x*9))%256])\n\
             def chunk(k,b):\n\
             \x20   return struct.pack('>I',len(b))+k+b+struct.pack('>I',zlib.crc32(k+b)&0xffffffff)\n\
             png=b'\\x89PNG\\r\\n\\x1a\\n'\n\
             png+=chunk(b'IHDR',struct.pack('>IIBBBBB',w,h,8,6,0,0,0))\n\
             png+=chunk(b'IDAT',zlib.compress(rows,9))\n\
             png+=chunk(b'IEND',b'')\n\
             open(r'{}','wb').write(png)\n\
             open(r'{}','w').write(','.join(str(v) for v in rows if True))\n",
            source.to_str().unwrap(),
            dump.to_str().unwrap(),
        );
        let made = std::process::Command::new("python3")
            .arg("-c")
            .arg(&program)
            .output()
            .unwrap();
        assert!(
            made.status.success(),
            "{}",
            String::from_utf8_lossy(&made.stderr)
        );

        let bytes = std::fs::read(&source).unwrap();
        let raster = crate::image::decode(&bytes).expect("a PNG another tool wrote must decode");
        assert_eq!(raster.width, 7);
        assert_eq!(raster.height, 5);
        for y in 0..5u32 {
            for x in 0..7u32 {
                assert_eq!(
                    raster.at(x, y),
                    [
                        ((x * 31) % 256) as u8,
                        ((y * 57) % 256) as u8,
                        ((x * y * 13) % 256) as u8,
                        ((255 - (x * 9)) % 256) as u8,
                    ],
                    "pixel {x},{y}"
                );
            }
        }

        std::fs::remove_dir_all(&directory).ok();
        eprintln!("codec: every pixel of a known image matches what it was written with");
    }

    #[test]
    fn a_launcher_set_is_every_size_android_asks_for_in_both_shapes() {
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 12);
            }
        }
        let Some(source) = files.into_iter().find(|file| {
            std::fs::read(file)
                .ok()
                .and_then(|bytes| crate::image::decode(&bytes).ok())
                .map(|raster| raster.width >= 24 && raster.height >= 24)
                .unwrap_or(false)
        }) else {
            eprintln!("launcher: no usable PNG is available here");
            return;
        };

        let bytes = std::fs::read(&source).unwrap();
        let set = crate::image::launcher_set(&bytes).expect("a launcher set must be produced");
        assert_eq!(
            set.len(),
            crate::image::launcher_files_expected().len(),
            "what is written and what is read back have to be the same list"
        );

        for made in &set {
            if made.name.ends_with(".xml") {
                let text = String::from_utf8(made.bytes.clone()).expect("the icon is text");
                assert!(text.contains("<adaptive-icon"), "{text}");
                assert!(text.contains(crate::image::FOREGROUND_NAME), "{text}");
                assert!(text.contains(crate::image::BACKGROUND_NAME), "{text}");
                assert!(text.contains(crate::image::MONOCHROME_NAME), "{text}");
                continue;
            }
            let header = crate::image::read_png(&made.bytes)
                .unwrap_or_else(|error| panic!("{} {}", error.code, error.message));
            assert_eq!(header.width, made.edge, "{} {}", made.folder, made.name);
            assert_eq!(header.height, made.edge);
            assert!(!header.interlaced);

            let back = crate::image::decode(&made.bytes)
                .expect("a launcher icon this build wrote must read back");
            assert_eq!(back.width, made.edge, "{} {}", made.folder, made.name);
            assert_eq!(back.height, made.edge);
        }

        for (folder, layer) in crate::image::ADAPTIVE_SIZES {
            let front = set
                .iter()
                .find(|made| made.folder == *folder && made.name == crate::image::FOREGROUND_NAME)
                .expect("every density carries a foreground");
            let pixels = crate::image::decode(&front.bytes).unwrap();
            assert_eq!(pixels.width, *layer);
            assert_eq!(pixels.at(0, 0)[3], 0, "{folder}: the corner must be clear");
            assert_eq!(
                pixels.at(layer / 2, 1)[3],
                0,
                "{folder}: the top edge is outside the safe zone"
            );

            let mono = set
                .iter()
                .find(|made| made.folder == *folder && made.name == crate::image::MONOCHROME_NAME)
                .expect("and a monochrome layer beside it");
            let flat = crate::image::decode(&mono.bytes).unwrap();
            for (x, y) in [(layer / 2, layer / 2), (layer / 3, layer / 2)] {
                let held = flat.at(x, y);
                assert_eq!(
                    [held[0], held[1], held[2]],
                    [0, 0, 0],
                    "{folder}: a monochrome layer carries shape and no colour"
                );
                assert_eq!(
                    held[3],
                    pixels.at(x, y)[3],
                    "{folder}: and the shape is the foreground's own"
                );
            }
        }

        let ground = set
            .iter()
            .find(|made| made.name == crate::image::BACKGROUND_NAME)
            .expect("a background to put it on");
        let filled = crate::image::decode(&ground.bytes).unwrap();
        let corner = filled.at(0, 0);
        assert_eq!(corner[3], 255, "the background is opaque");
        assert_eq!(
            corner,
            filled.at(filled.width - 1, filled.height - 1),
            "and one colour throughout"
        );

        for (folder, edge) in crate::image::LAUNCHER_SIZES {
            let square = set
                .iter()
                .find(|made| made.folder == *folder && made.name == "ic_launcher")
                .unwrap();
            let round = set
                .iter()
                .find(|made| made.folder == *folder && made.name == "ic_launcher_round")
                .unwrap();
            let square_pixels = crate::image::decode(&square.bytes).unwrap();
            let round_pixels = crate::image::decode(&round.bytes).unwrap();

            assert_eq!(
                square_pixels.at(edge / 2, edge / 2),
                round_pixels.at(edge / 2, edge / 2),
                "the centre of the round icon is the centre of the square one"
            );
            assert_eq!(
                round_pixels.at(0, 0)[3],
                0,
                "a corner of the round icon at {edge} is outside the circle and must be clear"
            );
            assert_eq!(
                round_pixels.at(edge - 1, edge - 1)[3],
                0,
                "the opposite corner at {edge} must be clear too"
            );
        }

        let total: usize = set.iter().map(|made| made.bytes.len()).sum();
        eprintln!(
            "launcher: {} images from one source, {} to {} pixels, square and round, {total} bytes",
            set.len(),
            crate::image::LAUNCHER_SIZES[0].1,
            crate::image::LAUNCHER_SIZES[crate::image::LAUNCHER_SIZES.len() - 1].1,
        );
    }

    #[test]
    fn the_image_reader_refuses_a_png_that_has_been_damaged() {
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 4);
            }
        }
        let Some(file) = files.into_iter().find(|file| {
            std::fs::read(file)
                .ok()
                .is_some_and(|bytes| crate::image::read_png(&bytes).is_ok())
        }) else {
            eprintln!("image conformance: no PNG file is available here");
            return;
        };
        let sound = std::fs::read(&file).unwrap();
        crate::image::read_png(&sound).expect("the file must read before it is damaged");

        let mut wrong_signature = sound.clone();
        wrong_signature[1] = b'Q';
        assert_eq!(
            crate::image::read_png(&wrong_signature).unwrap_err().code,
            "EM002"
        );

        let mut flipped = sound.clone();
        flipped[20] ^= 0x01;
        assert_eq!(crate::image::read_png(&flipped).unwrap_err().code, "EM006");

        let truncated = &sound[..sound.len() - 1];
        let refused = crate::image::read_png(truncated).unwrap_err();
        assert!(
            refused.code == "EM005" || refused.code == "EM003" || refused.code == "EM006",
            "{} {}",
            refused.code,
            refused.message
        );

        let mut trailing = sound.clone();
        trailing.push(0);
        assert_eq!(crate::image::read_png(&trailing).unwrap_err().code, "EM018");

        assert_eq!(crate::image::read_png(&[]).unwrap_err().code, "EM002");
        assert_eq!(
            crate::image::read_png(&crate::image::SIGNATURE)
                .unwrap_err()
                .code,
            "EM016"
        );
    }

    #[test]
    fn the_editor_reads_writes_and_stays_inside_the_project() {
        let directory = temp_directory("omni-workspace");
        let root = directory.join("Edited");
        let text = root.to_str().unwrap().to_string();

        crate::scaffold::create(
            &text,
            &crate::scaffold::Spec {
                languages: vec!["kotlin".to_string()],
                ..Default::default()
            },
        )
        .unwrap();

        let listed = crate::workspace::list_projects(directory.to_str().unwrap());
        assert_eq!(listed.len(), 1);
        assert_eq!(listed[0].package, crate::scaffold::DEFAULT_PACKAGE);
        assert_eq!(
            listed[0].label, "My App",
            "the manifest points at a string resource, and the listing resolves it"
        );
        assert_eq!(listed[0].version_name, "1.0.0");
        assert_eq!(listed[0].version_code, 1);
        assert_eq!(listed[0].min_sdk, 30);
        assert_eq!(
            listed[0].target_sdk,
            u64::from(crate::scaffold::NEWEST_DESCRIBED)
        );
        assert!(
            listed[0].icon.is_some(),
            "a project shows the picture it was made with"
        );

        let entries = crate::workspace::tree(&text).unwrap();
        assert!(entries
            .iter()
            .any(|entry| entry.path == "AndroidManifest.xml"));
        assert!(entries
            .iter()
            .any(|entry| entry.path == "Kotlin" && entry.folder));

        let manifest = crate::workspace::read_text(&text, "AndroidManifest.xml").unwrap();
        assert!(
            manifest.contains(crate::scaffold::DEFAULT_PACKAGE),
            "{manifest}"
        );

        crate::workspace::create_folder(&text, "Kotlin/com/tr/yt").unwrap();
        crate::workspace::write_text(&text, "Kotlin/com/tr/yt/Screen.kt", "class Screen\n")
            .unwrap();
        assert_eq!(
            crate::workspace::read_text(&text, "Kotlin/com/tr/yt/Screen.kt").unwrap(),
            "class Screen\n"
        );

        for escape in [
            "../outside.txt",
            "/etc/passwd",
            "Kotlin/../../outside.txt",
            "Kotlin/./../../outside.txt",
            "",
        ] {
            let refused = crate::workspace::write_text(&text, escape, "no")
                .expect_err("a path that leaves the project must be refused");
            assert_eq!(refused.code, "EW100", "{escape}: {}", refused.message);
        }
        assert!(!directory.join("outside.txt").exists());
        assert!(!std::path::Path::new("/etc/passwd")
            .metadata()
            .map(|data| data.len() == 2)
            .unwrap_or(false));

        std::fs::write(root.join("Kotlin/Binary.bin"), [0xff, 0xfe, 0x00, 0x01]).unwrap();
        assert_eq!(
            crate::workspace::read_text(&text, "Kotlin/Binary.bin")
                .unwrap_err()
                .code,
            "EW113"
        );

        let bin = directory.join("Trash").to_str().unwrap().to_string();
        let now = 1_787_000_000;
        assert_eq!(
            crate::workspace::remove(&text, "AndroidManifest.xml", &bin, now)
                .unwrap_err()
                .code,
            "EW140"
        );
        let thrown = crate::workspace::remove(&text, "Kotlin/Binary.bin", &bin, now).unwrap();
        assert!(!root.join("Kotlin/Binary.bin").exists());
        assert_eq!(thrown.name, "Binary.bin");
        assert_eq!(thrown.bytes, 4);

        crate::workspace::rename(&text, "Kotlin/App.kt", "Kotlin/Screen.kt").unwrap();
        assert!(!root.join("Kotlin/App.kt").exists());
        assert!(root.join("Kotlin/Screen.kt").is_file());
        assert_eq!(
            crate::workspace::rename(&text, "Kotlin/Screen.kt", "AndroidManifest.xml")
                .unwrap_err()
                .code,
            "EW150"
        );
        assert_eq!(
            crate::workspace::rename(&text, "Kotlin", "Kotlin/Inside")
                .unwrap_err()
                .code,
            "EW153"
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn copying_carries_a_whole_folder_and_never_over_something() {
        let directory = temp_directory("omni-copy");
        let root = directory.join("Held");
        let text = root.to_str().unwrap().to_string();
        crate::scaffold::create(&text, &crate::scaffold::Spec::default()).unwrap();

        crate::workspace::write_text(&text, "Java/one/A.java", "class A {}\n").unwrap();
        crate::workspace::write_text(&text, "Java/one/deep/B.java", "class B {}\n").unwrap();
        std::fs::write(root.join("Java/one/held.bin"), [0u8, 1, 2, 255]).unwrap();

        let put = crate::workspace::copy(&text, "Java/one", "Java/two").unwrap();
        assert_eq!(put, "Java/two");
        assert_eq!(
            crate::workspace::read_text(&text, "Java/two/A.java").unwrap(),
            "class A {}\n"
        );
        assert_eq!(
            crate::workspace::read_text(&text, "Java/two/deep/B.java").unwrap(),
            "class B {}\n",
            "a folder is copied all the way down"
        );
        assert_eq!(
            std::fs::read(root.join("Java/two/held.bin")).unwrap(),
            vec![0u8, 1, 2, 255],
            "bytes that are not text come across unchanged"
        );
        assert!(
            root.join("Java/one/A.java").is_file(),
            "copying leaves what it copied"
        );

        assert_eq!(
            crate::workspace::copy(&text, "Java/one", "Java/two")
                .unwrap_err()
                .code,
            "EW162",
            "copying over something is refused rather than silently replacing it"
        );
        assert_eq!(
            crate::workspace::copy(&text, "Java/one", "Java/one/inside")
                .unwrap_err()
                .code,
            "EW163"
        );
        assert_eq!(
            crate::workspace::copy(&text, "Java/nothing", "Java/three")
                .unwrap_err()
                .code,
            "EW161"
        );
        assert_eq!(
            crate::workspace::copy(&text, "Java/one/A.java", "../outside.java")
                .unwrap_err()
                .code,
            "EW100",
            "a copy cannot leave the project"
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_save_that_cannot_finish_leaves_what_was_there_before() {
        let directory = temp_directory("omni-atomic-save");
        let root = directory.join("Held");
        let text = root.to_str().unwrap().to_string();
        crate::scaffold::create(&text, &crate::scaffold::Spec::default()).unwrap();

        let held = "Java/Kept.java";
        crate::workspace::write_text(&text, held, "the first version\n").unwrap();
        let beside = root.join("Java").join("Kept.java.part");
        std::fs::create_dir(&beside).expect("something in the way of the temporary name");

        let refused = crate::workspace::write_text(&text, held, "the second version\n")
            .expect_err("the save cannot finish");
        assert_eq!(refused.code, "EW122");
        assert_eq!(
            crate::workspace::read_text(&text, held).unwrap(),
            "the first version\n",
            "a save that could not finish took the file with it"
        );

        std::fs::remove_dir(&beside).unwrap();
        crate::workspace::write_text(&text, held, "the second version\n").unwrap();
        assert_eq!(
            crate::workspace::read_text(&text, held).unwrap(),
            "the second version\n"
        );
        assert!(!beside.exists(), "a save left its temporary file behind");

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn what_is_deleted_waits_a_day_in_the_trash_and_can_be_put_back() {
        let directory = temp_directory("omni-trash");
        let root = directory.join("Held");
        let text = root.to_str().unwrap().to_string();
        crate::scaffold::create(&text, &crate::scaffold::Spec::default()).unwrap();
        let bin = directory
            .join(crate::trash::FOLDER)
            .to_str()
            .unwrap()
            .to_string();
        let now = 1_787_000_000;

        crate::workspace::write_text(&text, "Kotlin/Gone.kt", "class Gone\n").unwrap();
        let thrown = crate::workspace::remove(&text, "Kotlin/Gone.kt", &bin, now).unwrap();
        assert!(!root.join("Kotlin/Gone.kt").exists(), "it left the project");
        assert_eq!(
            thrown.expires_at - thrown.deleted_at,
            crate::trash::HELD_SECONDS,
            "it is held for a day"
        );

        let held = crate::trash::list(&bin, now);
        assert_eq!(held.len(), 1);
        assert_eq!(held[0].name, "Gone.kt");
        assert_eq!(held[0].seconds_left(now), crate::trash::HELD_SECONDS);

        crate::trash::restore(&bin, &thrown.id, now).unwrap();
        assert_eq!(
            crate::workspace::read_text(&text, "Kotlin/Gone.kt").unwrap(),
            "class Gone\n",
            "what came back is what went in"
        );
        assert!(crate::trash::list(&bin, now).is_empty());

        let again = crate::workspace::remove(&text, "Kotlin/Gone.kt", &bin, now).unwrap();
        crate::workspace::write_text(&text, "Kotlin/Gone.kt", "written since\n").unwrap();
        assert_eq!(
            crate::trash::restore(&bin, &again.id, now)
                .unwrap_err()
                .code,
            "ET012",
            "restoring never writes over what is there now"
        );

        let a_day_later = now + crate::trash::HELD_SECONDS;
        assert!(
            crate::trash::list(&bin, a_day_later).is_empty(),
            "a day on, the trash no longer offers it"
        );
        assert_eq!(
            crate::trash::restore(&bin, &again.id, a_day_later)
                .unwrap_err()
                .code,
            "ET011"
        );
        assert_eq!(crate::trash::sweep(&bin, a_day_later), 1);
        assert!(!std::path::Path::new(&bin).join(&again.id).exists());

        let folder = crate::workspace::remove(&text, "Kotlin", &bin, now).unwrap();
        assert!(folder.folder, "a folder goes to the trash whole");
        assert!(!root.join("Kotlin").exists());
        crate::trash::restore(&bin, &folder.id, now).unwrap();
        assert!(root.join("Kotlin").is_dir());

        crate::workspace::remove(&text, "Kotlin", &bin, now).unwrap();
        assert_eq!(crate::trash::empty(&bin), 1);
        assert!(crate::trash::list(&bin, now).is_empty());

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_gradle_project_is_read_the_way_gradle_reads_it() {
        let directory = temp_directory("omni-gradle-read");
        std::fs::create_dir_all(directory.join("app/src/main/cpp")).unwrap();
        std::fs::create_dir_all(directory.join("gradle")).unwrap();

        std::fs::write(
            directory.join("settings.gradle.kts"),
            "pluginManagement { repositories { google(); mavenCentral() } }\n\
             rootProject.name = \"Held\"\n\
             include(\":app\")\n\
             include(\":core\", \":ui\")\n",
        )
        .unwrap();

        std::fs::write(
            directory.join("gradle/libs.versions.toml"),
            "[versions]\n\
             core = \"1.13.1\"\n\
             room = \"2.6.1\"\n\
             \n\
             [libraries]\n\
             androidx-core-ktx = { module = \"androidx.core:core-ktx\", version.ref = \"core\" }\n\
             room-runtime = { group = \"androidx.room\", name = \"room-runtime\", version.ref = \"room\" }\n\
             room-compiler = { module = \"androidx.room:room-compiler\", version.ref = \"room\" }\n\
             material = \"com.google.android.material:material:1.12.0\"\n\
             \n\
             [plugins]\n\
             android-application = { id = \"com.android.application\", version = \"8.5.0\" }\n",
        )
        .unwrap();

        std::fs::write(
            directory.join("app/build.gradle.kts"),
            "// the comment at the top { is not a block\n\
             plugins {\n\
             \x20   id(\"com.android.application\")\n\
             \x20   id(\"org.jetbrains.kotlin.android\")\n\
             \x20   id(\"com.google.devtools.ksp\")\n\
             \x20   id(\"com.google.gms.google-services\")\n\
             }\n\
             \n\
             android {\n\
             \x20   namespace = \"com.tr.yt\"\n\
             \x20   compileSdk = 35\n\
             \n\
             \x20   defaultConfig {\n\
             \x20       applicationId = \"com.tr.yt.free\"\n\
             \x20       minSdk = 24\n\
             \x20       targetSdk = 34\n\
             \x20       versionCode = 17\n\
             \x20       versionName = \"2.3.1\"\n\
             \x20       externalNativeBuild { cmake { cppFlags += \"-std=c++17\" } }\n\
             \x20   }\n\
             \n\
             \x20   buildTypes {\n\
             \x20       release {\n\
             \x20           isMinifyEnabled = true\n\
             \x20           isShrinkResources = true\n\
             \x20       }\n\
             \x20   }\n\
             \n\
             \x20   compileOptions {\n\
             \x20       sourceCompatibility = JavaVersion.VERSION_11\n\
             \x20       targetCompatibility = JavaVersion.VERSION_11\n\
             \x20   }\n\
             \n\
             \x20   externalNativeBuild { cmake { path = \"src/main/cpp/CMakeLists.txt\" } }\n\
             }\n\
             \n\
             dependencies {\n\
             \x20   implementation(libs.androidx.core.ktx)\n\
             \x20   implementation(libs.room.runtime)\n\
             \x20   implementation(\"com.squareup.okhttp3:okhttp:4.12.0\")\n\
             \x20   implementation(project(\":core\"))\n\
             \x20   ksp(libs.room.compiler)\n\
             \x20   testImplementation(\"junit:junit:4.13.2\")\n\
             }\n",
        )
        .unwrap();

        let text = directory.to_str().unwrap();
        assert!(crate::gradle::looks_like_one(text));
        assert_eq!(
            crate::gradle::application_module(text).as_deref(),
            Some("app"),
            "the module that applies the application plugin is the one to build"
        );

        let found = crate::gradle::read(text, "app").expect("the build file reads");
        assert_eq!(found.settings.namespace, "com.tr.yt");
        assert_eq!(found.settings.application_id, "com.tr.yt.free");
        assert_eq!(found.settings.compile_sdk, 35);
        assert_eq!(found.settings.min_sdk, 24);
        assert_eq!(found.settings.target_sdk, 34);
        assert_eq!(found.settings.version_code, 17);
        assert_eq!(found.settings.version_name, "2.3.1");
        assert_eq!(found.settings.java.source, "11");
        assert_eq!(found.settings.native.path, "src/main/cpp/CMakeLists.txt");
        assert!(found.settings.shrink, "release minifies, so this does too");

        let named: Vec<&str> = found
            .settings
            .dependencies
            .iter()
            .map(|one| one.name.as_str())
            .collect();
        assert!(named.contains(&"androidx.core:core-ktx"), "{named:?}");
        assert!(named.contains(&"androidx.room:room-runtime"), "{named:?}");
        assert!(named.contains(&"com.squareup.okhttp3:okhttp"), "{named:?}");
        assert!(
            !named.contains(&"junit:junit"),
            "a test-only dependency is not one the app carries"
        );
        assert_eq!(
            found
                .settings
                .dependencies
                .iter()
                .find(|one| one.name == "androidx.core:core-ktx")
                .map(|one| one.version.as_str()),
            Some("1.13.1"),
            "the version comes out of the catalogue"
        );
        assert_eq!(
            found.processors.first().map(|one| one.name.as_str()),
            Some("androidx.room:room-compiler"),
            "what ksp is given is a processor, not a library"
        );
        assert!(
            found.modules.contains(&"core".to_string()),
            "{:?}",
            found.modules
        );
        assert!(
            found.modules.contains(&"ui".to_string()),
            "{:?}",
            found.modules
        );
        assert!(found.settings.languages.contains(&"kotlin".to_string()));
        assert!(found.settings.languages.contains(&"cpp".to_string()));
        assert_eq!(
            found.unread,
            vec!["com.google.gms.google-services".to_string()],
            "a plugin this cannot run is said out loud, not swallowed"
        );

        eprintln!(
            "gradle: read {} dependencies, {} processors and {} other modules",
            found.settings.dependencies.len(),
            found.processors.len(),
            found.modules.len()
        );
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_standard_gradle_project_opens_as_one_this_builds() {
        let directory = temp_directory("omni-gradle-adopt");
        let from = directory.join("Sent");
        std::fs::create_dir_all(from.join("app/src/main/java/com/tr/yt")).unwrap();
        std::fs::create_dir_all(from.join("app/src/main/res/values")).unwrap();
        std::fs::create_dir_all(from.join("app/src/main/cpp")).unwrap();
        std::fs::create_dir_all(from.join("app/src/test/java")).unwrap();
        std::fs::create_dir_all(from.join("core/src/main/java/com/tr/yt/core")).unwrap();
        std::fs::create_dir_all(from.join("app/libs")).unwrap();

        std::fs::write(
            from.join("settings.gradle.kts"),
            "rootProject.name = \"Sent\"\ninclude(\":app\")\ninclude(\":core\")\n",
        )
        .unwrap();
        std::fs::write(from.join("build.gradle.kts"), "plugins { }\n").unwrap();
        std::fs::write(
            from.join("app/build.gradle.kts"),
            "plugins { id(\"com.android.application\") ; id(\"org.jetbrains.kotlin.android\") }\n\
             android {\n\
             \x20   namespace = \"com.tr.yt\"\n\
             \x20   compileSdk = 35\n\
             \x20   defaultConfig { applicationId = \"com.tr.yt\" ; minSdk = 24 ; versionCode = 4 ; versionName = \"1.4\" }\n\
             }\n\
             dependencies { implementation(project(\":core\")) }\n",
        )
        .unwrap();
        std::fs::write(
            from.join("core/build.gradle.kts"),
            "plugins { id(\"com.android.library\") }\nandroid { namespace = \"com.tr.yt.core\" }\n",
        )
        .unwrap();
        std::fs::write(
            from.join("app/src/main/AndroidManifest.xml"),
            "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" \
             package=\"com.tr.yt\"><application android:label=\"Sent\"><activity \
             android:name=\".App\" android:exported=\"true\"/></application></manifest>",
        )
        .unwrap();
        std::fs::write(
            from.join("app/src/main/java/com/tr/yt/App.java"),
            "package com.tr.yt;\npublic class App {}\n",
        )
        .unwrap();
        std::fs::write(
            from.join("app/src/main/java/com/tr/yt/Helper.kt"),
            "package com.tr.yt\nclass Helper\n",
        )
        .unwrap();
        std::fs::write(
            from.join("app/src/test/java/Gone.java"),
            "public class Gone {}\n",
        )
        .unwrap();
        std::fs::write(
            from.join("core/src/main/java/com/tr/yt/core/Core.java"),
            "package com.tr.yt.core;\npublic class Core {}\n",
        )
        .unwrap();
        std::fs::write(
            from.join("app/src/main/res/values/strings.xml"),
            "<resources><string name=\"app_name\">Sent</string></resources>",
        )
        .unwrap();
        std::fs::write(
            from.join("app/src/main/cpp/CMakeLists.txt"),
            "cmake_minimum_required(VERSION 3.22)\n",
        )
        .unwrap();
        std::fs::write(from.join("app/libs/held.jar"), b"not really a jar").unwrap();
        std::fs::write(from.join("app/proguard-rules.pro"), "-dontwarn **\n").unwrap();

        let packed = directory.join("Sent.zip");
        crate::packer::pack(
            directory.to_str().unwrap(),
            &["Sent".to_string()],
            packed.to_str().unwrap(),
            crate::packer::ZIP,
            "",
        )
        .expect("the project packs");

        let root = directory.join("Opened");
        let opened = crate::workspace::unpack(packed.to_str().unwrap(), root.to_str().unwrap(), "")
            .expect("the project opens");
        assert!(opened.adopted, "a Gradle project is taken in as one");
        assert!(
            opened.settings_written,
            "opening one writes the settings this builds from"
        );

        assert!(
            root.join("AndroidManifest.xml").is_file(),
            "the manifest is at the root"
        );
        assert!(root.join("Java/com/tr/yt/App.java").is_file());
        assert!(
            root.join("Kotlin/com/tr/yt/Helper.kt").is_file(),
            "a .kt under src/main/java still goes where Kotlin lives"
        );
        assert!(
            root.join("Java/com/tr/yt/core/Core.java").is_file(),
            "a library module's source comes with it"
        );
        assert!(root.join("Res/values/strings.xml").is_file());
        assert!(root.join("Native/CMakeLists.txt").is_file());
        assert!(root.join("Libraries/held.jar").is_file());
        assert!(root.join("proguard-rules.pro").is_file());
        assert!(
            !root.join("Java/Gone.java").is_file(),
            "what only the tests used is not compiled into the app"
        );
        assert!(
            root.join("app/build.gradle.kts").is_file(),
            "the build file it came with is left where it was"
        );

        let held = crate::settings::held(root.to_str().unwrap())
            .unwrap()
            .expect("the settings are written");
        assert_eq!(held.namespace, "com.tr.yt");
        assert_eq!(held.compile_sdk, 35);
        assert_eq!(held.min_sdk, 24);
        assert_eq!(held.version_code, 4);
        assert_eq!(held.version_name, "1.4");
        assert!(held.languages.contains(&"kotlin".to_string()));
        assert!(held.languages.contains(&"cpp".to_string()));

        let ignored = crate::builder::uncompiled_source(root.to_str().unwrap());
        assert_eq!(
            ignored
                .iter()
                .map(|(language, _)| *language)
                .collect::<Vec<&str>>(),
            vec!["kotlin"],
            "only the Kotlin is named as what this build cannot compile: {ignored:?}"
        );

        eprintln!(
            "gradle: took in a two module project, {} files moved into place",
            opened.files
        );
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn what_a_project_names_comes_down_from_maven_with_all_it_leans_on() {
        let directory = temp_directory("omni-maven");
        let root = directory.join("Held");
        let text = root.to_str().unwrap().to_string();
        crate::scaffold::create(&text, &crate::scaffold::Spec::default()).unwrap();

        let mut settings = crate::settings::held(&text).unwrap().unwrap();
        settings.dependencies = vec![crate::settings::Dependency {
            name: "com.squareup.okhttp3:okhttp".to_string(),
            version: "4.12.0".to_string(),
            file: String::new(),
        }];
        crate::settings::write(&text, &settings).unwrap();

        let mut rounds = 0;
        let mut asked = 0;
        loop {
            rounds += 1;
            assert!(rounds < 24, "the plan never settled");
            let plan = crate::maven::plan(&text).expect("the plan is made");
            if plan.done {
                break;
            }
            let mut carried = 0;
            for want in &plan.wanted {
                let into = root.join(&want.path);
                std::fs::create_dir_all(into.parent().unwrap()).unwrap();
                for url in &want.urls {
                    asked += 1;
                    let Some((passed, _)) = tool_runs(
                        "curl",
                        &["-sSfL", "-m", "40", "-o", into.to_str().unwrap(), url],
                    ) else {
                        eprintln!("maven: curl is not here to fetch anything");
                        std::fs::remove_dir_all(&directory).ok();
                        return;
                    };
                    if passed && into.is_file() {
                        carried += 1;
                        break;
                    }
                }
            }
            if carried == 0 {
                eprintln!("maven: nothing came down, so there is nothing to check");
                std::fs::remove_dir_all(&directory).ok();
                return;
            }
        }

        let libraries = root.join(crate::scaffold::LIBRARY_FOLDER);
        let held: Vec<String> = std::fs::read_dir(&libraries)
            .unwrap()
            .flatten()
            .filter(|one| one.path().is_file())
            .map(|one| one.file_name().to_string_lossy().to_string())
            .collect();
        assert!(
            held.contains(&"okhttp-4.12.0.jar".to_string()),
            "what was named did not come down: {held:?}"
        );
        assert!(
            held.iter().any(|one| one.starts_with("okio")),
            "what okhttp leans on did not come with it: {held:?}"
        );
        assert!(
            held.iter().any(|one| one.starts_with("kotlin-stdlib")),
            "the Kotlin runtime okhttp leans on did not come with it: {held:?}"
        );
        for one in &held {
            let bytes = std::fs::metadata(libraries.join(one)).unwrap().len();
            assert!(bytes > 0, "{one} came down empty");
        }
        assert!(
            crate::maven::plan(&text).unwrap().done,
            "asking again wants nothing more"
        );

        eprintln!(
            "maven: {} jars in {rounds} rounds and {asked} requests, from one name",
            held.len()
        );
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_project_keeps_what_it_deletes_in_folders_named_by_the_day() {
        let directory = temp_directory("omni-trash-project");
        let root = directory.join("Held");
        let text = root.to_str().unwrap().to_string();
        crate::scaffold::create(&text, &crate::scaffold::Spec::default()).unwrap();
        let bin = root
            .join(crate::trash::FOLDER)
            .to_str()
            .unwrap()
            .to_string();
        let now = 1_787_000_000;
        let day = crate::trash::day_of(now);

        crate::workspace::write_text(&text, "Kotlin/Gone.kt", "class Gone\n").unwrap();
        let thrown = crate::workspace::remove(&text, "Kotlin/Gone.kt", &bin, now).unwrap();
        assert!(thrown.kept(), "what a project deletes is kept, not timed");
        assert!(
            thrown.id.starts_with(&format!("{day}/")),
            "{} is not filed under the day it was deleted",
            thrown.id
        );
        assert!(root.join(crate::trash::FOLDER).join(&day).is_dir());

        let later = now + 9 * crate::trash::HELD_SECONDS;
        assert_eq!(
            crate::trash::sweep(&bin, later),
            0,
            "a project's trash is never swept out from under it"
        );
        assert_eq!(
            crate::trash::list(&bin, later).len(),
            1,
            "it is still there nine days on"
        );

        crate::trash::restore(&bin, &thrown.id, later).unwrap();
        assert_eq!(
            crate::workspace::read_text(&text, "Kotlin/Gone.kt").unwrap(),
            "class Gone\n"
        );
        assert!(
            !root.join(crate::trash::FOLDER).join(&day).exists(),
            "a day with nothing left in it is forgotten"
        );

        let second = now + 3 * crate::trash::HELD_SECONDS;
        crate::workspace::remove(&text, "Kotlin/Gone.kt", &bin, now).unwrap();
        crate::workspace::write_text(&text, "Kotlin/Gone.kt", "again\n").unwrap();
        crate::workspace::remove(&text, "Kotlin/Gone.kt", &bin, second).unwrap();
        let mut days: Vec<String> = std::fs::read_dir(&bin)
            .unwrap()
            .flatten()
            .filter(|one| one.path().is_dir())
            .map(|one| one.file_name().to_string_lossy().to_string())
            .collect();
        days.sort();
        assert_eq!(
            days,
            vec![day.clone(), crate::trash::day_of(second)],
            "two days deleted on, two folders"
        );
        assert_eq!(crate::trash::list(&bin, second).len(), 2);

        assert_eq!(
            crate::workspace::remove(&text, crate::trash::FOLDER, &bin, second)
                .unwrap_err()
                .code,
            "EW142",
            "the trash is not something the trash can hold"
        );

        assert_eq!(crate::trash::empty(&bin), 2);
        assert!(crate::trash::list(&bin, second).is_empty());
        assert!(
            std::fs::read_dir(&bin).unwrap().flatten().count() == 0,
            "emptying leaves no day behind"
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_project_keeps_the_image_the_developer_chose() {
        let _turn = crate::progress::one_at_a_time();
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 8);
            }
        }
        let Some(source) = files
            .into_iter()
            .find(|file| crate::image::read_png_file(file.to_str().unwrap_or_default()).is_ok())
        else {
            eprintln!("project image: no PNG file is available here");
            return;
        };

        let directory = temp_directory("omni-icon");
        let root = directory.join("Pictured");
        let text = root.to_str().unwrap().to_string();
        crate::scaffold::create(&text, &crate::scaffold::Spec::default()).unwrap();

        let stored = crate::scaffold::set_icon(&text, source.to_str().unwrap()).unwrap();
        assert!(stored.width > 0 && stored.height > 0);
        assert_eq!(
            std::fs::read(&source).unwrap(),
            std::fs::read(crate::scaffold::icon_path(&text)).unwrap()
        );
        let read_back = crate::scaffold::read_icon(&text).expect("the stored image must read");
        assert_eq!(read_back.width, stored.width);
        assert_eq!(read_back.height, stored.height);
        assert!(crate::workspace::describe(&text).unwrap().icon.is_some());

        let not_an_image = root.join("AndroidManifest.xml");
        assert_eq!(
            crate::scaffold::set_icon(&text, not_an_image.to_str().unwrap())
                .unwrap_err()
                .code,
            "EM002"
        );

        let key = crate::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let project = crate::builder::from_project(&text).unwrap();
        let outcome = crate::builder::build(&project, &key, 1_787_000_000, &mut sink).unwrap();
        let archive = archive::read(&outcome.package, &mut sink).unwrap();
        assert!(
            !archive
                .entries()
                .iter()
                .any(|entry| entry.name.contains("Icon.png")),
            "the image is stored with the project, and this build does not claim it reached \
             the package"
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    fn find_bundletool() -> Option<Vec<String>> {
        if let Ok(command) = std::env::var("OMNI_BUNDLETOOL") {
            let parts: Vec<String> = command
                .split_whitespace()
                .map(|part| part.to_string())
                .collect();
            if !parts.is_empty() {
                return Some(parts);
            }
        }

        let home = std::env::var("HOME").unwrap_or_else(|_| "/root".to_string());
        let cache = std::path::PathBuf::from(&home).join(".gradle/caches/modules-2/files-2.1");
        if !cache.join("com.android.tools.build/bundletool").is_dir() {
            return None;
        }

        let mut jars = Vec::new();
        collect_jars(&cache, &mut jars, 0);
        if jars.is_empty() {
            return None;
        }
        jars.sort();
        Some(vec![
            "java".to_string(),
            "-cp".to_string(),
            jars.join(":"),
            "com.android.tools.build.bundletool.BundleToolMain".to_string(),
        ])
    }

    fn collect_jars(root: &std::path::Path, into: &mut Vec<String>, depth: usize) {
        if depth > 8 || into.len() > 4_000 {
            return;
        }
        let Ok(entries) = std::fs::read_dir(root) else {
            return;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                collect_jars(&path, into, depth + 1);
            } else if path.extension().and_then(|e| e.to_str()) == Some("jar") {
                let Some(text) = path.to_str() else { continue };
                if text.contains("-sources") || text.contains("-javadoc") {
                    continue;
                }
                into.push(text.to_string());
            }
        }
    }

    #[test]
    fn the_bundle_writer_produces_a_bundle_bundletool_accepts() {
        let Some(bundletool) = find_bundletool() else {
            assert!(
                std::env::var("OMNI_REQUIRE_BUNDLETOOL").is_err(),
                "OMNI_REQUIRE_BUNDLETOOL is set but bundletool was not found, so the bundle \
                 this build writes was never handed to the tool that judges one"
            );
            eprintln!("bundle conformance: bundletool is not available here");
            return;
        };
        let Some(aapt2) = find_build_tool("aapt2") else {
            assert!(
                std::env::var("OMNI_REQUIRE_BUNDLETOOL").is_err(),
                "OMNI_REQUIRE_BUNDLETOOL is set but aapt2 is missing, and bundletool needs it"
            );
            eprintln!("bundle conformance: aapt2 is not available here");
            return;
        };

        let spec = crate::scaffold::Spec {
            package: "com.tr.yt".to_string(),
            label: "Bundled".to_string(),
            version_name: "1.0.0".to_string(),
            version_code: 3,
            ..crate::scaffold::Spec::default()
        };
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 8);
            }
        }
        let picture = files
            .into_iter()
            .find(|file| crate::image::read_png_file(file.to_str().unwrap_or_default()).is_ok());

        let mut project = crate::builder::from_spec(&spec).unwrap();
        project.icon = picture.as_ref().map(|path| std::fs::read(path).unwrap());
        project.files = vec![
            (
                "lib/arm64-v8a/libomni_core.so".to_string(),
                b"\x7fELF not a real object, only a path to place".to_vec(),
            ),
            (
                "notes.txt".to_string(),
                b"carried at the package root".to_vec(),
            ),
        ];
        let outcome = crate::bundle::write(&project).expect("a compliant project must bundle");
        assert!(outcome.carries_code);
        assert_eq!(outcome.carries_image, project.icon.is_some());
        let images = crate::image::launcher_files_expected().len();
        assert_eq!(
            outcome.entries,
            if outcome.carries_image { 6 + images } else { 5 },
            "config, manifest, dex, a native library, a root file, and when there is an image \
             the resource table and {images} launcher files"
        );

        let directory = temp_directory("omni-bundle");
        let path = directory.join("omni.aab");
        std::fs::write(&path, &outcome.bundle).unwrap();

        let store = directory.join("bundle.jks");
        let keytool = std::process::Command::new("keytool")
            .args([
                "-genkeypair",
                "-keystore",
                store.to_str().unwrap(),
                "-storepass",
                "password",
                "-keypass",
                "password",
                "-alias",
                "omni",
                "-keyalg",
                "RSA",
                "-keysize",
                "2048",
                "-validity",
                "3650",
                "-dname",
                "CN=Omni",
            ])
            .output()
            .expect("keytool must run");
        assert!(
            keytool.status.success(),
            "{}",
            String::from_utf8_lossy(&keytool.stderr)
        );

        let apks = directory.join("omni.apks");
        let mut command = std::process::Command::new(&bundletool[0]);
        command.args(&bundletool[1..]);
        command.args([
            "build-apks",
            &format!("--bundle={}", path.to_str().unwrap()),
            &format!("--output={}", apks.to_str().unwrap()),
            "--mode=universal",
            &format!("--aapt2={}", aapt2.to_str().unwrap()),
            &format!("--ks={}", store.to_str().unwrap()),
            "--ks-pass=pass:password",
            "--ks-key-alias=omni",
            "--key-pass=pass:password",
            "--overwrite",
        ]);
        let built = command.output().expect("bundletool must run");
        let report = format!(
            "{}{}",
            String::from_utf8_lossy(&built.stdout),
            String::from_utf8_lossy(&built.stderr)
        );
        assert!(built.status.success(), "bundletool refused it:\n{report}");

        let unpacked = directory.join("apks");
        std::fs::create_dir_all(&unpacked).unwrap();
        let unzipped = std::process::Command::new("unzip")
            .args([
                "-o",
                "-q",
                apks.to_str().unwrap(),
                "-d",
                unpacked.to_str().unwrap(),
            ])
            .output()
            .unwrap();
        assert!(unzipped.status.success());

        let universal = unpacked.join("universal.apk");
        assert!(universal.is_file(), "bundletool produced no universal APK");

        let dumped = std::process::Command::new(&aapt2)
            .args([
                "dump",
                "xmltree",
                universal.to_str().unwrap(),
                "--file",
                "AndroidManifest.xml",
            ])
            .output()
            .unwrap();
        let tree = String::from_utf8_lossy(&dumped.stdout).to_string();
        assert!(dumped.status.success(), "{tree}");

        let targets = format!(
            "android:targetSdkVersion(0x01010270)={}",
            crate::scaffold::NEWEST_DESCRIBED
        );
        for expected in [
            "A: package=\"com.tr.yt\"",
            "android:versionCode(0x0101021b)=3",
            "android:versionName(0x0101021c)=\"1.0.0\"",
            "android:minSdkVersion(0x0101020c)=30",
            targets.as_str(),
            "android:label(0x01010001)=@0x7f020000",
            "android:allowBackup(0x01010280)=false",
            "android:extractNativeLibs(0x010104ea)=false",
            "E: activity",
            "android:name(0x01010003)=\"com.tr.yt.App\"",
            "android:exported(0x01010010)=true",
            "android.intent.action.MAIN",
            "android.intent.category.LAUNCHER",
        ] {
            assert!(tree.contains(expected), "missing {expected:?} in\n{tree}");
        }

        let extracted = std::process::Command::new("unzip")
            .args(["-p", universal.to_str().unwrap(), "classes.dex"])
            .output()
            .unwrap();
        assert!(extracted.status.success());
        let classes = dex::read(&extracted.stdout, &mut Sink::new()).expect("our dex must read");
        assert_eq!(classes.class_names(), vec!["com.tr.yt.App"]);

        let listed = std::process::Command::new("unzip")
            .args(["-l", universal.to_str().unwrap()])
            .output()
            .unwrap();
        let names = String::from_utf8_lossy(&listed.stdout).to_string();
        assert!(names.contains("lib/arm64-v8a/libomni_core.so"), "{names}");
        assert!(names.contains("notes.txt"), "{names}");

        if outcome.carries_image {
            assert!(names.contains("resources.arsc"), "{names}");
            let badging = std::process::Command::new(&aapt2)
                .args(["dump", "badging", universal.to_str().unwrap()])
                .output()
                .unwrap();
            let reported = String::from_utf8_lossy(&badging.stdout).to_string();
            assert!(badging.status.success(), "{reported}");
            assert!(
                reported.contains("ic_launcher"),
                "bundletool must carry the icon through into the package it builds:\n{reported}"
            );
        }

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "bundle conformance: {} bytes handed to bundletool, which built and signed a \
             universal APK aapt2 reads back attribute for attribute",
            outcome.bundle.len()
        );
    }

    #[test]
    fn the_bundle_writer_refuses_what_it_cannot_write_faithfully() {
        let mut sink = Sink::new();
        let referenced = crate::xml::parse(
            concat!(
                "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" ",
                "package=\"com.tr.yt\">",
                "<uses-sdk android:minSdkVersion=\"30\" android:targetSdkVersion=\"36\" />",
                "<application android:label=\"@string/name\" android:allowBackup=\"false\" />",
                "</manifest>",
            ),
            "AndroidManifest.xml",
            &mut sink,
        )
        .unwrap();
        assert_eq!(
            crate::bundle::encode_manifest(&referenced)
                .expect_err("a name this build cannot resolve must be refused")
                .code,
            "EN011"
        );

        let unknown = crate::xml::parse(
            concat!(
                "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" ",
                "package=\"com.tr.yt\">",
                "<application android:notAnAttributeAndroidHas=\"1\" />",
                "</manifest>",
            ),
            "AndroidManifest.xml",
            &mut sink,
        )
        .unwrap();
        assert_eq!(
            crate::bundle::encode_manifest(&unknown)
                .expect_err("an attribute with no identifier must be refused")
                .code,
            "EN010"
        );

        let wrong_root = crate::xml::parse("<application />", "x.xml", &mut sink).unwrap();
        assert_eq!(
            crate::bundle::encode_manifest(&wrong_root)
                .unwrap_err()
                .code,
            "EN001"
        );

        let weak = crate::builder::from_manifest(concat!(
            "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" ",
            "package=\"com.tr.yt\" android:versionCode=\"1\" android:versionName=\"1.0.0\">",
            "<uses-sdk android:minSdkVersion=\"30\" android:targetSdkVersion=\"36\" />",
            "<application android:label=\"X\" android:allowBackup=\"false\" ",
            "android:debuggable=\"true\">",
            "<activity android:name=\"com.tr.yt.MainActivity\" android:exported=\"false\" />",
            "</application></manifest>",
        ))
        .unwrap();
        let written = crate::bundle::write(&weak)
            .expect("the security policy reports a bundle, it does not stop one");
        assert!(!written.bundle.is_empty());
    }

    #[test]
    fn protobuf_varints_are_written_the_way_the_wire_format_defines_them() {
        use crate::protobuf::{tag, varint};
        assert_eq!(varint(0), vec![0x00]);
        assert_eq!(varint(1), vec![0x01]);
        assert_eq!(varint(127), vec![0x7f]);
        assert_eq!(varint(128), vec![0x80, 0x01]);
        assert_eq!(varint(300), vec![0xac, 0x02]);
        assert_eq!(varint(16_843_291), vec![0x9b, 0x84, 0x84, 0x08]);
        assert_eq!(
            varint(u64::MAX),
            vec![0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x01]
        );

        assert_eq!(tag(1, 2), vec![0x0a]);
        assert_eq!(tag(3, 2), vec![0x1a]);
        assert_eq!(tag(5, 0), vec![0x28]);
        assert_eq!(tag(16, 2), vec![0x82, 0x01]);

        let mut message = crate::protobuf::Message::new();
        message.text(1, "testing");
        assert_eq!(
            message.as_bytes(),
            &[0x0a, 0x07, b't', b'e', b's', b't', b'i', b'n', b'g']
        );

        let mut outer = crate::protobuf::Message::new();
        outer.message(2, &message);
        assert_eq!(
            outer.as_bytes(),
            &[0x12, 0x09, 0x0a, 0x07, b't', b'e', b's', b't', b'i', b'n', b'g']
        );
    }

    #[test]
    fn dimensions_are_written_in_the_fixed_point_the_format_defines() {
        use crate::arsc::encode_dimension;
        use crate::arsc::encode_fraction;
        use crate::resources::Unit;

        assert_eq!(encode_dimension(1_000, Unit::Dp).unwrap(), 0x0000_0101);
        assert_eq!(encode_dimension(4_000, Unit::Dp).unwrap(), 0x0000_0401);
        assert_eq!(encode_dimension(12_000, Unit::Dp).unwrap(), 0x0000_0c01);
        assert_eq!(encode_dimension(16_000, Unit::Dp).unwrap(), 0x0000_1001);
        assert_eq!(encode_dimension(14_000, Unit::Sp).unwrap(), 0x0000_0e02);
        assert_eq!(encode_dimension(16_000, Unit::Sp).unwrap(), 0x0000_1002);
        assert_eq!(encode_dimension(0, Unit::Px).unwrap(), 0x0000_0000);

        assert_eq!(encode_dimension(1_500, Unit::Dp).unwrap(), 0x00c0_0021);
        assert_eq!(encode_dimension(-2_250, Unit::Dp).unwrap(), 0xfee0_0021);
        assert_eq!(encode_dimension(1_234_500, Unit::Sp).unwrap(), 0x0269_4012);

        assert_eq!(encode_dimension(100, Unit::Dp).unwrap(), 0x0ccc_cd31);
        assert_eq!(encode_fraction(500, false).unwrap(), 0x4000_0030);
        assert_eq!(encode_fraction(333, true).unwrap(), 0x2a9f_be31);
        assert_eq!(encode_fraction(1_000, false).unwrap(), 0x0000_0100);

        assert_eq!(
            encode_dimension(40_000_000_000, Unit::Dp)
                .expect_err("a dimension larger than the mantissa must be refused")
                .code,
            "EZ001"
        );
    }

    fn table_for_test() -> crate::resources::Compiled {
        let mut sink = Sink::new();
        let mut table = crate::resources::Table::for_package(0x7f);
        assert!(table.read_values(
            concat!(
                "<resources>",
                "<string name=\"app_name\">Omni Made</string>",
                "<string name=\"greeting\">Hello</string>",
                "<color name=\"accent\">#ff6cb6ff</color>",
                "<dimen name=\"gap\">12dp</dimen>",
                "<bool name=\"ready\">true</bool>",
                "<integer name=\"tries\">3</integer>",
                "</resources>",
            ),
            "values/values.xml",
            &mut sink,
        ));
        assert!(table.read_file(
            "mipmap",
            "ic_launcher.png",
            "res/mipmap/ic_launcher.png",
            &mut sink
        ));
        assert!(table.read_file(
            "mipmap-xxhdpi",
            "ic_launcher.png",
            "res/mipmap-xxhdpi/ic_launcher.png",
            &mut sink,
        ));
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        table.compile(&mut sink).expect("the table must compile")
    }

    #[test]
    fn the_resource_table_this_build_writes_is_the_one_aapt2_reads() {
        let compiled = table_for_test();
        let table = crate::arsc::write("com.tr.yt", &compiled).expect("the table must be written");

        assert_eq!(&table[..2], &crate::arsc::RES_TABLE.to_le_bytes());
        assert_eq!(
            u32::from_le_bytes([table[4], table[5], table[6], table[7]]) as usize,
            table.len(),
            "the table header must state the whole size"
        );

        let Some(aapt2) = find_build_tool("aapt2") else {
            assert!(
                std::env::var("OMNI_REQUIRE_AXML_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_AXML_CONFORMANCE is set but aapt2 is missing, so the resource \
                 table this build wrote was never read by anything but itself"
            );
            eprintln!("resource table: aapt2 is not available here");
            return;
        };

        let mut sink = Sink::new();
        let root = crate::xml::parse(
            concat!(
                "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" ",
                "package=\"com.tr.yt\" android:versionCode=\"1\" android:versionName=\"1.0.0\">",
                "<uses-sdk android:minSdkVersion=\"30\" android:targetSdkVersion=\"36\" />",
                "<application android:label=\"X\" android:allowBackup=\"false\" />",
                "</manifest>",
            ),
            "AndroidManifest.xml",
            &mut sink,
        )
        .unwrap();

        let mut builder = ArchiveBuilder::for_android();
        builder
            .add("AndroidManifest.xml", crate::axml::encode(&root).unwrap())
            .unwrap();
        builder.add("resources.arsc", table.clone()).unwrap();
        builder
            .add("res/mipmap/ic_launcher.png", b"not a real image".to_vec())
            .unwrap();
        builder
            .add("res/mipmap-xxhdpi/ic_launcher.png", b"nor is this".to_vec())
            .unwrap();
        let apk = builder.finish().unwrap();

        let directory = temp_directory("omni-arsc");
        let path = directory.join("table.apk");
        std::fs::write(&path, &apk).unwrap();

        let dumped = std::process::Command::new(&aapt2)
            .args(["dump", "resources", path.to_str().unwrap()])
            .output()
            .unwrap();
        let text = format!(
            "{}{}",
            String::from_utf8_lossy(&dumped.stdout),
            String::from_utf8_lossy(&dumped.stderr)
        );
        assert!(
            dumped.status.success(),
            "aapt2 refused the table this build wrote:\n{text}"
        );

        for expected in [
            "Package name=com.tr.yt id=7f",
            "type bool id=01",
            "type color id=02",
            "type dimen id=03",
            "type integer id=04",
            "type mipmap id=05",
            "type string id=06",
            "resource 0x7f010000 bool/ready",
            "resource 0x7f020000 color/accent",
            "resource 0x7f030000 dimen/gap",
            "resource 0x7f040000 integer/tries",
            "resource 0x7f050000 mipmap/ic_launcher",
            "resource 0x7f060000 string/app_name",
            "resource 0x7f060001 string/greeting",
            "Omni Made",
            "Hello",
            "res/mipmap/ic_launcher.png",
            "res/mipmap-xxhdpi/ic_launcher.png",
        ] {
            assert!(text.contains(expected), "missing {expected:?} in\n{text}");
        }

        let badging = std::process::Command::new(&aapt2)
            .args(["dump", "badging", path.to_str().unwrap()])
            .output()
            .unwrap();
        assert!(
            badging.status.success(),
            "{}",
            String::from_utf8_lossy(&badging.stderr)
        );

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "resource table: {} bytes, {} identifiers, aapt2 read every one of them back",
            table.len(),
            compiled.assignments().len()
        );
    }

    #[test]
    fn the_name_a_project_carries_is_translated_in_every_language_it_chose() {
        let _turn = crate::progress::one_at_a_time();
        let directory = temp_directory("omni-locales");
        let root = directory.join("Spoken");
        let text = root.to_str().unwrap().to_string();
        let spec = crate::scaffold::Spec {
            package: "com.my.app".to_string(),
            label: "Spoken".to_string(),
            locales: vec![
                crate::scaffold::BASE_LOCALE.to_string(),
                "tr".to_string(),
                "de".to_string(),
            ],
            ..crate::scaffold::Spec::default()
        };
        crate::scaffold::create(&text, &spec).unwrap();

        let translations = [("tr", "Konuşulan"), ("de", "Gesprochen")];
        for (locale, translated) in translations {
            crate::workspace::write_text(
                &text,
                &format!(
                    "{}/{}/{}",
                    crate::scaffold::RES_FOLDER,
                    crate::scaffold::values_folder(locale),
                    crate::scaffold::STRINGS_FILE
                ),
                &crate::scaffold::strings_file(translated),
            )
            .unwrap();
        }

        let project = crate::builder::from_project(&text).unwrap();
        assert_eq!(
            project.values.len(),
            3,
            "the base folder and one per translation are read back"
        );

        let key = crate::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let outcome = crate::builder::build(&project, &key, 1_787_000_000, &mut sink)
            .expect("a translated project must build");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let Some(aapt2) = find_build_tool("aapt2") else {
            assert!(
                std::env::var("OMNI_REQUIRE_AXML_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_AXML_CONFORMANCE is set but aapt2 is missing"
            );
            eprintln!("locales: aapt2 is not available here");
            std::fs::remove_dir_all(&directory).ok();
            return;
        };

        let package = directory.join("spoken.apk");
        std::fs::write(&package, &outcome.package).unwrap();
        let dumped = std::process::Command::new(&aapt2)
            .args(["dump", "resources", package.to_str().unwrap()])
            .output()
            .unwrap();
        let listing = String::from_utf8_lossy(&dumped.stdout).to_string();
        assert!(dumped.status.success(), "{listing}");

        assert!(
            listing.contains("string/app_name"),
            "the name is a string resource in the table aapt2 read\n{listing}"
        );
        assert!(
            listing.contains("\"Spoken\""),
            "the folder a device falls back to carries the untranslated name\n{listing}"
        );
        for (locale, translated) in translations {
            assert!(
                listing.contains(&format!("({locale})")),
                "aapt2 must report a {locale} configuration\n{listing}"
            );
            assert!(
                listing.contains(&format!("\"{translated}\"")),
                "aapt2 must report {translated:?}\n{listing}"
            );
        }

        eprintln!(
            "locales: aapt2 reports the name in {} languages from the table this build wrote",
            translations.len() + 1
        );
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_image_the_developer_chose_becomes_the_icon_aapt2_reports() {
        let _turn = crate::progress::one_at_a_time();
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 8);
            }
        }
        let Some(source) = files
            .into_iter()
            .find(|file| crate::image::read_png_file(file.to_str().unwrap_or_default()).is_ok())
        else {
            eprintln!("icon: no PNG file is available here");
            return;
        };

        let directory = temp_directory("omni-icon-package");
        let root = directory.join("Pictured");
        let text = root.to_str().unwrap().to_string();
        crate::scaffold::create(&text, &crate::scaffold::Spec::default()).unwrap();
        crate::scaffold::set_icon(&text, source.to_str().unwrap()).unwrap();

        let project = crate::builder::from_project(&text).unwrap();
        assert!(project.icon.is_some(), "the stored image must be read back");
        assert_eq!(
            project.launcher.len(),
            crate::image::launcher_files_expected().len(),
            "choosing the image wrote the launcher icons into the project's own folders"
        );

        let key = crate::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let outcome = crate::builder::build(&project, &key, 1_787_000_000, &mut sink)
            .expect("a project with an image must build");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let mut own = Sink::new();
        let archive = archive::read(&outcome.package, &mut own).expect("it must read back");
        for wanted in [
            "AndroidManifest.xml",
            crate::builder::TABLE_ENTRY,
            "classes.dex",
        ] {
            assert!(
                archive.entries().iter().any(|entry| entry.name == wanted),
                "the package must carry {wanted}"
            );
        }
        for (folder, edge) in crate::image::LAUNCHER_SIZES {
            for name in ["ic_launcher", "ic_launcher_round"] {
                let wanted = format!("res/{folder}/{name}.png");
                let entry = archive
                    .entry(&wanted)
                    .unwrap_or_else(|| panic!("the package must carry {wanted}"));
                let bytes = archive.content(&outcome.package, entry).unwrap();
                let header = crate::image::read_png(&bytes).unwrap();
                assert_eq!(header.width, *edge, "{wanted}");
                assert_eq!(header.height, *edge, "{wanted}");
            }
        }

        let Some(aapt2) = find_build_tool("aapt2") else {
            assert!(
                std::env::var("OMNI_REQUIRE_AXML_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_AXML_CONFORMANCE is set but aapt2 is missing"
            );
            eprintln!("icon: aapt2 is not available here");
            std::fs::remove_dir_all(&directory).ok();
            return;
        };

        let path = directory.join("pictured.apk");
        std::fs::write(&path, &outcome.package).unwrap();

        let badging = std::process::Command::new(&aapt2)
            .args(["dump", "badging", path.to_str().unwrap()])
            .output()
            .unwrap();
        let report = format!(
            "{}{}",
            String::from_utf8_lossy(&badging.stdout),
            String::from_utf8_lossy(&badging.stderr)
        );
        assert!(badging.status.success(), "{report}");
        for density in [160, 240, 320, 480, 640] {
            let wanted = format!(
                "application-icon-{density}:'res/{}/ic_launcher.xml'",
                crate::image::ADAPTIVE_FOLDER
            );
            assert!(
                report.contains(&wanted),
                "aapt2 must report {wanted}:\n{report}"
            );
        }
        assert!(
            report.contains(&format!(
                "application: label='My App' icon='res/{}/ic_launcher.xml'",
                crate::image::ADAPTIVE_FOLDER
            )),
            "aapt2 must name the adaptive icon as the application icon:\n{report}"
        );

        let tree = std::process::Command::new(&aapt2)
            .args([
                "dump",
                "xmltree",
                path.to_str().unwrap(),
                "--file",
                "AndroidManifest.xml",
            ])
            .output()
            .unwrap();
        let manifest = String::from_utf8_lossy(&tree.stdout).to_string();
        assert!(tree.status.success(), "{manifest}");
        assert!(
            manifest.contains("android:icon(0x01010002)=@0x7f010000"),
            "the manifest must point at the identifier the table assigned:\n{manifest}"
        );
        let round = manifest
            .split("android:roundIcon(0x0101052c)=@0x")
            .nth(1)
            .map(|rest| rest.split_whitespace().next().unwrap_or("").to_string())
            .expect("the round icon must be pointed at as well");
        assert!(
            round.starts_with("7f01") && round != "7f010000",
            "the round icon points at {round}, which is not a mipmap of its own"
        );

        let anydpi = format!("res/{}/ic_launcher.xml", crate::image::ADAPTIVE_FOLDER);
        assert!(
            archive.entries().iter().any(|entry| entry.name == anydpi),
            "the package must carry {anydpi}"
        );
        let drawn = std::process::Command::new(&aapt2)
            .args(["dump", "xmltree", path.to_str().unwrap(), "--file", &anydpi])
            .output()
            .unwrap();
        let layers = String::from_utf8_lossy(&drawn.stdout).to_string();
        assert!(drawn.status.success(), "{layers}");
        for element in ["adaptive-icon", "background", "foreground", "monochrome"] {
            assert!(
                layers.contains(&format!("E: {element} ")),
                "aapt2 does not report {element}:\n{layers}"
            );
        }
        for (folder, _) in crate::image::ADAPTIVE_SIZES {
            for name in [crate::image::FOREGROUND_NAME, crate::image::MONOCHROME_NAME] {
                let wanted = format!("res/{folder}/{name}.png");
                assert!(
                    archive.entries().iter().any(|entry| entry.name == wanted),
                    "the package must carry {wanted}"
                );
            }
        }

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "icon: one {} byte image became {} launcher files across {} densities -- square, \
             round, and an adaptive icon with its three layers -- and aapt2 reports them",
            project.icon.as_ref().map(|png| png.len()).unwrap_or(0),
            crate::image::launcher_files_expected().len(),
            crate::image::LAUNCHER_SIZES.len(),
        );
    }

    #[test]
    fn a_package_this_build_writes_is_compressed_where_compressing_is_allowed() {
        let _turn = crate::progress::one_at_a_time();
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 8);
            }
        }
        let picture = files
            .into_iter()
            .find(|file| crate::image::read_png_file(file.to_str().unwrap_or_default()).is_ok());

        let mut project = crate::builder::starter("com.tr.yt", "Packed");
        project.icon = picture.as_ref().map(|path| std::fs::read(path).unwrap());
        project.files = vec![
            (
                "lib/arm64-v8a/libomni.so".to_string(),
                b"\x7fELF".iter().copied().cycle().take(64_000).collect(),
            ),
            (
                "assets/notes.txt".to_string(),
                "the same sentence over and over. ".repeat(400).into_bytes(),
            ),
        ];

        let key = crate::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let outcome = crate::builder::build(&project, &key, 1_787_000_000, &mut sink).unwrap();
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let mut own = Sink::new();
        let archive = archive::read(&outcome.package, &mut own).expect("it must read back");

        let table = archive.entry(crate::builder::TABLE_ENTRY);
        if let Some(table) = table {
            assert_eq!(
                table.compression,
                archive::Compression::Stored,
                "Android maps the resource table in place, so it may never be compressed"
            );
            assert!(table.is_aligned_to(4));
        }

        let library = archive
            .entry("lib/arm64-v8a/libomni.so")
            .expect("the library must be there");
        assert_eq!(
            library.compression,
            archive::Compression::Stored,
            "a native library is loaded straight out of the package, so it stays stored"
        );
        assert!(library.is_aligned_to(crate::builder::PAGE_ALIGNMENT));

        let notes = archive
            .entry("assets/notes.txt")
            .expect("the asset must be there");
        assert_eq!(
            notes.compression,
            archive::Compression::Deflate,
            "a repetitive asset is exactly what compression is for"
        );
        assert!(
            notes.compressed_size * 4 < notes.uncompressed_size,
            "{} bytes out of {} is not compression",
            notes.compressed_size,
            notes.uncompressed_size
        );

        for entry in archive.entries() {
            let read = archive
                .content(&outcome.package, entry)
                .unwrap_or_else(|error| panic!("{}: {} {}", entry.name, error.code, error.message));
            assert_eq!(read.len() as u64, entry.uncompressed_size, "{}", entry.name);
        }

        let directory = temp_directory("omni-packed");
        let path = directory.join("packed.apk");
        std::fs::write(&path, &outcome.package).unwrap();

        let listed = std::process::Command::new("unzip")
            .args(["-p", path.to_str().unwrap(), "assets/notes.txt"])
            .output()
            .unwrap();
        assert!(listed.status.success());
        assert_eq!(
            listed.stdout,
            "the same sentence over and over. ".repeat(400).into_bytes(),
            "an independent reader must get back exactly what went in"
        );

        if let Some(zipalign) = find_build_tool("zipalign") {
            let checked = std::process::Command::new(&zipalign)
                .args(["-c", "-P", "16", "-v", "4", path.to_str().unwrap()])
                .output()
                .unwrap();
            assert!(
                checked.status.success(),
                "zipalign refused it:\n{}{}",
                String::from_utf8_lossy(&checked.stdout),
                String::from_utf8_lossy(&checked.stderr)
            );
        }

        let stored: u64 = archive
            .entries()
            .iter()
            .map(|entry| entry.uncompressed_size)
            .sum();
        let packed: u64 = archive
            .entries()
            .iter()
            .map(|entry| entry.compressed_size)
            .sum();
        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "archive: {} entries, {stored} bytes of content carried in {packed}, with the \
             resource table and the native library left stored and aligned",
            archive.entries().len()
        );
    }

    #[test]
    fn the_resource_table_sits_where_the_installer_needs_it() {
        let _turn = crate::progress::one_at_a_time();
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 8);
            }
        }
        let Some(source) = files
            .into_iter()
            .find(|file| crate::image::read_png_file(file.to_str().unwrap_or_default()).is_ok())
        else {
            eprintln!("alignment: no PNG file is available here");
            return;
        };

        let directory = temp_directory("omni-arsc-align");
        let root = directory.join("Aligned");
        let text = root.to_str().unwrap().to_string();
        crate::scaffold::create(&text, &crate::scaffold::Spec::default()).unwrap();
        crate::scaffold::set_icon(&text, source.to_str().unwrap()).unwrap();

        let project = crate::builder::from_project(&text).unwrap();
        let key = crate::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let outcome = crate::builder::build(&project, &key, 1_787_000_000, &mut sink).unwrap();

        let mut own = Sink::new();
        let archive = archive::read(&outcome.package, &mut own).unwrap();
        let table = archive
            .entry(crate::builder::TABLE_ENTRY)
            .expect("the table must be in the package");
        assert_eq!(
            table.compression,
            archive::Compression::Stored,
            "Android reads resources.arsc in place, so it may not be compressed"
        );
        assert!(
            table.is_aligned_to(4),
            "Android maps resources.arsc directly, so it must start on a four byte boundary"
        );

        let path = directory.join("aligned.apk");
        std::fs::write(&path, &outcome.package).unwrap();
        if let Some(zipalign) = find_build_tool("zipalign") {
            let checked = std::process::Command::new(&zipalign)
                .args(["-c", "-v", "4", path.to_str().unwrap()])
                .output()
                .unwrap();
            assert!(
                checked.status.success(),
                "zipalign refused it:\n{}{}",
                String::from_utf8_lossy(&checked.stdout),
                String::from_utf8_lossy(&checked.stderr)
            );
            eprintln!("alignment: zipalign agrees the package is aligned at four bytes");
        }

        std::fs::remove_dir_all(&directory).ok();
    }

