    #[test]
    fn the_bridge_makes_a_developer_key_lists_it_and_signs_a_project_with_it() {
        let directory = temp_directory("omni-ffi-keys");
        let keys = directory.join("Keys");
        let root = directory.join("Signed");
        crate::scaffold::create(root.to_str().unwrap(), &crate::scaffold::Spec::default()).unwrap();

        let keys_c = std::ffi::CString::new(keys.to_str().unwrap()).unwrap();
        let spec_c = std::ffi::CString::new(
            "alias=studio;commonName=Studio Name;organisation=Omni;country=TR;\
             validityDays=10950;bits=2048",
        )
        .unwrap();
        let password_c = std::ffi::CString::new("a password worth having").unwrap();

        let made = call_ffi(|| unsafe {
            crate::ffi::omni_create_key(keys_c.as_ptr(), spec_c.as_ptr(), password_c.as_ptr())
        });
        assert!(is_structurally_valid(&made), "{made}");
        assert!(made.contains("\"created\":true"), "{made}");
        assert!(made.contains("CN=Studio Name"), "{made}");

        let listed = call_ffi(|| unsafe { crate::ffi::omni_list_keys(keys_c.as_ptr()) });
        assert!(is_structurally_valid(&listed), "{listed}");
        assert!(listed.contains("\"alias\":\"studio\""), "{listed}");

        let path = crate::keystore::path_for(keys.to_str().unwrap(), "studio");
        let path_c = std::ffi::CString::new(path.clone()).unwrap();
        let opened = call_ffi(|| unsafe {
            crate::ffi::omni_check_key(path_c.as_ptr(), password_c.as_ptr())
        });
        assert!(opened.contains("\"opened\":true"), "{opened}");

        let wrong_c = std::ffi::CString::new("not the password").unwrap();
        let refused =
            call_ffi(|| unsafe { crate::ffi::omni_check_key(path_c.as_ptr(), wrong_c.as_ptr()) });
        assert!(refused.contains("\"opened\":false"), "{refused}");
        assert!(refused.contains("EY021"), "{refused}");
        assert!(
            !refused.contains("not the password"),
            "a bridge answer must never echo a password: {refused}"
        );

        let output = directory.join("signed.apk");
        let root_c = std::ffi::CString::new(root.to_str().unwrap()).unwrap();
        let out_c = std::ffi::CString::new(output.to_str().unwrap()).unwrap();
        let built = call_ffi(|| unsafe {
            crate::ffi::omni_build_project(
                root_c.as_ptr(),
                out_c.as_ptr(),
                path_c.as_ptr(),
                password_c.as_ptr(),
            )
        });
        assert!(is_structurally_valid(&built), "{built}");
        assert!(built.contains("\"built\":true"), "{built}");
        assert!(built.contains("\"developerKey\":true"), "{built}");
        assert!(built.contains("CN=Studio Name"), "{built}");
        assert!(
            !built.contains("a password worth having"),
            "a build answer must never echo a password: {built}"
        );

        let bytes = std::fs::read(&output).unwrap();
        let mut sink = Sink::new();
        let archive = archive::read(&bytes, &mut sink).unwrap();
        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );
        assert!(report.schemes.contains(&"v2"), "{:?}", report.schemes);
        assert!(report.schemes.contains(&"v3"), "{:?}", report.schemes);
        assert!(report.signers[0].certificates[0]
            .subject
            .contains("CN=Studio Name"));

        let removed = call_ffi(|| unsafe { crate::ffi::omni_delete_key(path_c.as_ptr()) });
        assert!(removed.contains("\"removed\":true"), "{removed}");
        assert!(crate::keystore::list(keys.to_str().unwrap()).is_empty());

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_picture_with_more_colours_than_a_palette_holds_is_cut_down_where_it_can_be() {
        let edge = 192u32;
        let mut pixels = Vec::with_capacity((edge * edge * 4) as usize);
        let mut seed = 0x2545_F491_4F6C_DD1Du64;
        let mut wobble = || {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            ((seed >> 33) % 5) as i16 - 2
        };
        for y in 0..edge {
            for x in 0..edge {
                let group = ((x / 24) + (y / 24) * 8) % 64;
                let shade = |base: u32, by: i16| (base as i16 + by).clamp(0, 255) as u8;
                pixels.extend_from_slice(&[
                    shade(30 + group % 8 * 28, wobble()),
                    shade(20 + group / 8 * 28, wobble()),
                    shade(200 - group % 5 * 40, wobble()),
                    255,
                ]);
            }
        }
        let raster = crate::image::Raster {
            width: edge,
            height: edge,
            pixels,
        };

        assert!(
            crate::image::palette_of(&raster).is_none(),
            "this picture is meant to hold more colours than a palette does"
        );

        let palette = crate::image::quantise(&raster, crate::image::LARGEST_PALETTE);
        assert!(palette.len() >= 2 && palette.len() <= crate::image::LARGEST_PALETTE);
        let error = crate::image::error_against(&raster, &palette);
        assert!(
            error <= crate::image::INVISIBLE_ERROR,
            "the cut moved the picture by {error}, past what an eye cannot find"
        );

        let exact = crate::image::encode(&raster).unwrap();
        let written = crate::image::encode_smallest(&raster).unwrap();
        assert_eq!(
            crate::image::decode(&exact).unwrap().pixels,
            raster.pixels,
            "the encoder that is not asked to squeeze stays exact"
        );
        assert!(
            written.len() * 2 < exact.len(),
            "the squeeze must be worth having: {} against {}",
            written.len(),
            exact.len()
        );

        let read = crate::image::decode(&written).unwrap();
        assert_eq!(read.width, raster.width);
        assert_eq!(read.height, raster.height);
        assert!(
            crate::image::error_against(&read, &palette) <= crate::image::INVISIBLE_ERROR,
            "what was written reads back as the picture that went in"
        );

        eprintln!(
            "quantise: thousands of colours became {}, {} bytes became {} ({}%), \
             mean squared error {error:.3}",
            palette.len(),
            exact.len(),
            written.len(),
            written.len() * 100 / exact.len(),
        );
    }

    #[test]
    fn a_picture_a_palette_would_spoil_keeps_every_colour_it_came_with() {
        let edge = 128u32;
        let mut pixels = Vec::with_capacity((edge * edge * 4) as usize);
        for y in 0..edge {
            for x in 0..edge {
                pixels.extend_from_slice(&[(x * 2) as u8, (y * 2) as u8, (x + y) as u8, 255]);
            }
        }
        let raster = crate::image::Raster {
            width: edge,
            height: edge,
            pixels,
        };

        let palette = crate::image::quantise(&raster, crate::image::LARGEST_PALETTE);
        let error = crate::image::error_against(&raster, &palette);
        assert!(
            error > crate::image::INVISIBLE_ERROR,
            "a sweep this wide cannot survive 256 colours, yet the error was {error}"
        );

        let written = crate::image::encode_smallest(&raster).unwrap();
        let read = crate::image::decode(&written).unwrap();
        assert_eq!(
            read.pixels, raster.pixels,
            "a picture the palette would spoil is written exactly as it came"
        );
        eprintln!("quantise: refused, the cut would have moved the picture by {error:.1}");
    }

    #[test]
    fn what_is_clear_in_a_picture_is_still_clear_after_it_is_squeezed() {
        let edge = 128u32;
        let middle = (edge as f64 - 1.0) / 2.0;
        let radius = middle;
        let mut pixels = Vec::with_capacity((edge * edge * 4) as usize);
        let mut seed = 0x9E37_79B9_7F4A_7C15u64;
        let mut wobble = || {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            ((seed >> 33) % 7) as i16 - 3
        };
        for y in 0..edge {
            for x in 0..edge {
                let across = f64::from(x) - middle;
                let down = f64::from(y) - middle;
                let shade = |base: u32, by: i16| (base as i16 + by).clamp(0, 255) as u8;
                if across * across + down * down <= radius * radius {
                    let group = ((x / 16) + (y / 16) * 8) % 64;
                    pixels.extend_from_slice(&[
                        shade(40 + group % 8 * 26, wobble()),
                        shade(30 + group / 8 * 26, wobble()),
                        shade(190 - group % 5 * 34, wobble()),
                        255,
                    ]);
                } else {
                    pixels.extend_from_slice(&[220, 40, 90, 0]);
                }
            }
        }
        let raster = crate::image::Raster {
            width: edge,
            height: edge,
            pixels,
        };
        assert!(
            crate::image::palette_of(&raster).is_none(),
            "this picture is meant to hold more colours than a palette does"
        );

        let written = crate::image::encode_smallest(&raster).unwrap();
        let exact = crate::image::encode(&raster).unwrap();
        assert!(
            written.len() < exact.len(),
            "a picture like this must squeeze: {} against {}",
            written.len(),
            exact.len()
        );

        let read = crate::image::decode(&written).unwrap();
        assert_eq!(read.width, edge);
        assert_eq!(read.height, edge);

        let mut clear = 0usize;
        for y in 0..edge {
            for x in 0..edge {
                let across = f64::from(x) - middle;
                let down = f64::from(y) - middle;
                let outside = across * across + down * down > radius * radius;
                let alpha = read.at(x, y)[3];
                if outside {
                    assert_eq!(
                        alpha, 0,
                        "the corner at {x},{y} came back {alpha}, not clear"
                    );
                    clear += 1;
                } else {
                    assert_eq!(
                        alpha, 255,
                        "the disc at {x},{y} came back {alpha}, not solid"
                    );
                }
            }
        }
        assert!(clear > 0, "the picture must have somewhere clear to test");
        eprintln!(
            "quantise: {clear} clear pixels stayed clear, {} bytes became {}",
            exact.len(),
            written.len()
        );
    }

    #[test]
    fn a_second_project_is_never_written_over_the_first() {
        let directory = temp_directory("omni-two-projects");
        let root = directory.join("Same Name");
        let text = root.to_str().unwrap().to_string();

        let first = crate::scaffold::Spec {
            package: "com.my.first".to_string(),
            label: "First".to_string(),
            ..crate::scaffold::Spec::default()
        };
        crate::scaffold::create(&text, &first).unwrap();
        let written = std::fs::read_to_string(root.join("AndroidManifest.xml")).unwrap();

        let second = crate::scaffold::Spec {
            package: "com.my.second".to_string(),
            label: "Second".to_string(),
            ..crate::scaffold::Spec::default()
        };
        let refused = crate::scaffold::create(&text, &second)
            .expect_err("a project may not be written into a folder that holds one");
        assert_eq!(refused.code, "EP028");
        assert_eq!(
            std::fs::read_to_string(root.join("AndroidManifest.xml")).unwrap(),
            written,
            "the first project's manifest is the one still there"
        );
        assert_eq!(
            crate::workspace::list_projects(directory.to_str().unwrap()).len(),
            1
        );

        let beside = directory.join("Same Name 2");
        crate::scaffold::create(beside.to_str().unwrap(), &second).unwrap();
        let listed = crate::workspace::list_projects(directory.to_str().unwrap());
        assert_eq!(listed.len(), 2, "{listed:?}");
        let packages: Vec<&str> = listed.iter().map(|one| one.package.as_str()).collect();
        assert!(packages.contains(&"com.my.first"), "{packages:?}");
        assert!(packages.contains(&"com.my.second"), "{packages:?}");

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_build_without_a_password_never_writes_over_a_sealed_key() {
        let _turn = SHARED_KEY_TURN
            .lock()
            .unwrap_or_else(|held| held.into_inner());
        let directory = temp_directory("omni-key-kept");
        let keys = directory.join("Keys");
        let path =
            crate::keystore::path_for(keys.to_str().unwrap(), crate::keystore::DEFAULT_ALIAS);
        crate::keystore::create(
            keys.to_str().unwrap(),
            &crate::keystore::Request::default(),
            crate::keystore::DEFAULT_PASSWORD,
            1_787_000_000,
        )
        .unwrap();
        let sealed = std::fs::read(&path).unwrap();

        let error = crate::builder::signing_key(&path)
            .expect_err("a sealed key is not a key this path may open");
        assert_eq!(error.code, "EB021");
        assert_eq!(
            std::fs::read(&path).unwrap(),
            sealed,
            "the key on disk is the key that was there before"
        );

        let root = directory.join("Kept");
        crate::scaffold::create(root.to_str().unwrap(), &crate::scaffold::Spec::default()).unwrap();
        let root_c = std::ffi::CString::new(root.to_str().unwrap()).unwrap();
        let package_c =
            std::ffi::CString::new(directory.join("kept.apk").to_str().unwrap()).unwrap();
        let bundle_c =
            std::ffi::CString::new(directory.join("kept.aab").to_str().unwrap()).unwrap();
        let path_c = std::ffi::CString::new(path.clone()).unwrap();

        let refused = call_ffi(|| unsafe {
            crate::ffi::omni_build_all(
                root_c.as_ptr(),
                package_c.as_ptr(),
                bundle_c.as_ptr(),
                path_c.as_ptr(),
                std::ptr::null(),
            )
        });
        assert!(is_structurally_valid(&refused), "{refused}");
        assert!(refused.contains("\"built\":false"), "{refused}");
        assert!(refused.contains("EB021"), "{refused}");
        assert_eq!(
            std::fs::read(&path).unwrap(),
            sealed,
            "a build asked for without the password leaves the key alone"
        );
        assert!(crate::keystore::describe(&path).is_ok());

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_shared_key_is_made_once_and_signs_the_package_and_the_bundle_together() {
        let _turn = SHARED_KEY_TURN
            .lock()
            .unwrap_or_else(|held| held.into_inner());
        let directory = temp_directory("omni-shared-key");
        let keys = directory.join("Keys");
        let root = directory.join("Together");
        crate::scaffold::create(root.to_str().unwrap(), &crate::scaffold::Spec::default()).unwrap();

        let keys_c = std::ffi::CString::new(keys.to_str().unwrap()).unwrap();
        let first = call_ffi(|| unsafe { crate::ffi::omni_default_key(keys_c.as_ptr()) });
        assert!(is_structurally_valid(&first), "{first}");
        assert!(first.contains("\"ready\":true"), "{first}");
        assert!(first.contains("\"created\":true"), "{first}");
        assert!(
            first.contains(&format!("CN={}", crate::keystore::DEFAULT_COMMON_NAME)),
            "{first}"
        );
        assert!(
            first.contains(&format!("O={}", crate::keystore::DEFAULT_ORGANISATION)),
            "{first}"
        );
        assert!(
            first.contains(&format!("C={}", crate::keystore::DEFAULT_COUNTRY)),
            "{first}"
        );
        assert!(
            first.contains(&format!("\"bits\":{}", crate::keystore::DEFAULT_BITS)),
            "{first}"
        );
        assert!(
            !first.contains(crate::keystore::DEFAULT_PASSWORD),
            "an answer must never echo a password: {first}"
        );

        let again = call_ffi(|| unsafe { crate::ffi::omni_default_key(keys_c.as_ptr()) });
        assert!(again.contains("\"ready\":true"), "{again}");
        assert!(
            again.contains("\"created\":false"),
            "the shared key is made once and reused after that: {again}"
        );
        assert_eq!(crate::keystore::list(keys.to_str().unwrap()).len(), 1);

        let path =
            crate::keystore::path_for(keys.to_str().unwrap(), crate::keystore::DEFAULT_ALIAS);
        assert!(crate::keystore::is_default(&path));

        let package = directory.join("together.apk");
        let bundle = directory.join("together.aab");
        let root_c = std::ffi::CString::new(root.to_str().unwrap()).unwrap();
        let package_c = std::ffi::CString::new(package.to_str().unwrap()).unwrap();
        let bundle_c = std::ffi::CString::new(bundle.to_str().unwrap()).unwrap();
        let path_c = std::ffi::CString::new(path.clone()).unwrap();
        let password_c = std::ffi::CString::new(crate::keystore::DEFAULT_PASSWORD).unwrap();

        let built = call_ffi(|| unsafe {
            crate::ffi::omni_build_all(
                root_c.as_ptr(),
                package_c.as_ptr(),
                bundle_c.as_ptr(),
                path_c.as_ptr(),
                password_c.as_ptr(),
            )
        });
        assert!(is_structurally_valid(&built), "{built}");
        assert!(built.contains("\"built\":true"), "{built}");
        assert!(built.contains("\"developerKey\":true"), "{built}");
        assert!(
            built.contains(&format!("\"locales\":{}", crate::scaffold::LOCALES.len())),
            "one action carries every language folder the project holds: {built}"
        );
        assert!(
            !built.contains(crate::keystore::DEFAULT_PASSWORD),
            "a build answer must never echo a password: {built}"
        );

        let bytes = std::fs::read(&package).unwrap();
        let mut sink = Sink::new();
        let read = archive::read(&bytes, &mut sink).unwrap();
        let report = signing::examine(
            &bytes,
            read.central_directory_offset(),
            read.end_record_offset(),
            &mut sink,
        );
        assert!(report.schemes.contains(&"v2"), "{:?}", report.schemes);
        assert!(report.signers[0].certificates[0]
            .subject
            .contains(&format!("CN={}", crate::keystore::DEFAULT_COMMON_NAME)));

        let bundled = std::fs::read(&bundle).unwrap();
        let read = archive::read(&bundled, &mut Sink::new()).unwrap();
        assert!(
            read.entry(crate::bundle::MANIFEST_ENTRY).is_some(),
            "the bundle the same action wrote holds its manifest"
        );

        let listed = crate::workspace::list_built(directory.to_str().unwrap());
        assert_eq!(listed.len(), 2, "{listed:?}");
        assert!(listed.iter().any(|made| made.bundle));
        assert!(listed.iter().any(|made| !made.bundle));

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn what_was_built_is_found_in_the_dated_folders_it_was_written_to() {
        let directory = temp_directory("omni-outputs");
        let outputs = directory.join(crate::workspace::OUTPUT_FOLDER);
        let first = outputs.join("2026-09-19_10-00-00");
        let second = outputs.join("2026-09-19_11-30-00");
        std::fs::create_dir_all(&first).unwrap();
        std::fs::create_dir_all(&second).unwrap();
        std::fs::write(first.join("Held.apk"), b"one").unwrap();
        std::fs::write(first.join("Held.aab"), b"two").unwrap();
        std::fs::write(second.join("Held.apk"), b"three").unwrap();
        std::fs::write(second.join("Held.apk.idsig"), b"beside").unwrap();
        std::fs::write(outputs.join("notes.txt"), b"not a package").unwrap();

        let listed = crate::workspace::list_built(outputs.to_str().unwrap());
        assert_eq!(listed.len(), 3, "{listed:?}");
        assert_eq!(
            listed.iter().filter(|made| made.bundle).count(),
            1,
            "{listed:?}"
        );
        assert!(
            listed
                .iter()
                .all(|made| made.folder.starts_with("2026-09-19_")),
            "each one says which dated folder it came out of: {listed:?}"
        );
        assert!(
            listed
                .iter()
                .any(|made| made.folder == "2026-09-19_11-30-00"),
            "{listed:?}"
        );
        assert!(
            listed.iter().all(|made| !made.name.ends_with(".idsig")),
            "the side signature is not a package: {listed:?}"
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_package_checks_itself_and_says_what_it_found() {
        let directory = temp_directory("omni-integrity");
        let root = directory.join("Checked");
        crate::scaffold::create(root.to_str().unwrap(), &crate::scaffold::Spec::default()).unwrap();

        let output = directory.join("checked.apk");
        let key = directory.join("signing.pk8");
        let root_c = std::ffi::CString::new(root.to_str().unwrap()).unwrap();
        let out_c = std::ffi::CString::new(output.to_str().unwrap()).unwrap();
        let key_c = std::ffi::CString::new(key.to_str().unwrap()).unwrap();
        call_ffi(|| unsafe {
            crate::ffi::omni_build_project(
                root_c.as_ptr(),
                out_c.as_ptr(),
                key_c.as_ptr(),
                std::ptr::null(),
            )
        });

        let bytes = std::fs::read(&output).unwrap();
        let mut sink = Sink::new();
        let archive = archive::read(&bytes, &mut sink).unwrap();
        let signing_report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );
        let fingerprint = signing_report.signers[0].certificates[0]
            .fingerprint
            .to_hex();

        let path_c = std::ffi::CString::new(output.to_str().unwrap()).unwrap();
        let good = std::ffi::CString::new(fingerprint.clone()).unwrap();
        let report =
            call_ffi(|| unsafe { crate::ffi::omni_verify_self(path_c.as_ptr(), good.as_ptr()) });
        assert!(report.contains("\"standing\":\"TRUSTED\""), "{report}");
        assert!(
            report.contains("cannot detect an attacker who patched the check out"),
            "{report}"
        );

        let other = std::ffi::CString::new("0".repeat(64)).unwrap();
        let report =
            call_ffi(|| unsafe { crate::ffi::omni_verify_self(path_c.as_ptr(), other.as_ptr()) });
        assert!(report.contains("\"standing\":\"TAMPERED\""), "{report}");
        assert!(report.contains("signed by a different key"), "{report}");

        let mut damaged = bytes.clone();
        let at = damaged.len() / 3;
        damaged[at] ^= 0xff;
        let damaged_path = directory.join("damaged.apk");
        std::fs::write(&damaged_path, &damaged).unwrap();
        let damaged_c = std::ffi::CString::new(damaged_path.to_str().unwrap()).unwrap();
        let report =
            call_ffi(|| unsafe { crate::ffi::omni_verify_self(damaged_c.as_ptr(), good.as_ptr()) });
        assert!(report.contains("\"standing\":\"TAMPERED\""), "{report}");

        std::fs::remove_dir_all(&directory).ok();
        eprintln!("integrity: a signed package reports TRUSTED, a re-signed or edited one reports TAMPERED");
    }

    fn bytes_of(hex: &str) -> Vec<u8> {
        (0..hex.len())
            .step_by(2)
            .map(|at| u8::from_str_radix(&hex[at..at + 2], 16).unwrap())
            .collect()
    }

    fn hex_string(bytes: &[u8]) -> String {
        bytes.iter().map(|byte| format!("{byte:02x}")).collect()
    }

    struct Pretend {
        outputs: Vec<(String, crate::compiler::Kind, Vec<u8>)>,

        offers: Option<Vec<(String, crate::compiler::Kind, Vec<u8>)>>,
        stop_after: Option<usize>,
        stopper: std::sync::Mutex<Option<crate::compiler::Stopper>>,
    }

    static PRETEND_CONTRACT: crate::plugin::Contract = crate::plugin::Contract {
        id: "omni.plugin.pretend",
        display_name: "Pretend",
        version: crate::plugin::Version::new(0, 1, 0),
        produces_artifacts: true,
        summary: "A compiler that exists so the contract can be tested.",
        inputs: &["pretend.source"],
        outputs: &["jvm.class"],
        required_capabilities: &[crate::caps::Capability::TempStorage],
        forbidden_capabilities: &[crate::caps::Capability::Network],
        non_responsibilities: &["Compiling anything."],
    };

    impl crate::compiler::Compiler for Pretend {
        fn contract(&self) -> &'static crate::plugin::Contract {
            &PRETEND_CONTRACT
        }

        fn probe(&self) -> crate::compiler::Probe {
            crate::compiler::Probe::usable(
                crate::compiler::Identity::new("pretend", "pretend", "1.0.0", "any"),
                crate::compiler::Reproducibility::Always,
            )
        }

        fn plan(
            &self,
            request: &crate::compiler::Request,
        ) -> Result<crate::compiler::Plan, crate::diag::Diagnostic> {
            let identity = self.probe().identity.unwrap();
            Ok(crate::compiler::Plan {
                key: crate::compiler::Plan::key_for(&identity, request),
                identity,
                expected: self
                    .outputs
                    .iter()
                    .map(|(name, kind, _)| crate::compiler::Expected {
                        name: name.clone(),
                        kind: *kind,
                    })
                    .collect(),
                reproducibility: crate::compiler::Reproducibility::Always,
            })
        }

        fn compile(
            &self,
            plan: &crate::compiler::Plan,
            _request: &crate::compiler::Request,
            mut session: crate::compiler::Session<'_>,
        ) -> Result<crate::compiler::Compiled, crate::diag::Diagnostic> {
            let offering = self.offers.as_ref().unwrap_or(&self.outputs);
            for (index, (name, kind, bytes)) in offering.iter().enumerate() {
                if self.stop_after == Some(index) {
                    let stopper = self.stopper.lock().unwrap().clone();
                    if let Some(stopper) = stopper {
                        stopper.stop();
                    }
                }
                session.offer(name.clone(), *kind, bytes.clone())?;
            }
            session.commit(plan)
        }
    }

    fn pretend(outputs: Vec<(&str, crate::compiler::Kind, &[u8])>) -> Pretend {
        Pretend {
            outputs: outputs
                .into_iter()
                .map(|(name, kind, bytes)| (name.to_string(), kind, bytes.to_vec()))
                .collect(),
            offers: None,
            stop_after: None,
            stopper: std::sync::Mutex::new(None),
        }
    }

    #[test]
    fn nothing_a_compiler_made_is_published_unless_all_of_it_was() {
        use crate::compiler::{Budget, Compiler, Kind, Request, Session};

        let directory = temp_directory("omni-compiler-contract");
        let store = crate::store::Store::at(directory.to_str().unwrap());
        let request = Request::new(crate::compiler::Abi::Arm64V8a, 28)
            .with_source(crate::compiler::Source::of("A.java", b"class A {}"));

        let session_of = |budget: Budget| {
            let policy: &'static mut crate::caps::Policy =
                Box::leak(Box::new(crate::caps::Policy::new("test")));
            let sink: &'static mut crate::diag::Sink =
                Box::leak(Box::new(crate::diag::Sink::new()));
            Session::new("omni.plugin.pretend", &store, policy, sink, budget)
        };

        let good = pretend(vec![
            ("A.class", Kind::JvmClass, b"one"),
            ("B.class", Kind::JvmClass, b"two"),
        ]);
        let plan = good.plan(&request).unwrap();
        let compiled = good
            .compile(&plan, &request, session_of(Budget::default()))
            .expect("a compilation that finishes must publish");
        assert_eq!(compiled.produced.len(), 2);
        assert_eq!(compiled.key, plan.key);
        for one in &compiled.produced {
            assert!(store.has(one.digest), "{} must be in the store", one.name);
        }
        let held_after_success = store.list().len();
        assert_eq!(held_after_success, 2);

        let mut short = pretend(vec![
            ("A.class", Kind::JvmClass, b"one"),
            ("B.class", Kind::JvmClass, b"two"),
        ]);
        short.offers = Some(vec![(
            "A.class".to_string(),
            Kind::JvmClass,
            b"one".to_vec(),
        )]);
        let plan = short.plan(&request).unwrap();
        let refused = short
            .compile(&plan, &request, session_of(Budget::default()))
            .expect_err("a compilation that did not keep its plan must publish nothing");
        assert_eq!(refused.code, "EX005");
        assert_eq!(
            store.list().len(),
            held_after_success,
            "nothing new may have reached the store"
        );

        let mut extra = pretend(vec![("A.class", Kind::JvmClass, b"one")]);
        extra.offers = Some(vec![(
            "Surprise.class".to_string(),
            Kind::JvmClass,
            b"one".to_vec(),
        )]);
        let plan = extra.plan(&request).unwrap();
        assert_eq!(
            extra
                .compile(&plan, &request, session_of(Budget::default()))
                .expect_err("an unplanned output must be refused")
                .code,
            "EX006"
        );

        let mut wrong = pretend(vec![("A.class", Kind::JvmClass, b"one")]);
        wrong.offers = Some(vec![("A.class".to_string(), Kind::Dex, b"one".to_vec())]);
        let plan = wrong.plan(&request).unwrap();
        assert_eq!(
            wrong
                .compile(&plan, &request, session_of(Budget::default()))
                .expect_err("the wrong kind must be refused")
                .code,
            "EX007"
        );

        let mut cancelled = pretend(vec![
            ("A.class", Kind::JvmClass, b"one"),
            ("B.class", Kind::JvmClass, b"two"),
        ]);
        cancelled.stop_after = Some(1);
        let plan = cancelled.plan(&request).unwrap();
        let budget = Budget::default();
        *cancelled.stopper.lock().unwrap() = Some(budget.stopper());
        let stopped = cancelled
            .compile(&plan, &request, session_of(budget))
            .expect_err("a compilation that was stopped must publish nothing");
        assert_eq!(stopped.code, "EX001");
        assert_eq!(store.list().len(), held_after_success);

        let big = pretend(vec![("A.class", Kind::JvmClass, b"more than four bytes")]);
        let plan = big.plan(&request).unwrap();
        assert_eq!(
            big.compile(&plan, &request, session_of(Budget::of(300, 4)))
                .expect_err("past its budget must be refused")
                .code,
            "EX004"
        );
        assert_eq!(store.list().len(), held_after_success);

        let mut twice = pretend(vec![
            ("A.class", Kind::JvmClass, b"one"),
            ("A.class", Kind::JvmClass, b"two"),
        ]);
        twice.offers = Some(vec![
            ("A.class".to_string(), Kind::JvmClass, b"one".to_vec()),
            ("A.class".to_string(), Kind::JvmClass, b"two".to_vec()),
        ]);
        let plan = twice.plan(&request).unwrap();
        assert_eq!(
            twice
                .compile(&plan, &request, session_of(Budget::default()))
                .expect_err("one name twice must be refused")
                .code,
            "EX003"
        );

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "contract: a compilation publishes all of what it planned or none of it, \
             and every published byte is read back and checked"
        );
    }

    #[test]
    fn the_same_everything_plans_to_the_same_key_and_anything_else_does_not() {
        use crate::compiler::{Abi, Identity, Plan, Request, Source};

        let identity = Identity::new("kotlin", "omni.kotlin", "2.4.10", "aarch64-linux-android");
        let base = Request::new(Abi::Arm64V8a, 30)
            .with_source(Source::of("A.kt", b"fun main() {}"))
            .with_source(Source::of("B.kt", b"fun other() {}"));

        assert_eq!(
            Plan::key_for(&identity, &base),
            Plan::key_for(&identity, &base)
        );

        let reordered = Request::new(Abi::Arm64V8a, 30)
            .with_source(Source::of("B.kt", b"fun other() {}"))
            .with_source(Source::of("A.kt", b"fun main() {}"));
        assert_eq!(
            Plan::key_for(&identity, &base),
            Plan::key_for(&identity, &reordered),
            "the order sources were handed over in must not decide anything"
        );

        let mut seen = std::collections::BTreeSet::new();
        seen.insert(Plan::key_for(&identity, &base).to_hex());

        let encoded = base.canonical().encode();
        assert!(
            encoded
                .windows(Abi::Arm64V8a.as_str().len())
                .any(|window| window == Abi::Arm64V8a.as_str().as_bytes()),
            "the machine has to be part of what the key is taken over"
        );

        let mut changed = base.clone();
        changed.api_level = 36;
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "api"
        );

        let mut changed = base.clone();
        changed.optimise = !changed.optimise;
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "optimise"
        );

        let mut changed = base.clone();
        changed.debug_info = !changed.debug_info;
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "debug info"
        );

        let mut changed = base.clone();
        changed.dependencies.push(crate::hash::sha256(b"a library"));
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "dependencies"
        );

        let mut changed = base.clone();
        changed
            .options
            .push(("jvmTarget".to_string(), "25".to_string()));
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "options"
        );

        let changed = Request::new(Abi::Arm64V8a, 28)
            .with_source(Source::of("A.kt", b"fun main() { }"))
            .with_source(Source::of("B.kt", b"fun other() {}"));
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "source bytes"
        );

        let changed = Request::new(Abi::Arm64V8a, 28)
            .with_source(Source::of("Renamed.kt", b"fun main() {}"))
            .with_source(Source::of("B.kt", b"fun other() {}"));
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "source name"
        );

        for moved in [
            Identity::new("kotlin", "omni.kotlin", "2.4.11", "aarch64-linux-android"),
            Identity::new("kotlin", "other.kotlin", "2.4.10", "aarch64-linux-android"),
            Identity::new("java", "omni.kotlin", "2.4.10", "aarch64-linux-android"),
            Identity::new("kotlin", "omni.kotlin", "2.4.10", "aarch64-linux-android30"),
            identity.clone().with("stdlib", "2.4.10"),
        ] {
            assert!(
                seen.insert(Plan::key_for(&moved, &base).to_hex()),
                "{moved:?} planned to a key something else already had"
            );
        }

        eprintln!(
            "contract: {} distinct compilations, no two sharing a key",
            seen.len()
        );
    }

    #[test]
    fn what_a_build_made_is_kept_checked_and_found_again_after_a_restart() {
        let directory = temp_directory("omni-store");
        let root = directory.join("Objects");
        let root_text = root.to_str().unwrap().to_string();
        let store = crate::store::Store::at(&root_text);

        let one = store.put(b"what the compiler wrote").unwrap();
        let same = store.put(b"what the compiler wrote").unwrap();
        assert_eq!(one, same, "the same bytes must be the same object");
        assert_eq!(store.list().len(), 1, "and must not be kept twice");
        assert_eq!(store.get(one).unwrap(), b"what the compiler wrote");

        let other = store.put(b"and what it wrote next").unwrap();
        assert_ne!(one, other);
        assert!(store.has(other));
        assert_eq!(store.list().len(), 2);

        let staged = std::fs::read_dir(format!("{root_text}/{}", crate::store::STAGING))
            .map(|entries| entries.count())
            .unwrap_or(0);
        assert_eq!(staged, 0, "a finished put leaves nothing staged");

        let hex = one.to_hex();
        let path = format!("{root_text}/{}/{}", &hex[..2], &hex[2..]);
        std::fs::write(&path, b"not what the compiler wrote at all").unwrap();
        let refused = store
            .get(one)
            .expect_err("an object that does not match its name must be refused");
        assert_eq!(refused.code, "ES010");
        assert!(
            !store.has(one),
            "and it must be gone, so the next build makes it again"
        );

        let one = store.put(b"what the compiler wrote").unwrap();

        let budget = 4u64;
        {
            let held = store.lease(one);
            assert_eq!(held.digest(), one);
            assert!(store.is_leased(one));
            let swept = store.sweep(budget, &std::collections::BTreeSet::new());
            assert!(store.has(one), "a leased object must survive a sweep");
            assert!(swept.held_back >= 1);
        }
        assert!(!store.is_leased(one), "and the hold ends with the lease");

        let mut keep = std::collections::BTreeSet::new();
        keep.insert(one);
        store.sweep(budget, &keep);
        assert!(store.has(one), "an object asked for must survive a sweep");

        let swept = store.sweep(budget, &std::collections::BTreeSet::new());
        assert!(swept.removed >= 1, "{swept:?}");
        assert!(store.total_bytes() <= budget, "{}", store.total_bytes());

        let before = store.list().len();
        let quiet = store.sweep(u64::MAX, &std::collections::BTreeSet::new());
        assert_eq!(quiet.removed, 0);
        assert_eq!(store.list().len(), before);

        let index_path = directory.join("Index").to_str().unwrap().to_string();
        let made = store.put(b"the package this key stands for").unwrap();
        let source = crate::hash::sha256(b"source");
        let dependencies = crate::hash::sha256(b"deps");
        let key = cache_inputs(&source, &dependencies).key();

        let mut index = crate::cache::Index::new();
        index.record(key, made, 31, 1_787_000_000);
        index.write(&index_path).expect("the index must write");
        assert!(
            !std::path::Path::new(&format!("{index_path}.writing")).exists(),
            "the file written beside it should have been moved over it"
        );

        let reopened = crate::cache::Index::read(&index_path);
        assert_eq!(
            reopened.len(),
            1,
            "the index must survive being written down"
        );
        let found = reopened
            .content_for(key)
            .expect("and must still say what the key stands for");
        assert_eq!(found, made);
        assert_eq!(
            store.get(found).unwrap(),
            b"the package this key stands for",
            "which is the whole point: the bytes come back"
        );

        store.remove(made).unwrap();
        let mut stale = crate::cache::Index::read(&index_path);
        assert_eq!(stale.len(), 1);
        assert_eq!(stale.reconcile(&store), 1, "the dangling entry must go");
        assert_eq!(stale.content_for(key), None);

        std::fs::write(&index_path, b"this is not an index").unwrap();
        assert!(crate::cache::Index::read(&index_path).is_empty());
        std::fs::write(&index_path, []).unwrap();
        assert!(crate::cache::Index::read(&index_path).is_empty());
        assert!(crate::cache::Index::read("nowhere at all").is_empty());

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "store: content-addressed, moved into place, checked on the way out, \
             swept by lease and budget, and found again after a restart"
        );
    }

    #[test]
    fn two_different_projects_never_come_to_one_digest() {
        use crate::canonical::Record;

        let mut one = crate::project::Project::defaults("App", "com.my.app");
        one.features = vec![("a=b".to_string(), true)];
        let mut other = crate::project::Project::defaults("App", "com.my.app");
        other.features = vec![("a".to_string(), true), ("b".to_string(), true)];
        assert_ne!(
            one.digest(),
            other.digest(),
            "a feature called `a=b` and the features `a` and `b` must not share a digest"
        );

        let mut forwards = crate::project::Project::defaults("App", "com.my.app");
        forwards.features = vec![("alpha".to_string(), true), ("beta".to_string(), false)];
        let mut backwards = crate::project::Project::defaults("App", "com.my.app");
        backwards.features = vec![("beta".to_string(), false), ("alpha".to_string(), true)];
        assert_eq!(
            forwards.digest(),
            backwards.digest(),
            "the same features in another order are the same project"
        );

        let renamed = crate::project::Project::defaults("Something Else", "com.my.app");
        assert_eq!(
            crate::project::Project::defaults("App", "com.my.app").digest(),
            renamed.digest(),
            "renaming a project must not throw its cache away"
        );

        let mut with_edition = crate::project::Project::defaults("App", "com.my.app");
        with_edition.edition = Some("2021".to_string());
        let mut other_edition = crate::project::Project::defaults("App", "com.my.app");
        other_edition.edition = Some("2024".to_string());
        assert_ne!(with_edition.digest(), other_edition.digest());
        assert_ne!(
            with_edition.digest(),
            crate::project::Project::defaults("App", "com.my.app").digest(),
            "an edition set at all is not the same as none"
        );

        let base = crate::project::Project::defaults("App", "com.my.app");
        let mut seen = std::collections::BTreeSet::new();
        seen.insert(base.digest().to_hex());
        for change in 0..9usize {
            let mut moved = base.clone();
            match change {
                0 => moved.lto = !moved.lto,
                1 => moved.incremental = !moved.incremental,
                2 => moved.parallel = !moved.parallel,
                3 => moved.deterministic = !moved.deterministic,
                4 => moved.provenance = !moved.provenance,
                5 => moved.verification = !moved.verification,
                6 => moved.min_sdk += 1,
                7 => moved.target_sdk += 1,
                _ => moved.compile_sdk += 1,
            }
            assert!(
                seen.insert(moved.digest().to_hex()),
                "change {change} did not reach the digest"
            );
        }

        let mut record = Record::new();
        record
            .text("name", "value")
            .text("nam", "evalue")
            .bytes("empty", b"")
            .number("count", 7)
            .flag("on", true);
        let written = record.encode();
        let read = crate::canonical::decode(&written).expect("what was written must read back");
        assert_eq!(read.len(), 5);
        assert_eq!(
            crate::canonical::decode(&written[..written.len() - 1]),
            None,
            "a truncated encoding must not read as a shorter one"
        );

        let mut confusable = Record::new();
        confusable.text("name", "value");
        let mut also = Record::new();
        also.text("nam", "evalue");
        assert_ne!(confusable.encode(), also.encode());

        eprintln!("canonical: features, editions and every switch reach the digest, none collide");
    }

    #[test]
    fn a_signature_is_blinded_and_still_comes_out_the_same_bytes_every_time() {
        let key = crate::rsa::generate(2048).expect("a key must be made");
        let digest = crate::hash::sha256(b"the same thing, signed again and again");

        let first =
            crate::rsa::sign_digest(&key, crate::rsa::DigestAlgorithm::Sha256, digest.as_bytes())
                .expect("the first signature");
        for round in 0..6 {
            let again = crate::rsa::sign_digest(
                &key,
                crate::rsa::DigestAlgorithm::Sha256,
                digest.as_bytes(),
            )
            .expect("and every one after");
            assert_eq!(
                first, again,
                "round {round} produced different bytes, so the blinding leaked into the answer"
            );
        }

        crate::rsa::verify(
            key.modulus(),
            key.public_exponent(),
            crate::rsa::DigestAlgorithm::Sha256,
            digest.as_bytes(),
            &first,
        )
        .expect("a blinded signature must verify like any other");

        let plain = key.without_crt();
        let without_crt = crate::rsa::sign_digest(
            &plain,
            crate::rsa::DigestAlgorithm::Sha256,
            digest.as_bytes(),
        )
        .expect("the whole exponent must sign too");
        assert_eq!(
            first, without_crt,
            "the two routes through the exponentiation must agree"
        );

        let blind_less = key.without_public_exponent();
        assert_eq!(
            crate::rsa::sign_digest(
                &blind_less,
                crate::rsa::DigestAlgorithm::Sha256,
                digest.as_bytes()
            )
            .expect_err("signing without anything to blind with must be refused")
            .code,
            "ER024"
        );

        eprintln!("rsa: seven signatures over one digest, blinded afresh each time, all identical");
    }

    fn a_small_tree(at: &std::path::Path) {
        std::fs::create_dir_all(at.join("Held/Inner")).expect("the tree is made");
        std::fs::write(at.join("Held/first.txt"), b"one line and then another\n").unwrap();
        std::fs::write(
            at.join("Held/Inner/second.txt"),
            "a line that repeats. ".repeat(80).as_bytes(),
        )
        .unwrap();
        std::fs::write(at.join("Held/Inner/empty.bin"), b"").unwrap();
    }

    fn tool_runs(named: &str, args: &[&str]) -> Option<(bool, String)> {
        let held = std::process::Command::new(named).args(args).output().ok()?;
        let mut said = String::from_utf8_lossy(&held.stdout).to_string();
        said.push_str(&String::from_utf8_lossy(&held.stderr));
        Some((held.status.success(), said))
    }

    #[test]
    fn a_zip_this_writes_is_one_unzip_reads_back() {
        let directory = temp_directory("omni-pack-zip");
        a_small_tree(&directory);
        let into = directory.join("Held.zip");

        let counted = crate::packer::pack(
            directory.to_str().unwrap(),
            &["Held".to_string()],
            into.to_str().unwrap(),
            crate::packer::ZIP,
            "",
        )
        .expect("the tree packs");
        assert_eq!(counted.files, 3);
        assert_eq!(counted.folders, 2);
        assert!(!counted.sealed);

        let Some((passed, said)) = tool_runs("unzip", &["-t", into.to_str().unwrap()]) else {
            eprintln!("pack conformance: unzip is not available here");
            std::fs::remove_dir_all(&directory).ok();
            return;
        };
        assert!(passed, "unzip refused what this wrote:\n{said}");

        let out = directory.join("Out");
        std::fs::create_dir_all(&out).unwrap();
        let (passed, said) = tool_runs(
            "unzip",
            &["-q", into.to_str().unwrap(), "-d", out.to_str().unwrap()],
        )
        .expect("unzip runs");
        assert!(passed, "unzip could not open it:\n{said}");

        for name in [
            "Held/first.txt",
            "Held/Inner/second.txt",
            "Held/Inner/empty.bin",
        ] {
            assert_eq!(
                std::fs::read(out.join(name)).unwrap_or_else(|_| panic!("{name} is there")),
                std::fs::read(directory.join(name)).unwrap(),
                "{name} came back changed"
            );
        }

        eprintln!("pack conformance: unzip reads back three files and two folders byte for byte");
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_tar_this_writes_is_one_tar_reads_back() {
        let directory = temp_directory("omni-pack-tar");
        a_small_tree(&directory);
        let into = directory.join("Held.tar");

        let counted = crate::packer::pack(
            directory.to_str().unwrap(),
            &["Held".to_string()],
            into.to_str().unwrap(),
            crate::packer::TAR,
            "",
        )
        .expect("the tree packs");
        assert_eq!(counted.files, 3);
        assert!(counted.written.is_multiple_of(512), "a tar is whole blocks");

        let out = directory.join("Out");
        std::fs::create_dir_all(&out).unwrap();
        let Some((passed, said)) = tool_runs(
            "tar",
            &["-xf", into.to_str().unwrap(), "-C", out.to_str().unwrap()],
        ) else {
            eprintln!("pack conformance: tar is not available here");
            std::fs::remove_dir_all(&directory).ok();
            return;
        };
        assert!(passed, "tar refused what this wrote:\n{said}");

        for name in [
            "Held/first.txt",
            "Held/Inner/second.txt",
            "Held/Inner/empty.bin",
        ] {
            assert_eq!(
                std::fs::read(out.join(name)).unwrap_or_else(|_| panic!("{name} is there")),
                std::fs::read(directory.join(name)).unwrap(),
                "{name} came back changed"
            );
        }

        assert_eq!(
            crate::packer::pack(
                directory.to_str().unwrap(),
                &["Held".to_string()],
                into.to_str().unwrap(),
                crate::packer::TAR,
                "secret",
            )
            .expect_err("a locked tar is refused")
            .code,
            "EZ002"
        );

        eprintln!("pack conformance: tar reads back three files byte for byte");
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_locked_zip_opens_with_its_password_and_with_nothing_else() {
        let directory = temp_directory("omni-pack-locked");
        a_small_tree(&directory);
        let into = directory.join("Held.zip");

        let counted = crate::packer::pack(
            directory.to_str().unwrap(),
            &["Held".to_string()],
            into.to_str().unwrap(),
            crate::packer::ZIP,
            "a long enough password",
        )
        .expect("the tree packs");
        assert!(counted.sealed);

        let bytes = std::fs::read(&into).expect("the archive is on disk");
        let mut sink = crate::diag::Sink::new();
        let archive = crate::archive::read(&bytes, &mut sink).expect("it is a readable archive");

        let mut seen = 0;
        for entry in archive.entries() {
            if entry.is_directory() {
                continue;
            }
            assert_eq!(
                entry.compression,
                crate::archive::Compression::Other(crate::packer::AES_METHOD),
                "{} is not locked",
                entry.name
            );
            let held = crate::packer::open_entry(&archive, &bytes, entry, "a long enough password")
                .unwrap_or_else(|why| panic!("{} did not open: {}", entry.name, why.message));
            assert_eq!(
                held,
                std::fs::read(directory.join(&entry.name)).unwrap(),
                "{} came back changed",
                entry.name
            );

            assert_eq!(
                crate::packer::open_entry(&archive, &bytes, entry, "the wrong one")
                    .expect_err("a wrong password is refused")
                    .code,
                "EZ021"
            );
            assert_eq!(
                crate::packer::open_entry(&archive, &bytes, entry, "")
                    .expect_err("no password at all is refused")
                    .code,
                "EZ023"
            );
            seen += 1;
        }
        assert_eq!(seen, 3, "every file is locked, not only the first");

        if let Some((passed, said)) = tool_runs("unzip", &["-l", into.to_str().unwrap()]) {
            assert!(
                passed && said.contains("Held/first.txt"),
                "unzip could not read the directory of a locked archive:\n{said}"
            );
        }

        eprintln!(
            "pack: three entries locked with AES-256, opened by the password and by nothing else"
        );
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_zip_locked_the_old_way_by_somebody_else_still_opens() {
        let directory = temp_directory("omni-pack-legacy");
        std::fs::create_dir_all(&directory).expect("the folder is made");
        let short = "a line, and then another\n";
        let long = "x".repeat(4_000);
        std::fs::write(directory.join("Note.txt"), short).expect("the note is written");
        std::fs::write(directory.join("Long.txt"), &long).expect("the long file is written");
        let into = directory.join("Locked.zip");

        let Some((passed, said)) = tool_runs(
            "zip",
            &[
                "-q",
                "-j",
                "-P",
                "hunter2",
                into.to_str().unwrap(),
                directory.join("Note.txt").to_str().unwrap(),
                directory.join("Long.txt").to_str().unwrap(),
            ],
        ) else {
            eprintln!("pack: zip is not here to write an old-style locked archive");
            std::fs::remove_dir_all(&directory).ok();
            return;
        };
        assert!(passed, "zip refused to write the archive:\n{said}");

        let bytes = std::fs::read(&into).expect("the archive is on disk");
        let mut sink = crate::diag::Sink::new();
        assert!(
            crate::archive::read(&bytes, &mut sink).is_none(),
            "a locked archive is still refused by the reader that refuses locks"
        );
        let mut sink = crate::diag::Sink::new();
        let archive =
            crate::archive::read_locked(&bytes, &mut sink).expect("it is a readable archive");

        let mut seen = 0;
        for entry in archive.entries() {
            if entry.is_directory() {
                continue;
            }
            assert!(entry.locked, "{} is not marked locked", entry.name);
            let held = crate::packer::open_entry(&archive, &bytes, entry, "hunter2")
                .unwrap_or_else(|why| panic!("{} did not open: {}", entry.name, why.message));
            assert_eq!(
                held,
                std::fs::read(directory.join(&entry.name)).unwrap(),
                "{} came back changed",
                entry.name
            );
            assert_eq!(
                crate::packer::open_entry(&archive, &bytes, entry, "")
                    .expect_err("no password at all is refused")
                    .code,
                "EZ023"
            );
            assert_eq!(
                crate::packer::open_entry(&archive, &bytes, entry, "not the one")
                    .expect_err("a wrong password is refused")
                    .code,
                "EZ026"
            );
            seen += 1;
        }
        assert_eq!(seen, 2, "both files are read back");

        eprintln!("pack: a zip locked by zip -P opens, stored and squeezed alike");
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_sha1_keyed_hash_answers_what_rfc_2202_publishes() {
        let held = crate::cipher::hmac_sha1(&[0x0b; 20], b"Hi There");
        assert_eq!(
            held.iter().map(|b| format!("{b:02x}")).collect::<String>(),
            "b617318655057264e28bc0b6fb378c8ef146be00"
        );

        let held = crate::cipher::hmac_sha1(b"Jefe", b"what do ya want for nothing?");
        assert_eq!(
            held.iter().map(|b| format!("{b:02x}")).collect::<String>(),
            "effcdf6ae5eb2fa2d27416d5f184df9c259a7c79"
        );

        eprintln!("hmac-sha1: two published cases answered byte for byte");
    }

    #[test]
    fn the_sha1_key_derivation_answers_what_rfc_6070_publishes() {
        for (iterations, length, wanted) in [
            (1u32, 20usize, "0c60c80f961f0e71f3a9b524af6012062fe037a6"),
            (2, 20, "ea6c014dc72d6f8ccd1ed92ace1d41f0d8de8957"),
            (4096, 20, "4b007901b765489abead49d926f721d065a429c1"),
        ] {
            let held = crate::cipher::pbkdf2_sha1(b"password", b"salt", iterations, length)
                .expect("the derivation is asked for a sane length");
            assert_eq!(
                held.iter().map(|b| format!("{b:02x}")).collect::<String>(),
                wanted,
                "iterations: {iterations}"
            );
        }

        assert!(crate::cipher::pbkdf2_sha1(b"p", b"s", 0, 20).is_err());
        assert!(crate::cipher::pbkdf2_sha1(b"p", b"s", 1, 0).is_err());

        eprintln!("pbkdf2-sha1: three published cases answered byte for byte");
    }

    #[test]
    fn the_counter_stream_is_its_own_inverse_and_walks_past_one_block() {
        let key = [0x42u8; crate::cipher::KEY_BYTES];
        let plain: Vec<u8> = (0..200u32).map(|one| (one % 251) as u8).collect();

        let mut held = plain.clone();
        crate::cipher::counter_stream(&key, 1, &mut held);
        assert_ne!(held, plain, "the stream has to change what it covers");

        crate::cipher::counter_stream(&key, 1, &mut held);
        assert_eq!(held, plain, "running it again puts every byte back");

        let mut first = plain.clone();
        crate::cipher::counter_stream(&key, 1, &mut first);
        let mut shifted = plain.clone();
        crate::cipher::counter_stream(&key, 2, &mut shifted);
        assert_ne!(first, shifted, "a different counter is a different stream");

        let mut short = plain[..16].to_vec();
        crate::cipher::counter_stream(&key, 1, &mut short);
        assert_eq!(
            short,
            first[..16].to_vec(),
            "the first block does not depend on what follows it"
        );

        eprintln!("aes-ctr: 200 bytes over thirteen blocks, reversible, counter-dependent");
    }

    #[test]
    fn the_substitution_is_computed_and_answers_what_the_table_would() {
        let (sbox, inverse) = crate::cipher::table_substitution();

        for value in 0..=255u8 {
            let (forward, backward) = crate::cipher::computed_substitution(value);
            assert_eq!(
                forward, sbox[value as usize],
                "substituting {value:#04x} computed {forward:#04x}, the table says {:#04x}",
                sbox[value as usize]
            );
            assert_eq!(
                backward, inverse[value as usize],
                "undoing {value:#04x} computed {backward:#04x}, the table says {:#04x}",
                inverse[value as usize]
            );
        }

        for value in 0..=255u8 {
            let (forward, _) = crate::cipher::computed_substitution(value);
            let (_, back) = crate::cipher::computed_substitution(forward);
            assert_eq!(back, value, "{value:#04x} did not survive the round trip");
        }

        eprintln!("cipher: 256 bytes substituted by arithmetic, none by table lookup");
    }

    #[test]
    fn a_tag_is_compared_without_saying_where_it_parted() {
        assert!(crate::cipher::same_bytes(b"", b""));
        assert!(crate::cipher::same_bytes(&[1, 2, 3], &[1, 2, 3]));
        assert!(!crate::cipher::same_bytes(&[1, 2, 3], &[1, 2]));
        assert!(!crate::cipher::same_bytes(&[1, 2, 3], &[9, 2, 3]));
        assert!(!crate::cipher::same_bytes(&[1, 2, 3], &[1, 2, 9]));

        let base = [0x5au8; 32];
        for position in 0..base.len() {
            for flip in 1..=255u8 {
                let mut other = base;
                other[position] ^= flip;
                assert!(
                    !crate::cipher::same_bytes(&base, &other),
                    "a difference at byte {position} was missed"
                );
            }
        }
    }

