    #[test]
    fn a_name_being_typed_finds_the_types_it_could_be() {
        let directory = temp_directory("omni-symbols");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Named".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");
        crate::workspace::write_text(
            &root,
            "Java/com/tr/yt/Cabinet.java",
            "package com.tr.yt;\npublic class Cabinet {\n}\nclass CabinetDrawer {\n}\n",
        )
        .unwrap();

        let exact = crate::symbols::matching(&root, "TextView").unwrap();
        assert_eq!(
            exact.first().map(|held| held.qualified.as_str()),
            Some("android.widget.TextView"),
            "got {:?}",
            exact
                .iter()
                .take(4)
                .map(|h| &h.qualified)
                .collect::<Vec<_>>()
        );
        assert_eq!(exact[0].from, crate::symbols::From::Platform);
        assert_eq!(exact[0].package, "android.widget");

        let starting = crate::symbols::matching(&root, "Bitmap").unwrap();
        assert_eq!(
            starting.first().map(|held| held.simple.as_str()),
            Some("Bitmap"),
            "got {:?}",
            starting
                .iter()
                .take(4)
                .map(|h| &h.simple)
                .collect::<Vec<_>>()
        );
        assert!(
            starting
                .iter()
                .any(|held| held.qualified == "android.graphics.BitmapFactory"),
            "a name starting with it must be offered too"
        );

        let initials = crate::symbols::matching(&root, "TV").unwrap();
        assert!(
            initials
                .iter()
                .any(|held| held.qualified == "android.widget.TextView"),
            "TV must reach TextView: {:?}",
            initials
                .iter()
                .take(6)
                .map(|h| &h.simple)
                .collect::<Vec<_>>()
        );

        let mine = crate::symbols::matching(&root, "Cabinet").unwrap();
        let first = mine.first().expect("the project's own type");
        assert_eq!(first.qualified, "com.tr.yt.Cabinet");
        assert_eq!(first.from, crate::symbols::From::Project);
        assert_eq!(first.path, "Java/com/tr/yt/Cabinet.java");
        assert!(
            mine.iter()
                .any(|held| held.qualified == "com.tr.yt.CabinetDrawer"),
            "the second type in a file counts as much as the first"
        );

        let (path, line) =
            crate::symbols::where_written(&root, "com.tr.yt.Cabinet").expect("it is written here");
        assert_eq!(path, "Java/com/tr/yt/Cabinet.java");
        assert_eq!(line, 2);

        assert!(crate::symbols::where_written(&root, "android.widget.TextView").is_none());

        let everything = crate::symbols::matching(&root, "").unwrap();
        assert_eq!(everything.len(), crate::symbols::MOST);

        assert!(crate::symbols::matching(&root, "Qzzxwv")
            .unwrap()
            .is_empty());

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_type_this_offers_is_one_an_import_of_it_compiles() {
        let directory = temp_directory("omni-symbols-compile");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Named".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");

        for typed in ["ArrayList", "TextView", "Bundle", "Intent"] {
            let offered = crate::symbols::matching(&root, typed).unwrap();
            let best = offered
                .iter()
                .find(|held| held.simple == typed)
                .unwrap_or_else(|| panic!("{typed} was not offered"));

            let source = format!(
                "package com.tr.yt;\nimport {};\npublic class Holds{typed} {{\n    {typed} held;\n}}\n",
                best.qualified
            );
            let produced =
                crate::compilers::java::compile(&source, &crate::compilers::java::Classpath::new());
            assert!(
                produced.is_ok(),
                "importing {} did not compile: {:?}",
                best.qualified,
                produced.err()
            );
        }

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_bridge_offers_names_and_says_where_one_is_written() {
        let directory = temp_directory("omni-symbols-bridge");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Named".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");
        crate::workspace::write_text(
            &root,
            "Java/com/tr/yt/Ledger.java",
            "package com.tr.yt;\n\npublic class Ledger {\n}\n",
        )
        .unwrap();

        let read = |ptr: *mut std::os::raw::c_char| {
            assert!(!ptr.is_null());
            let held = unsafe { std::ffi::CStr::from_ptr(ptr) }
                .to_string_lossy()
                .into_owned();
            unsafe { crate::ffi::omni_string_free(ptr) };
            held
        };
        let root_c = std::ffi::CString::new(root.clone()).unwrap();

        let needle = std::ffi::CString::new("Ledger").unwrap();
        let answer = read(unsafe { crate::ffi::omni_symbols(root_c.as_ptr(), needle.as_ptr()) });
        assert!(is_structurally_valid(&answer), "{answer}");
        assert!(answer.contains("\"found\":true"), "{answer}");
        assert!(
            answer.contains("\"qualified\":\"com.tr.yt.Ledger\""),
            "{answer}"
        );
        assert!(answer.contains("\"from\":\"project\""), "{answer}");
        assert!(answer.contains("Java/com/tr/yt/Ledger.java"), "{answer}");

        let named = std::ffi::CString::new("com.tr.yt.Ledger").unwrap();
        let where_it_is =
            read(unsafe { crate::ffi::omni_where_written(root_c.as_ptr(), named.as_ptr()) });
        assert!(is_structurally_valid(&where_it_is), "{where_it_is}");
        assert!(where_it_is.contains("\"written\":true"), "{where_it_is}");
        assert!(where_it_is.contains("\"line\":3"), "{where_it_is}");

        let platform = std::ffi::CString::new("android.widget.TextView").unwrap();
        let nowhere =
            read(unsafe { crate::ffi::omni_where_written(root_c.as_ptr(), platform.as_ptr()) });
        assert!(nowhere.contains("\"written\":false"), "{nowhere}");

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn source_this_build_cannot_compile_stops_it_rather_than_being_dropped() {
        let directory = temp_directory("omni-uncompiled");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Mixed".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");

        let clear = crate::builder::check(&root);
        assert!(clear.refusal.is_none(), "{:?}", clear.refusal);
        assert!(crate::builder::uncompiled_source(&root).is_empty());

        crate::workspace::write_text(
            &root,
            "Kotlin/com/tr/yt/Screen.kt",
            "package com.tr.yt

class Screen
",
        )
        .unwrap();

        let found = crate::builder::uncompiled_source(&root);
        assert_eq!(found.len(), 1);
        assert_eq!(found[0].0, "kotlin");
        assert_eq!(found[0].1, "Kotlin/com/tr/yt/Screen.kt");

        let refused = crate::builder::check(&root);
        let refusal = refused.refusal.expect("it must refuse");
        assert_eq!(refusal.code, "EB058");
        assert!(
            refusal
                .context
                .iter()
                .any(|line| line.contains("Kotlin/com/tr/yt/Screen.kt")),
            "the refusal names the file: {:?}",
            refusal.context
        );
        assert!(
            refusal
                .context
                .iter()
                .any(|line| line.starts_with("Compiled here:") && line.contains("java")),
            "and says what is compiled: {:?}",
            refusal.context
        );

        assert_eq!(
            crate::builder::from_project(&root)
                .expect_err("the build refuses")
                .code,
            "EB058"
        );

        let bin = directory.join("bin").to_str().unwrap().to_string();
        crate::workspace::remove(&root, "Kotlin/com/tr/yt/Screen.kt", &bin, 1_800_000_000).unwrap();
        assert!(crate::builder::check(&root).refusal.is_none());

        std::fs::remove_dir_all(&directory).ok();
    }

