    #[test]
    fn every_rule_the_policy_applies_is_one_it_lists() {
        let source = std::fs::read_to_string("Builder.rs").expect("this file must be here");
        let at = source
            .find("pub fn inspect_manifest(root: &Element) -> Report {")
            .expect("the inspection is here");
        let end = source[at..]
            .find("\n    pub fn emit(")
            .expect("and it ends")
            + at;
        let body = &source[at..end];

        let mut applied: Vec<String> = Vec::new();
        let mut rest = body;
        while let Some(found) = rest.find("code: \"") {
            let after = &rest[found + 7..];
            let close = after.find('"').expect("a code is quoted");
            applied.push(after[..close].to_string());
            rest = &after[close..];
        }
        applied.sort();
        applied.dedup();

        let listed: Vec<String> = crate::guard::RULES
            .iter()
            .map(|(code, _, _)| (*code).to_string())
            .collect();
        let mut sorted = listed.clone();
        sorted.sort();
        sorted.dedup();

        assert_eq!(
            sorted, applied,
            "the listed rules and the applied rules have drifted apart"
        );
        assert_eq!(
            listed.len(),
            crate::guard::RULES.len(),
            "a rule is listed twice"
        );

        let mut sink = Sink::new();
        let manifest = crate::xml::parse(
            "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" \
             package=\"com.tr.yt\"><uses-sdk android:minSdkVersion=\"30\"/>\
             <application/></manifest>",
            "AndroidManifest.xml",
            &mut sink,
        )
        .expect("it must parse");
        let report = crate::guard::inspect_manifest(&manifest);
        assert_eq!(
            report.rules_applied,
            crate::guard::RULES.len(),
            "the policy applied {} rules and lists {}",
            report.rules_applied,
            crate::guard::RULES.len()
        );

        for (code, rule, says) in crate::guard::RULES {
            assert!(code.starts_with("EG"), "{code}");
            assert!(rule.contains('-'), "{rule}");
            assert!(says.len() > 30, "{code} says too little: {says}");
            assert!(says.ends_with('.'), "{code} does not finish its sentence");
        }
    }

    #[test]
    fn a_check_says_what_the_policy_would_refuse() {
        let directory = temp_directory("omni-check-policy");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Guarded".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");

        let clear = crate::builder::check(&root);
        let policy = clear.policy.expect("a project that reads has a verdict");
        assert_eq!(policy.verdict(), crate::guard::Verdict::Passed);
        assert_eq!(policy.rules_applied, crate::guard::RULES.len());

        let manifest = crate::workspace::read_text(&root, "AndroidManifest.xml").unwrap();
        let opened = manifest.replace("<application", "<application android:debuggable=\"true\"");
        assert_ne!(opened, manifest, "the manifest must have an application");
        crate::workspace::write_text(&root, "AndroidManifest.xml", &opened).unwrap();

        let refused = crate::builder::check(&root);
        let policy = refused.policy.expect("a verdict");
        assert_eq!(policy.verdict(), crate::guard::Verdict::Refused);
        assert!(crate::guard::fired(&policy, "EG001"));
        assert!(!crate::guard::fired(&policy, "EG002"));

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_resource_named_like_a_style_becomes_a_field_that_compiles() {
        assert_eq!(
            crate::builder::r_field("Theme.App.Light"),
            "Theme_App_Light"
        );
        assert_eq!(crate::builder::r_field("some-name"), "some_name");
        assert_eq!(crate::builder::r_field("android:one"), "android_one");
        assert_eq!(crate::builder::r_field("plain_name"), "plain_name");
        assert_eq!(crate::builder::r_field("app_name"), "app_name");

        let directory = temp_directory("omni-r-field");
        let root = directory.to_str().unwrap().to_string();
        crate::scaffold::create(
            &root,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Styled".to_string(),
                languages: vec!["java".to_string()],
                ..Default::default()
            },
        )
        .expect("the project must be made");
        crate::workspace::write_text(
            &root,
            "Res/values/styles.xml",
            "<resources>\n\
             \x20 <style name=\"Theme.App\">\n\
             \x20   <item name=\"android:textSize\">14sp</item>\n\
             \x20 </style>\n\
             \x20 <style name=\"Theme.App.Light\" parent=\"Theme.App\">\n\
             \x20   <item name=\"android:textColor\">#FF000000</item>\n\
             \x20 </style>\n\
             </resources>\n",
        )
        .unwrap();

        let project = crate::builder::from_project(&root).expect("it must read");
        assert!(project.code.len() > 1, "the R class and the activity");

        let mut sink = Sink::new();
        let table = crate::builder::compile_resources_for_test(&project, &mut sink)
            .unwrap()
            .unwrap();
        let source = crate::builder::r_source("com.tr.yt", &table.compiled);
        assert!(source.contains("Theme_App_Light"), "{source}");
        assert!(!source.contains("Theme.App.Light ="), "{source}");

        assert!(table
            .compiled
            .entries()
            .iter()
            .any(|entry| entry.name == "Theme.App.Light"));

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_resources_a_real_application_ships_come_out_as_aapt2_makes_them() {
        let (Some(aapt2), Some(jar)) = (find_build_tool("aapt2"), android_jar()) else {
            assert!(
                std::env::var("OMNI_REQUIRE_AXML_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_AXML_CONFORMANCE is set but aapt2 or android.jar is missing"
            );
            eprintln!("resources: aapt2 or android.jar is not available here");
            return;
        };

        let directory = temp_directory("omni-real-resources");
        let root = directory.join("project");
        let folder = root.to_str().unwrap().to_string();
        crate::scaffold::create(
            &folder,
            &crate::scaffold::Spec {
                package: "com.tr.yt".to_string(),
                label: "Real".to_string(),
                languages: vec!["java".to_string()],
                min_sdk: 30,
                target_sdk: 36,
                ..Default::default()
            },
        )
        .expect("the project must be made");

        let files: &[(&str, &str)] = &[
            (
                "drawable/mark.xml",
                "<vector xmlns:android=\"http://schemas.android.com/apk/res/android\"\n\
                 \x20   android:width=\"24dp\" android:height=\"24dp\"\n\
                 \x20   android:viewportWidth=\"24\" android:viewportHeight=\"24\">\n\
                 \x20 <path android:fillColor=\"#FF35B7FF\"\n\
                 \x20       android:pathData=\"M12,2L2,22h20L12,2z\" />\n\
                 </vector>\n",
            ),
            (
                "color/tinted.xml",
                "<selector xmlns:android=\"http://schemas.android.com/apk/res/android\">\n\
                 \x20 <item android:state_pressed=\"true\" android:color=\"#FF2FE0B0\" />\n\
                 \x20 <item android:state_enabled=\"false\" android:color=\"#806F7F94\" />\n\
                 \x20 <item android:color=\"#FFDCE9F5\" />\n\
                 </selector>\n",
            ),
            (
                "values/colours.xml",
                "<resources>\n\
                 \x20 <color name=\"ground\">#FF04070C</color>\n\
                 \x20 <color name=\"accent\">#FF35B7FF</color>\n\
                 </resources>\n",
            ),
            (
                "values/sizes.xml",
                "<resources>\n\
                 \x20 <dimen name=\"gutter\">16dp</dimen>\n\
                 \x20 <dimen name=\"reading\">14sp</dimen>\n\
                 \x20 <integer name=\"columns\">3</integer>\n\
                 \x20 <bool name=\"wide\">false</bool>\n\
                 </resources>\n",
            ),
            (
                "values/styles.xml",
                "<resources>\n\
                 \x20 <style name=\"Plain\">\n\
                 \x20   <item name=\"android:textColor\">#FFDCE9F5</item>\n\
                 \x20   <item name=\"android:textSize\">14sp</item>\n\
                 \x20 </style>\n\
                 \x20 <style name=\"Plain.Loud\" parent=\"Plain\">\n\
                 \x20   <item name=\"android:textStyle\">bold</item>\n\
                 \x20 </style>\n\
                 \x20 <style name=\"OmniTheme\" parent=\"android:Theme.Material.NoActionBar\">\n\
                 \x20   <item name=\"android:windowBackground\">@color/ground</item>\n\
                 \x20   <item name=\"android:colorAccent\">@color/accent</item>\n\
                 \x20 </style>\n\
                 </resources>\n",
            ),
            (
                "layout/screen.xml",
                "<LinearLayout xmlns:android=\"http://schemas.android.com/apk/res/android\"\n\
                 \x20   android:layout_width=\"match_parent\"\n\
                 \x20   android:layout_height=\"match_parent\"\n\
                 \x20   android:orientation=\"vertical\"\n\
                 \x20   android:padding=\"@dimen/gutter\"\n\
                 \x20   android:background=\"@color/ground\">\n\
                 \x20 <TextView android:id=\"@+id/heading\"\n\
                 \x20     android:layout_width=\"wrap_content\"\n\
                 \x20     android:layout_height=\"wrap_content\"\n\
                 \x20     android:textColor=\"@color/tinted\"\n\
                 \x20     android:textSize=\"@dimen/reading\"\n\
                 \x20     android:text=\"@string/app_name\" />\n\
                 \x20 <ImageView android:layout_width=\"24dp\"\n\
                 \x20     android:layout_height=\"24dp\"\n\
                 \x20     android:src=\"@drawable/mark\" />\n\
                 </LinearLayout>\n",
            ),
        ];

        for (name, body) in files {
            crate::workspace::write_text(
                &folder,
                &format!("{}/{name}", crate::scaffold::RES_FOLDER),
                body,
            )
            .unwrap();
        }

        let mine = crate::builder::from_project(&folder).expect("the project must read");
        let mut sink = Sink::new();
        let table = crate::builder::compile_resources_for_test(&mine, &mut sink)
            .expect("the resources must compile")
            .expect("and there must be some");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let named: Vec<&str> = table
            .compiled
            .entries()
            .iter()
            .map(|entry| entry.name.as_str())
            .collect();
        for wanted in [
            "mark",
            "tinted",
            "ground",
            "accent",
            "gutter",
            "reading",
            "columns",
            "wide",
            "Plain",
            "Plain.Loud",
            "OmniTheme",
            "screen",
            "heading",
        ] {
            assert!(
                named.contains(&wanted),
                "{wanted} is not in the table this build wrote: {named:?}"
            );
        }

        let theirs = directory.join("theirs");
        std::fs::create_dir_all(&theirs).unwrap();
        let compiled = std::process::Command::new(&aapt2)
            .args([
                "compile",
                "--dir",
                root.join(crate::scaffold::RES_FOLDER).to_str().unwrap(),
                "-o",
                theirs.join("compiled.zip").to_str().unwrap(),
            ])
            .output()
            .unwrap();
        assert!(
            compiled.status.success(),
            "aapt2 would not compile what this build accepted:\n{}",
            String::from_utf8_lossy(&compiled.stderr)
        );

        let linked = std::process::Command::new(&aapt2)
            .args([
                "link",
                "--manifest",
                root.join("AndroidManifest.xml").to_str().unwrap(),
                "-I",
                jar.to_str().unwrap(),
                "-o",
                theirs.join("theirs.apk").to_str().unwrap(),
                theirs.join("compiled.zip").to_str().unwrap(),
            ])
            .output()
            .unwrap();
        assert!(
            linked.status.success(),
            "aapt2 would not link it:\n{}",
            String::from_utf8_lossy(&linked.stderr)
        );

        let package = std::fs::read(theirs.join("theirs.apk")).unwrap();
        let mut reading = Sink::new();
        let archive = crate::archive::read(&package, &mut reading).expect("their package reads");
        let entry = archive
            .entries()
            .iter()
            .find(|held| held.name == "res/layout/screen.xml")
            .expect("aapt2 wrote the layout");
        let bytes = crate::builder::entry_bytes(&package, entry, "theirs.apk").unwrap();
        let their_layout = crate::axml::decode(&bytes).expect("and it reads back");

        let ours = table
            .files
            .iter()
            .find(|(name, _)| name == "res/layout/screen.xml")
            .map(|(_, bytes)| bytes.clone())
            .expect("this build wrote the layout too");
        let our_layout = crate::axml::decode(&ours).expect("and this build's reads back");

        assert_eq!(our_layout.name, their_layout.name);
        assert_eq!(
            our_layout.children.len(),
            their_layout.children.len(),
            "a different number of views came out"
        );

        for (ours, theirs) in our_layout
            .attributes
            .iter()
            .zip(their_layout.attributes.iter())
        {
            assert_eq!(ours.id, theirs.id, "{} against {}", ours.name, theirs.name);
            assert_eq!(
                ours.kind, theirs.kind,
                "{} came out as a different kind of value",
                ours.name
            );
            if ours.kind != 0x01 {
                assert_eq!(
                    ours.value, theirs.value,
                    "{} says something else",
                    ours.name
                );
            }
        }

        eprintln!(
            "resources: {} entries, and aapt2 agrees on the layout attribute for attribute",
            table.compiled.entries().len()
        );
        std::fs::remove_dir_all(&directory).ok();
    }

