    #[test]
    fn the_binary_xml_reader_survives_arbitrary_input() {
        let source = "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" \
             package=\"com.tr.yt\"><application android:label=\"Omni\"/></manifest>";
        let mut sink = Sink::new();
        let parsed =
            crate::xml::parse(source, "AndroidManifest.xml", &mut sink).expect("it must parse");
        let bytes = crate::axml::encode(&parsed).expect("it must encode");

        let mut seed = 0x1234_5678_9abc_def0u64;
        for _ in 0..4_000 {
            let mut damaged = bytes.clone();
            let mutations = (xorshift(&mut seed) % 5) + 1;
            for _ in 0..mutations {
                let position = (xorshift(&mut seed) as usize) % damaged.len();
                damaged[position] = (xorshift(&mut seed) & 0xff) as u8;
            }

            let _ = crate::axml::decode(&damaged);
        }

        assert!(crate::axml::decode(&[]).is_err());
        assert!(crate::axml::decode(&[0u8; 8]).is_err());
    }

    #[test]
    fn what_aapt2_wrote_reads_back_the_same_as_what_this_wrote() {
        let (Some(aapt2), Some(jar)) = (find_build_tool("aapt2"), android_jar()) else {
            assert!(
                std::env::var("OMNI_REQUIRE_AXML_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_AXML_CONFORMANCE is set but aapt2 or android.jar is missing"
            );
            eprintln!("binary xml: aapt2 or android.jar is not available here");
            return;
        };

        let directory = temp_directory("omni-axml-read");
        let source = "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\"\n\
             \x20   package=\"com.tr.yt\"\n\
             \x20   android:versionCode=\"7\"\n\
             \x20   android:versionName=\"1.2.3\">\n\
             \x20 <uses-sdk android:minSdkVersion=\"30\" android:targetSdkVersion=\"36\"/>\n\
             \x20 <application android:label=\"Omni\" android:hardwareAccelerated=\"true\">\n\
             \x20   <activity android:name=\".Main\" android:exported=\"true\"/>\n\
             \x20 </application>\n\
             </manifest>\n";
        let written = directory.join("AndroidManifest.xml");
        std::fs::write(&written, source).unwrap();

        let out = directory.join("theirs.apk");
        let made = std::process::Command::new(&aapt2)
            .args([
                "link",
                "--manifest",
                written.to_str().unwrap(),
                "-I",
                jar.to_str().unwrap(),
                "-o",
                out.to_str().unwrap(),
            ])
            .output()
            .unwrap();
        assert!(
            made.status.success(),
            "{}",
            String::from_utf8_lossy(&made.stderr)
        );

        let package = std::fs::read(&out).unwrap();
        let mut sink = Sink::new();
        let archive = crate::archive::read(&package, &mut sink).expect("aapt2 wrote an archive");
        let entry = archive
            .entries()
            .iter()
            .find(|held| held.name == "AndroidManifest.xml")
            .expect("with a manifest in it");
        let theirs = crate::builder::entry_bytes(&package, entry, "theirs.apk").unwrap();

        let read = crate::axml::decode(&theirs).expect("aapt2's manifest must read");
        assert_eq!(read.name, "manifest");
        assert_eq!(read.attribute("package"), Some("com.tr.yt"));
        assert_eq!(read.attribute("versionName"), Some("1.2.3"));
        assert_eq!(read.attribute("versionCode"), Some("7"));

        let sdk = read.children_named("uses-sdk").next().expect("a uses-sdk");
        assert_eq!(sdk.attribute("minSdkVersion"), Some("30"));

        let application = read
            .children_named("application")
            .next()
            .expect("an application");
        assert_eq!(application.attribute("label"), Some("Omni"));
        assert_eq!(application.attribute("hardwareAccelerated"), Some("true"));
        let activity = application
            .children_named("activity")
            .next()
            .expect("an activity");
        assert_eq!(activity.attribute("exported"), Some("true"));
        assert_eq!(activity.attribute("name"), Some(".Main"));

        eprintln!("binary xml: aapt2's own manifest read back by this build");
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn every_attribute_identifier_is_the_one_aapt2_uses() {
        let (Some(aapt2), Some(jar)) = (find_build_tool("aapt2"), android_jar()) else {
            eprintln!("axml conformance: aapt2 or android.jar is not available here");
            return;
        };

        let directory = temp_directory("axml-ids");
        let source = directory.join("AndroidManifest.xml");
        std::fs::write(&source, ATTRIBUTE_PROBE_MANIFEST).unwrap();

        let out = directory.join("probe.apk");
        let linked = std::process::Command::new(&aapt2)
            .args([
                "link",
                "--manifest",
                source.to_str().unwrap(),
                "-o",
                out.to_str().unwrap(),
                "-I",
                jar.to_str().unwrap(),
            ])
            .output()
            .unwrap();
        assert!(
            linked.status.success(),
            "aapt2 link failed: {}",
            String::from_utf8_lossy(&linked.stderr)
        );

        let dumped = std::process::Command::new(&aapt2)
            .args([
                "dump",
                "xmltree",
                out.to_str().unwrap(),
                "--file",
                "AndroidManifest.xml",
            ])
            .output()
            .unwrap();
        let text = String::from_utf8_lossy(&dumped.stdout).to_string();

        for (name, id) in axml::ATTRIBUTES {
            let marker = format!("android:{name}(0x{id:08x})");
            assert!(
                text.contains(&marker),
                "aapt2 does not agree that {name} is 0x{id:08x}"
            );
        }
        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "axml conformance: {} attribute identifiers agree with aapt2",
            axml::ATTRIBUTES.len()
        );
    }

    #[test]
    fn the_binary_xml_this_build_writes_is_read_by_aapt2() {
        let (root, sink) = parse_xml(PROBE_MANIFEST);
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        let root = root.expect("the manifest must parse");
        let encoded = axml::encode(&root).expect("the manifest must encode");

        let Some(aapt2) = find_build_tool("aapt2") else {
            assert!(
                std::env::var("OMNI_REQUIRE_AXML_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_AXML_CONFORMANCE is set but aapt2 is missing, so the \
                 manifest this build writes was never checked against it"
            );
            eprintln!("axml conformance: aapt2 is not available here");
            return;
        };

        let mut builder = ArchiveBuilder::for_android();
        builder.add("AndroidManifest.xml", encoded).unwrap();
        let apk = builder.finish().unwrap();

        let directory = temp_directory("axml-dump");
        let path = directory.join("ours.apk");
        std::fs::write(&path, &apk).unwrap();

        let dumped = std::process::Command::new(&aapt2)
            .args([
                "dump",
                "xmltree",
                path.to_str().unwrap(),
                "--file",
                "AndroidManifest.xml",
            ])
            .output()
            .unwrap();
        let text = String::from_utf8_lossy(&dumped.stdout).to_string();
        assert!(
            dumped.status.success(),
            "aapt2 refused what this build wrote: {}\n{text}",
            String::from_utf8_lossy(&dumped.stderr)
        );

        let expected = [
            "N: android=http://schemas.android.com/apk/res/android",
            "E: manifest",
            "A: package=\"com.omni.probe\"",
            "E: uses-sdk",
            "android:minSdkVersion(0x0101020c)=30",
            "android:targetSdkVersion(0x01010270)=36",
            "E: uses-permission",
            "android:name(0x01010003)=\"android.permission.INTERNET\"",
            "E: application",
            "android:label(0x01010001)=\"Omni\"",
            "android:allowBackup(0x01010280)=false",
            "android:supportsRtl(0x010103af)=true",
            "android:extractNativeLibs(0x010104ea)=false",
            "android:theme(0x01010000)=@0x7f060000",
            "E: activity",
            "android:name(0x01010003)=\"com.omni.probe.Main\"",
            "android:exported(0x01010010)=true",
        ];
        for line in expected {
            assert!(
                text.contains(line),
                "aapt2 did not report {line:?}:\n{text}"
            );
        }

        std::fs::remove_dir_all(&directory).ok();
        eprintln!("axml conformance: aapt2 read the binary XML this build wrote");
    }

