    #[test]
    fn versions_and_editions_are_validated() {
        for (version, ok) in [
            ("1.0.0", true),
            ("10.20.30", true),
            ("1.0", false),
            ("1.0.x", false),
            ("01.0.0", false),
        ] {
            let manifest = format!("[ Project ]\nName = \"A\"\nVersion = \"{version}\"\n");
            let mut sink = Sink::new();
            assert_eq!(
                parse_manifest(&manifest, "com.f", &mut sink).is_some(),
                ok,
                "version: {version}"
            );
        }

        for (edition, ok) in [
            ("01/01/2000", true),
            ("31/12/2026", true),
            ("2000-01-01", false),
            ("1/1/2000", false),
            ("32/01/2000", false),
        ] {
            let manifest = format!("[ Project ]\nName = \"A\"\nEdition = \"{edition}\"\n");
            let mut sink = Sink::new();
            assert_eq!(
                parse_manifest(&manifest, "com.f", &mut sink).is_some(),
                ok,
                "edition: {edition}"
            );
        }
    }

