    #[test]
    fn a_calculator_written_in_java_25_compiles_and_gets_the_answers_right() {
        let produced = compile(A_CALCULATOR, &empty()).expect("the calculator must compile");
        let names: Vec<&str> = produced.iter().map(|(name, _)| name.as_str()).collect();
        for wanted in [
            "com/my/app/Calculator.class",
            "com/my/app/Operator.class",
            "com/my/app/Piece.class",
            "com/my/app/Value.class",
            "com/my/app/Node.class",
            "com/my/app/Operation.class",
            "com/my/app/Malformed.class",
            "com/my/app/Reading.class",
            "com/my/app/Named.class",
        ] {
            assert!(
                names.contains(&wanted),
                "{wanted} is missing from {names:?}"
            );
        }

        let read = |file: &str| {
            let (_, bytes) = produced
                .iter()
                .find(|(name, _)| name == file)
                .unwrap_or_else(|| panic!("{file}"));
            crate::jvm::read(bytes).unwrap_or_else(|why| panic!("{file}: {why:?}"))
        };
        assert!(read("com/my/app/Piece.class").access_flags & 0x0200 != 0);
        assert_eq!(
            read("com/my/app/Value.class").superclass.as_deref(),
            Some("java.lang.Record")
        );
        assert!(read("com/my/app/Operator.class").access_flags & 0x4000 != 0);

        for (file, bytes) in &produced {
            let one = file.trim_end_matches(".class");
            match jvm_verifies(one, bytes) {
                None | Some(Verdict::TooOld(_)) => {
                    eprintln!("java: no JVM new enough here to verify the calculator");
                    return;
                }
                Some(Verdict::Refused(said)) => panic!("a real JVM refused {file}:\n{said}"),
                Some(Verdict::Verified) => {}
            }
        }

        match jvm_runs(&produced, "com.my.app.Calculator") {
            None => eprintln!("java: no JVM here to run the calculator"),
            Some(Err(said)) => panic!("a real JVM would not run it:\n{said}"),
            Some(Ok(said)) => assert_eq!(
                said,
                "1 + 2 = 3\n\
             2 + 3 * 4 = 14\n\
             (2 + 3) * 4 = 20\n\
             2 ^ 3 ^ 2 = 512\n\
             -3 + 1 = -2\n\
             10 / 4 = 2.5\n\
             10 % 3 = 1\n\
             7 / 0 = ?a division by zero at 0\n\
             sqrt(16) = 4\n\
             abs(-5) + floor(2.7) + ceil(2.1) = 10\n\
             min(3, 4) * max(3, 4) = 12\n\
             min(1, 2, 3) = ?min takes 2 at 0\n\
             nothing(1) = ?a name this does not know: nothing at 0\n\
             2 + = ?an expression that stops early at -1\n\
             1 $ 2 = ?a character this does not read at 2\n\
             1..2 = ?a second dot in one number at 2\n\
             ((1 + 2) = ?a missing ) at -1\n\
             + - * / % ^\n\
             sqrt abs floor ceil min max\n",
                "what it worked out is not what javac's own build of it works out"
            ),
        }

        let together = vec![
            ("Calculator.java".to_string(), A_CALCULATOR.to_string()),
            ("Screen.java".to_string(), THE_SCREEN_FOR_IT.to_string()),
        ];
        let whole = compile_together(&together, &empty()).expect("the screen must compile too");
        assert!(whole
            .iter()
            .any(|(name, _)| name == "com/my/app/Screen.class"));
        let translated: Vec<_> = whole
            .iter()
            .flat_map(|(file, bytes)| {
                let class = crate::jvm::read(bytes).unwrap_or_else(|_| panic!("read {file}"));
                crate::dalvik::translate_class(&class)
                    .unwrap_or_else(|refused| panic!("{file} to Dalvik: {refused:?}"))
            })
            .collect();
        let dex = crate::dexwrite::write(&translated, &[]).expect("and reach a dex");
        let mut sink = crate::diag::Sink::new();
        crate::dex::read(&dex, &mut sink).expect("which our own reader reads");
        assert_eq!(sink.entries().len(), 0, "{:?}", sink.entries());
        if let Some(said) = dexdump_disassembly(&dex) {
            assert!(said.contains("Calculator"), "dexdump read it back");
        }

        eprintln!(
            "java: a calculator -- {} classes run and right, {} into a {} byte dex",
            produced.len(),
            whole.len(),
            dex.len()
        );
    }

    const A_BOX_OF_ONES_OWN: &str = r####"
import java.util.ArrayList;
import java.util.List;

class Box<T> {
    private T held;

    void put(T one) {
        held = one;
    }

    T get() {
        return held;
    }
}

interface Shelf {
    int LIMIT = 3;

    String label();
}

public class Boxed {
    private int count;

    private String secret() {
        return "kept";
    }

    class Inner {
        String reach() {
            return secret() + count;
        }
    }

    static String fromABox() {
        Box<String> one = new Box<String>();
        one.put("held");
        String out = one.get();
        return out + one.get().length();
    }

    static <T> T firstOf(List<T> given) {
        return given.get(0);
    }

    static int chained() {
        List<List<Integer>> deep = new ArrayList<List<Integer>>();
        List<Integer> inner = new ArrayList<Integer>();
        inner.add(7);
        deep.add(inner);
        return deep.get(0).get(0);
    }

    public static void main(String[] args) {
        Boxed held = new Boxed();
        held.count = 2;
        StringBuilder out = new StringBuilder();
        out.append(fromABox()).append(' ');
        out.append(chained()).append(' ');
        List<String> words = new ArrayList<String>();
        words.add("one");
        String first = firstOf(words);
        out.append(first.length()).append(' ');
        out.append(held.new Inner().reach()).append(' ');
        out.append(Shelf.LIMIT).append(' ');
        Shelf shelf = () -> "shelf";
        out.append(shelf.label()).append(' ');
        System.out.println(out.toString());
    }
}
"####;

    #[test]
    fn a_generic_class_of_ones_own_gives_back_what_it_was_written_holding() {
        let produced = compile(A_BOX_OF_ONES_OWN, &empty()).expect("it must compile");
        for (file, bytes) in &produced {
            let one = file.trim_end_matches(".class");
            match jvm_verifies(one, bytes) {
                None | Some(Verdict::TooOld(_)) => {
                    eprintln!("java: no JVM new enough here to verify a box");
                    return;
                }
                Some(Verdict::Refused(said)) => panic!("a real JVM refused {file}:\n{said}"),
                Some(Verdict::Verified) => {}
            }
        }
        match jvm_runs(&produced, "Boxed") {
            None => eprintln!("java: no JVM here to run a box"),
            Some(Err(said)) => panic!("a real JVM would not run it:\n{said}"),
            Some(Ok(said)) => assert_eq!(
                said.trim(),
                "held4 7 3 kept2 3 shelf",
                "what it printed is not what javac's own build of the same source prints"
            ),
        }
        eprintln!("java: a box of one's own gives back what it was written holding");
    }

    #[test]
    fn a_jar_handed_over_is_a_jar_the_code_may_call_into() {
        let library = r#"
            package com.some.lib;

            public class Greeter {
                private final String who;

                public Greeter(String who) {
                    this.who = who;
                }

                public String greeting() {
                    return "hello " + who;
                }

                public static Greeter of(String who) {
                    return new Greeter(who);
                }
            }
        "#;
        let produced = compile(library, &empty()).expect("the library must compile");

        let mut jar = crate::archive::Builder::new();
        for (name, bytes) in &produced {
            jar.add(name.clone(), bytes.clone()).expect("into the jar");
        }
        let bytes = jar.finish().expect("a jar");

        let mut classpath = empty();
        let learned = classpath.learn_jar(&bytes).expect("and be read back");
        assert_eq!(learned, produced.len());

        let user = r#"
            import com.some.lib.Greeter;

            public class Uses {
                public static void main(String[] args) {
                    System.out.println(Greeter.of("world").greeting());
                }
            }
        "#;
        let (_, held) = compile_one(user, &classpath).expect("calling into it must compile");
        let class = crate::jvm::read(&held).expect("read back");
        let called: Vec<String> = class
            .constants
            .iter()
            .filter_map(|one| match one {
                crate::jvm::Constant::Utf8(text) => Some(text.clone()),
                _ => None,
            })
            .collect();
        assert!(
            called.iter().any(|one| one == "com/some/lib/Greeter"),
            "the call names the class it was handed: {called:?}"
        );

        let mut together = produced.clone();
        together.push(("Uses.class".to_string(), held));
        match jvm_runs(&together, "Uses") {
            None => eprintln!("java: no JVM here to run against a jar"),
            Some(Err(said)) => panic!("a real JVM would not run it:\n{said}"),
            Some(Ok(said)) => assert_eq!(said.trim(), "hello world"),
        }

        let refused = empty()
            .learn_jar(b"not a jar at all")
            .expect_err("that is not an archive");
        assert_eq!(refused.code, "EJ255");

        eprintln!("java: a jar handed over, read, and called into");
    }

    #[test]
    fn the_platform_jar_is_the_whole_android_api() {
        let Some(platform) = crate::builder::platform_jar() else {
            eprintln!("java: no android.jar on this machine");
            return;
        };
        let bytes = std::fs::read(&platform).expect("the platform jar");
        let mut classpath = empty();
        let learned = classpath.learn_jar(&bytes).expect("must be read");
        assert!(
            learned > 1000,
            "a platform jar holds thousands of classes, not {learned}"
        );

        let source = r#"
            package com.my.app;

            import android.app.Activity;
            import android.content.SharedPreferences;
            import android.os.Bundle;
            import android.os.Handler;
            import android.os.Looper;
            import android.widget.ArrayAdapter;
            import android.widget.ListView;
            import android.widget.Spinner;

            import java.text.SimpleDateFormat;
            import java.util.ArrayList;
            import java.util.Calendar;
            import java.util.LinkedHashMap;
            import java.util.List;
            import java.util.Locale;
            import java.util.Map;
            import java.util.concurrent.atomic.AtomicInteger;

            public class Screen extends Activity {
                private final AtomicInteger counted = new AtomicInteger();
                private final Map<String, Integer> seen = new LinkedHashMap<String, Integer>();
                private SharedPreferences settings;
                private Handler onTheMainThread;

                @Override
                protected void onCreate(Bundle state) {
                    super.onCreate(state);
                    settings = getSharedPreferences("screen", MODE_PRIVATE);
                    onTheMainThread = new Handler(Looper.getMainLooper());

                    List<String> rows = new ArrayList<String>();
                    rows.add(stamped());
                    ArrayAdapter<String> adapter = new ArrayAdapter<String>(
                        this, android.R.layout.simple_list_item_1, rows);
                    ListView list = new ListView(this);
                    list.setAdapter(adapter);
                    Spinner pick = new Spinner(this);
                    pick.setAdapter(adapter);
                    setContentView(list);
                }

                String stamped() {
                    SimpleDateFormat shape = new SimpleDateFormat("yyyy-MM-dd", Locale.US);
                    return shape.format(Calendar.getInstance().getTime());
                }

                int remember(String key) {
                    int held = counted.incrementAndGet();
                    seen.put(key, held);
                    settings.edit().putInt(key, held).apply();
                    return seen.get(key);
                }

                void later(final Runnable what) {
                    onTheMainThread.postDelayed(what, 500L);
                }

                // The jar says what its generic classes hand back, and that is
                // read rather than guessed: `getItem` on an
                // `ArrayAdapter<String>` is a String, and a `Map<String,
                // List<Integer>>` gives back a list that gives back an int.
                String generics() {
                    List<String> rows = new ArrayList<String>();
                    rows.add("one");
                    ArrayAdapter<String> adapter = new ArrayAdapter<String>(
                        this, android.R.layout.simple_list_item_1, rows);
                    String first = adapter.getItem(0);

                    Map<String, List<Integer>> deep =
                        new LinkedHashMap<String, List<Integer>>();
                    List<Integer> inner = new ArrayList<Integer>();
                    inner.add(first.length());
                    deep.put("k", inner);
                    int back = deep.get("k").get(0);
                    return first + back + rows.get(0).length();
                }
            }
        "#;
        let produced = compile(source, &classpath).expect("real Android code must compile");
        assert!(produced
            .iter()
            .any(|(name, _)| name == "com/my/app/Screen.class"));

        let translated: Vec<_> = produced
            .iter()
            .flat_map(|(file, held)| {
                let class = crate::jvm::read(held).unwrap_or_else(|_| panic!("read {file}"));
                crate::dalvik::translate_class(&class)
                    .unwrap_or_else(|refused| panic!("{file} to Dalvik: {refused:?}"))
            })
            .collect();
        let dex = crate::dexwrite::write(&translated, &[]).expect("and reach a dex");
        let mut sink = crate::diag::Sink::new();
        crate::dex::read(&dex, &mut sink).expect("which our own reader reads");
        assert_eq!(sink.entries().len(), 0, "{:?}", sink.entries());

        eprintln!("java: {learned} classes from the platform, and code that imports what it likes");
    }

    #[test]
    fn the_java_a_person_writes_against_a_library_gets_the_same_answer_javac_gets() {
        let classpath = empty();
        let source = r#"
            package com.my.app;

            import java.util.ArrayList;
            import java.util.Arrays;
            import java.util.Collections;
            import java.util.Comparator;
            import java.util.HashMap;
            import java.util.List;
            import java.util.Map;
            import java.util.Objects;

            public class Daily {

                static int viaAsList() {
                    return Arrays.asList("a", "bb", "ccc").get(2).length();
                }

                static String viaRequireNonNull(String held) {
                    return Objects.requireNonNull(held).trim();
                }

                static void sortWithAnAnonymousClass(List<String> rows) {
                    Collections.sort(rows, new Comparator<String>() {
                        @Override
                        public int compare(String left, String right) {
                            return left.compareTo(right);
                        }
                    });
                }

                static void sortWithALambda(List<String> rows) {
                    Collections.sort(rows, (left, right) -> left.compareTo(right));
                }

                static String biggest(List<String> rows) {
                    return Collections.max(rows);
                }

                static int mapped() {
                    Map<String, Integer> held = new HashMap<String, Integer>();
                    held.put("a", 1);
                    for (Map.Entry<String, Integer> one : held.entrySet()) {
                        if (one.getKey().equals("a")) {
                            return one.getValue();
                        }
                    }
                    return -1;
                }

                static String joined(List<String> rows) {
                    StringBuilder out = new StringBuilder();
                    for (String one : rows) {
                        out.append(one);
                    }
                    return out.toString();
                }

                public static void main(String[] args) {
                    List<String> rows = new ArrayList<String>(Arrays.asList("pear", "apple"));
                    sortWithAnAnonymousClass(rows);
                    sortWithALambda(rows);
                    System.out.println(
                        viaAsList() + " " + viaRequireNonNull(" x ") + " " + biggest(rows)
                            + " " + mapped() + " " + joined(rows));
                }
            }
        "#;
        let produced = compile(source, &classpath).expect("must compile");
        match jvm_runs(&produced, "com.my.app.Daily") {
            None => eprintln!("java: no JVM here to run an ordinary afternoon's Java"),
            Some(Err(said)) => panic!("{said}"),
            Some(Ok(said)) => {
                assert_eq!(said.trim(), "3 x pear 1 applepear");
                eprintln!("java: an ordinary afternoon's Java, against the platform jar, ran");
            }
        }
    }

    #[test]
    fn a_checked_exception_has_to_be_answered_for() {
        for (source, why) in [
            (
                "import java.io.IOException;
                 public class A {
                     static void risky() throws IOException { }
                     void f() { risky(); }
                 }",
                "a call to one",
            ),
            (
                "import java.io.IOException;
                 public class A {
                     static class B { B() throws IOException { } }
                     void f() { new B(); }
                 }",
                "a `new` of one",
            ),
            (
                "import java.io.IOException;
                 public class A { void f() { throw new IOException(\"no\"); } }",
                "a `throw` of one",
            ),
            (
                "public class A {
                     void f() { java.io.InputStream in = null; in.read(); }
                 }",
                "one the platform declares",
            ),
            (
                "import java.io.IOException;
                 public class A {
                     static void risky() throws IOException { }
                     void f() { try { risky(); } catch (java.io.FileNotFoundException e) { } }
                 }",
                "a `catch` for something narrower",
            ),
        ] {
            let refused = compile(source, &empty())
                .err()
                .unwrap_or_else(|| panic!("{why} must be refused"));
            assert_eq!(refused.code, "EJ256", "{why}: {}", refused.message);
            assert!(refused.suggestion.is_some(), "{why}");
        }

        for (source, why) in [
            (
                "import java.io.IOException;
                 public class A {
                     static void risky() throws IOException { }
                     void f() { try { risky(); } catch (IOException e) { } }
                 }",
                "a `catch` naming it",
            ),
            (
                "import java.io.IOException;
                 public class A {
                     static void risky() throws IOException { }
                     void f() { try { risky(); } catch (Exception e) { } }
                 }",
                "a `catch` naming something above it",
            ),
            (
                "import java.io.IOException;
                 public class A {
                     static void risky() throws IOException { }
                     void f() throws IOException { risky(); }
                 }",
                "a `throws` on the method",
            ),
            (
                "import java.io.IOException;
                 public class A {
                     static void risky() throws IOException { }
                     void f() throws Exception { risky(); }
                 }",
                "a `throws` of something above it",
            ),
            (
                "import java.util.concurrent.Callable;
                 public class A {
                     Callable<String> f() { return () -> { throw new Exception(\"no\"); }; }
                 }",
                "a lambda whose interface says it throws",
            ),
            (
                "public class A { void f() { throw new IllegalStateException(\"fine\"); } }",
                "a RuntimeException, which nobody declares",
            ),
            (
                "public class A { void f() { throw new StackOverflowError(); } }",
                "an Error, which nobody declares",
            ),
        ] {
            compile(source, &empty()).unwrap_or_else(|why| panic!("{why:?} refused {why:?}"));
            let _ = why;
        }
        eprintln!("java: a checked exception is caught, declared, or refused");
    }

